INSERT OR IGNORE INTO verses (id, ref, book, chapter, verse, text, text_normalized, text_html, testament, translation_key, dialect, tags, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(38411, 'Isaiah 10:9', 'Isaiah', 10, 9, 'ما د کرکمیش، کلنو او همدارنګه د ارفاد او حمات ښارونه فتح کړي دي. دمشق او سامره مې هم فتح کړي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_009.mp3', NULL, 1761758823, 1761758823),
(38412, 'Isaiah 10:10', 'Isaiah', 10, 10, 'ما خپل لاس د هغو پاچاهیو د فتح کولو دپاره اوچت کړی چې د بتانو عبادت کوي. هغه پاچاهیو د اورشلیم او سامرې څخه زیات بتان درلودل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_010.mp3', NULL, 1761758823, 1761758823),
(38413, 'Isaiah 10:11', 'Isaiah', 10, 11, 'ما سامره او د هغې ټول بتان له منځه یووړل، خو زه به اورشلیم او د هغه مجسمې چې عبادت ورته کیږي، هم له منځه یوسم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_011.mp3', NULL, 1761758823, 1761758823),
(38414, 'Isaiah 10:12', 'Isaiah', 10, 12, 'کله چې څښتن خپل کارونه د صهیون په غره او اورشلیم کې پای ته ورسوي، نو هغه وخت به د اشور پاچا ته د هغه د ټولو لافو او ټول غرور په خاطر سزا ورکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_012.mp3', NULL, 1761758823, 1761758823),
(38415, 'Isaiah 10:13', 'Isaiah', 10, 13, 'د اشور پاچا لاپې وهي او وایي: «زه د خپلو مټو په زور، پوهې او حکمت سره په جګړو کې بریالی شوم. د هېوادونو ترمنځ مې سرحدونه له منځه یووړل او د هغوی خزانې مې لوټ کړې. لکه د قوي غویي په شان مې د هغو ځایونو پاچاهان د تختونو څخه وغورځول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_013.mp3', NULL, 1761758823, 1761758823),
(38416, 'Isaiah 10:14', 'Isaiah', 10, 14, 'د نړۍ هېوادونه زما دپاره د مرغۍ د ځالې په شان وو. ما د هغوی خزانې داسې په اسانۍ سره خالي کړې لکه څوک چې د ځالې نه پاتې شوې هګۍ راټولوي. نه یو وزر ورپېده چې ما ووېروي او نه کومه مښوکه خلاصه شوه چې په ما باندې وچوغیږي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_014.mp3', NULL, 1761758823, 1761758823),
(38417, 'Isaiah 10:15', 'Isaiah', 10, 15, 'خو څښتن وایي: «ایا تبر دا دعوه کولای شي چې دی د هغه سړي څخه چې ورڅخه کار اخلي ډېر لوی دی؟ ایا اره د اره کوونکي نه مهمه ده؟ انسان لرګی راپورته کوي، نه لرګی انسان.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_015.mp3', NULL, 1761758823, 1761758823),
(38418, 'Isaiah 10:16', 'Isaiah', 10, 16, 'نو مطلق قادر څښتن به یو وژونکی مرض راولېږي چې د اشور جنګیالیو ته، چې تکړه دي، سزا ورکړي. د هغوی لویي او شتمني به د اور لمبې وسوځوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_016.mp3', NULL, 1761758823, 1761758823),
(38419, 'Isaiah 10:17', 'Isaiah', 10, 17, 'د اسراییلو رڼا به په سوځوونکي اور بدله شي. د اسراییلو د سپېڅلي خدای د غوسې لمبې به په یوه ورځ د اشوریانو هرڅه لکه د اغزیو او کرکڼو په شان وسوځوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_017.mp3', NULL, 1761758823, 1761758823),
(38420, 'Isaiah 10:18', 'Isaiah', 10, 18, 'شنه شنه ځنګلونه او حاصلخېزې ځمکې به داسې بیخي له منځه لاړې شي لکه څنګه چې یوه وژونکې ناروغي انسان له منځه وړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_018.mp3', NULL, 1761758823, 1761758823),
(38421, 'Isaiah 10:19', 'Isaiah', 10, 19, 'په ځنګلونو کې به دومره لږې ونې پاتې شي چې حتی یو ماشوم به هم وکولای شي چې هغه وشمېري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_019.mp3', NULL, 1761758823, 1761758823),
(38422, 'Isaiah 10:20', 'Isaiah', 10, 20, 'داسې ورځ راروانه ده چې د اسراییلو هغه خلک چې ژوندي پاتې شوي دي، یعنې د یعقوب اولاده چې ژغورل شوې ده، هغوی به نور په هغه هېواد باندې چې په دوی یې ظلم کړی دی، تکیه ونه کړي. هغوی به یوازې په څښتن یعنې د اسراییلو په سپېڅلي خدای باندې تکیه کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_020.mp3', NULL, 1761758823, 1761758823),
(38423, 'Isaiah 10:21', 'Isaiah', 10, 21, 'د یعقوب پاتې شوې اولاده به مطلق خدای ته رجوع وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_021.mp3', NULL, 1761758823, 1761758823),
(38424, 'Isaiah 10:22', 'Isaiah', 10, 22, 'که څه هم اسراییلیان اوس د بحیرې د شګو په شان زیات دي خو یوه کوچنۍ پاتې شوې برخه به راستنه شي. په دې خلکو باندې د تباهي پرېکړه شوې ده او هغوی د دې لایق دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_022.mp3', NULL, 1761758823, 1761758823),
(38425, 'Isaiah 10:23', 'Isaiah', 10, 23, 'هو، لکه څنګه چې مطلق قادر څښتن خدای پرېکړه کړې ده، هغه به ټول هېواد له منځه یوسي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_023.mp3', NULL, 1761758823, 1761758823),
(38426, 'Isaiah 10:24', 'Isaiah', 10, 24, 'مطلق قادر څښتن خدای داسې وایي: «ای زما قومه چې په صهیون کې اوسېږئ، له اشوریانو مه وېرېږئ، که څه هم هغوی په تاسو باندې داسې ظلم کوي لکه څنګه چې مصریانو درسره کاوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_024.mp3', NULL, 1761758823, 1761758823),
(38427, 'Isaiah 10:25', 'Isaiah', 10, 25, 'ځکه زما قهر به ډېر لږ وخت وروسته پای ته ورسیږي او بیا به زه اشوریانو ته په قهر شم او هغوی به له منځه یوسم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_025.mp3', NULL, 1761758823, 1761758823),
(38428, 'Isaiah 10:26', 'Isaiah', 10, 26, 'زه مطلق قادر څښتن به هغوی په خپله قمچینه داسې ووهم لکه څنګه مې چې د مدیان خلک د غراب د ګټ تر څنګ وهلي وو. زه به اشوریانو ته هغه شان سزا ورکړم لکه څنګه چې مې د مصریانو لښکر په بحیره کې ډوب کړی ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_026.mp3', NULL, 1761758823, 1761758823),
(38429, 'Isaiah 10:27', 'Isaiah', 10, 27, 'کله چې هغه ورځ راشي، نو د اشوریانو پېټی به ستاسو له اوږو او د اسارت جغ به ستاسو له غاړې څخه لېرې شي. جغ به د سوکالۍ له امله مات شي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_027.mp3', NULL, 1761758823, 1761758823),
(38430, 'Isaiah 10:28', 'Isaiah', 10, 28, 'د دښمن لښکر د عای ښار ته رسېدلی دی! هغوی د مجرون نه تېر شوي دي او خپل سامان یې په مخماس کې پریښی دی!', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_028.mp3', NULL, 1761758823, 1761758823),
(38431, 'Isaiah 10:29', 'Isaiah', 10, 29, 'هغوی د کنډو څخه تېر شوي دي او شپه په جبع کې تېروي. د رامې د ښار خلک له وېرې رپیږي او د جبعې یعنې د شاوول پاچا د ښار خلک تښتېدلي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_029.mp3', NULL, 1761758823, 1761758823),
(38432, 'Isaiah 10:30', 'Isaiah', 10, 30, 'ای د جلیم خلکو، چیغې ووهئ! ای د لیشې خلکو، غوږ ونیسئ! ای د عناتوت بې چاره خلکو!', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_030.mp3', NULL, 1761758823, 1761758823),
(38433, 'Isaiah 10:31', 'Isaiah', 10, 31, 'د مدمینې خلک تښتي او د جیبیم خلک د پناه دپاره منډې وهي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_031.mp3', NULL, 1761758823, 1761758823),
(38434, 'Isaiah 10:32', 'Isaiah', 10, 32, 'دښمن به نن د نوب په ښار کې وي. هغوی خپل سوک د اورشلیم خواته چې د صهیون په غره کې دی د اخطار په توګه خوځوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_032.mp3', NULL, 1761758823, 1761758823),
(38435, 'Isaiah 10:33', 'Isaiah', 10, 33, 'ګورئ، مطلق قادر څښتن به هغوی داسې راوغورځوي لکه څنګه چې د لوړو ونو څانګې په درب رالویږي. د ونو په شان به د هغوی لوی لوی خلک راوغورځوي او هغوی به خوار او ذلیل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_033.mp3', NULL, 1761758823, 1761758823),
(38436, 'Isaiah 10:34', 'Isaiah', 10, 34, 'څښتن به هغوی داسې راوغورځوي لکه څنګه چې ونې د ځنګل په منځ کې په تبر رالویږي، لکه څنګه چې د لبنان ښایسته او جګې ونې راغورځیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah10_verse_034.mp3', NULL, 1761758823, 1761758823),
(38437, 'Isaiah 27:1', 'Isaiah', 27, 1, 'په هغه ورځ به څښتن په خپلې تېرې، وژونکې او غټې تورې سره بحري بلا ته یعنې هغه تښتېدونکی مار چې تاویږي او راتاویږي، سزا ورکړي او هغه ښامار به ووژني چې په بحیره کې اوسیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah27_verse_001.mp3', NULL, 1761758823, 1761758823),
(38438, 'Isaiah 27:2', 'Isaiah', 27, 2, 'په هغه ورځ به څښتن ووایي: «د یو زړه وړونکي د انګورو باغ په اړه سندره ووایئ:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah27_verse_002.mp3', NULL, 1761758823, 1761758823),
(38439, 'Isaiah 27:3', 'Isaiah', 27, 3, 'زه څښتن یمه ساتونکی د دې باغ او هر وخت ورته اوبه ورکوم شپه او ورځ ترې زه ساتنه کوم چې څوک ونه رسوي زیان ورته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah27_verse_003.mp3', NULL, 1761758823, 1761758823),
(38440, 'Isaiah 27:4', 'Isaiah', 27, 4, 'زه د انګورو په باغ په قهر نه یمه نور خو که په کې ولیدل شي اغزي او کرکڼې وبه جنګېږم د هغو په وړاندې او ټول به وسوځوم زه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah27_verse_004.mp3', NULL, 1761758823, 1761758823),
(38441, 'Isaiah 27:5', 'Isaiah', 27, 5, 'خو که وغواړي دښمنان زما د قوم چې راوړي ماته پناه او غوښتنه وکړي له ما د روغې جوړې پرېږدئ چې وکړي روغه جوړه دوی زما سره.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah27_verse_005.mp3', NULL, 1761758823, 1761758823),
(38442, 'Isaiah 27:6', 'Isaiah', 27, 6, 'هغه وخت به راشي چې د اسراییلو قوم یعنې د یعقوب اولاده لکه د ونې په شان ریښې وکړي، غوټۍ ونیسي او ګلان وغوړوي او ټوله نړۍ له مېوې ډکه کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah27_verse_006.mp3', NULL, 1761758823, 1761758823),
(38443, 'Isaiah 27:7', 'Isaiah', 27, 7, 'څښتن اسراییلیانو ته دومره سزا نه ده ورکړې لکه د هغوی دښمنانو ته چې یې ورکړې ده. د اسراییلو خلک یې د هغوی په اندازه نه دي وژلي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah27_verse_007.mp3', NULL, 1761758823, 1761758823),
(38444, 'Isaiah 27:8', 'Isaiah', 27, 8, 'څښتن د اسراییلو خلکو ته سزا ورکړه او هغوی یې جلاوطنه کړل. هغوی یې د ختیځ له خوا د یو تند باد سره لېرې یووړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah27_verse_008.mp3', NULL, 1761758823, 1761758823),
(38445, 'Isaiah 27:9', 'Isaiah', 27, 9, 'خو د اسراییلو ګناهونه به یوازې هغه وخت وبخښل شي او پای ته به ورسیږي کله چې بتانو ته د قربانۍ د ځایونو تیږې لکه د تباشیر په شان ټوټې ټوټې شي او همدارنګه بتانو ته د خوشبویۍ د سوځولو د قربانۍ ځایونو او د اشیره د بتانو نښې نښانې پاتې نه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah27_verse_009.mp3', NULL, 1761758823, 1761758823),
(38446, 'Isaiah 27:10', 'Isaiah', 27, 10, 'ټینګ ښارونه پرېښودل شوي دي او د دښتې په شان څوک په کې نه اوسیږي. هغه د څارویو څړځای جوړ شوی دی چې په کې ارام وي او د څانګو پاڼې وخوري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah27_verse_010.mp3', NULL, 1761758823, 1761758823),
(38447, 'Isaiah 27:11', 'Isaiah', 27, 11, 'د ونو څانګې وچې شوې، ښځې یې ماتوي او د سوځولو دپاره یې وړي. څښتن چې د هغوی خالق دی، په دې قوم زړه نه سوځوي او رحم نه کوي، ځکه چې هغوی پوهه نه لري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah27_verse_011.mp3', NULL, 1761758823, 1761758823),
(38448, 'Isaiah 27:12', 'Isaiah', 27, 12, 'په هغه ورځ به څښتن لکه څوک چې غنم له بوسو جدا کوي، همداسې به د اسراییلو خلک د فرات د سیند نه نیولې د مصر تر پولې پورې یو یو کس راغونډ کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah27_verse_012.mp3', NULL, 1761758823, 1761758823),
(38449, 'Isaiah 27:13', 'Isaiah', 27, 13, 'په هغه ورځ به لوی سرنی ووهل شي او هغه ټول اسراییلیان چې د اشور او د مصر په هېوادونو کې جلاوطنه دي، هغوی به بېرته خپل هېواد ته راستانه شي او د څښتن عبادت به د هغه په سپېڅلي غره باندې چې په اورشلیم کې دی، وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah27_verse_013.mp3', NULL, 1761758823, 1761758823),
(38450, 'Ecclesiastes 8:1', 'Ecclesiastes', 8, 1, 'د حکمت خاوند څوک دی؟ څوک د یو موضوع په څرګندولو پوهیږي؟ د یو انسان حکمت د هغه څېره روښانوي او د هغه سخت صورت نرموي', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes8_verse_001.mp3', NULL, 1761758823, 1761758823),
(38451, 'Ecclesiastes 8:2', 'Ecclesiastes', 8, 2, 'زما نصیحت دا دی چې د پاچا د حکم څخه اطاعت وکړه، ځکه خدای له هغه سره وعده کړې ده.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes8_verse_002.mp3', NULL, 1761758823, 1761758823),
(38452, 'Ecclesiastes 8:3', 'Ecclesiastes', 8, 3, 'نو د هغه د حضور څخه په تللو کې بیړه مه کوه او د هغو خلکو سره مه یوځای کېږه چې د هغه په ضد دسیسې جوړوي، ځکه پاچا هر هغه څه کولای شي چې زړه یې وغواړي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes8_verse_003.mp3', NULL, 1761758823, 1761758823),
(38453, 'Ecclesiastes 8:4', 'Ecclesiastes', 8, 4, 'په حقیقت کې، د پاچا حکم تر هرڅه لوړ دی او هېڅوک هغه ته نه شي ویلی چې ته څه کوې؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes8_verse_004.mp3', NULL, 1761758823, 1761758823),
(38454, 'Ecclesiastes 8:5', 'Ecclesiastes', 8, 5, 'څوک چې د هغه حکم ومني نو هغه به په هېڅ یوه دسیسه کې برخه وانخلي، او هوښیار سړی په مناسب وخت او سم قضاوت باندې پوهیږي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes8_verse_005.mp3', NULL, 1761758823, 1761758823),
(38455, 'Ecclesiastes 8:6', 'Ecclesiastes', 8, 6, 'که څه هم انسان ډېرې بدبختۍ ګالي خو د هر مقصد دپاره مناسب وخت او سم قضاوت ټاکل شوی دی.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes8_verse_006.mp3', NULL, 1761758823, 1761758823),
(38456, 'Ecclesiastes 8:7', 'Ecclesiastes', 8, 7, 'انسان نه پوهیږي چې راتلونکی به څه ډول وي، نو څوک کولای شي بل چاته ووایي چې څه به پېښیږي؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes8_verse_007.mp3', NULL, 1761758823, 1761758823),
(38457, 'Ecclesiastes 8:8', 'Ecclesiastes', 8, 8, 'لکه څنګه چې هېڅوک د ژوند د ساه د ساتلو اختیار نه لري همدا شان هېڅوک د خپل مرګ د ورځې اختیار هم نه لري لکه څنګه چې هېڅوک د جګړې په وخت د رخصتۍ اجازه نه لري همدا شان هېڅوک په خپلو بدکاریو ځان نه شي ژغورلی', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes8_verse_008.mp3', NULL, 1761758823, 1761758823),
(38458, 'Ecclesiastes 8:9', 'Ecclesiastes', 8, 9, 'کله چې ما په خپل زړه کې هر هغه څه ته چې د اسمان لاندې تر‌سره کیږي فکر وکړ، نو ومې لیدل چې کله کله یو انسان په بل انسان باندې واک او اختیار لري او هغه ته زیان رسوي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes8_verse_009.mp3', NULL, 1761758823, 1761758823),
(38459, 'Ecclesiastes 8:10', 'Ecclesiastes', 8, 10, 'نو بیا ما ولیدل چې د بدکارانو مړي ښخ شوي وو. هماغه بدکاران چې سپېڅلي ځای ته تلل راتلل، په هغه ښار کې چې هغوی بد کارونه تر‌سره کړي وو، د خلکو له خوا ستایل کېدل. نو دا حالت هم لوګی او پوکی دی.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes8_verse_010.mp3', NULL, 1761758823, 1761758823),
(38460, 'Ecclesiastes 8:11', 'Ecclesiastes', 8, 11, 'کله چې بدکارانو ته د هغو د بدو کارونو په خاطر سمدلاسه د سزا پرېکړه ونه شي، نو د انسانانو زړه د بدکارۍ په لور هڅول کیږي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes8_verse_011.mp3', NULL, 1761758823, 1761758823),
(38461, 'Ecclesiastes 8:12', 'Ecclesiastes', 8, 12, 'که څه هم یو ګناهکار ښایي سل وارې بد کارونه وکړي او لا هم اوږد ژوند ولري، بیاهم زه پوهېږم چې دا به له خدای څخه وېرېدونکو خلکو سره ښه په مخ ځي، ځکه چې دوی له هغه څخه په وېره کې ژوند کوي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes8_verse_012.mp3', NULL, 1761758823, 1761758823),
(38462, 'Ecclesiastes 8:13', 'Ecclesiastes', 8, 13, 'خو له بدکار انسان سره به دا ښه په مخ نه ځي، او د هغه د ژوند ورځې به د سیوري په څېر اوږدې نه وي، ځکه چې هغه له خدای څخه په وېره کې ژوند نه کوي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes8_verse_013.mp3', NULL, 1761758823, 1761758823),
(38463, 'Ecclesiastes 8:14', 'Ecclesiastes', 8, 14, 'دلته د لوګي او پوکي څخه ډک حالت د ځمکې په مخ موجود دی: ځینې نېکان هغه څه تر‌لاسه کوي چې بدکاران د هغه مستحق دي خو بیا ځینې بدکاران هغه څه تر‌لاسه کوي چې نېکان د هغه مستحق دي نو له ځان سره مې وویل: «دا حالت هم لوګی او پوکی دی.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes8_verse_014.mp3', NULL, 1761758823, 1761758823),
(38464, 'Ecclesiastes 8:15', 'Ecclesiastes', 8, 15, 'نو زه له ژوند نه د خوند اخیستلو سپارښتنه کوم، ځکه چې د اسمان لاندې له دې نه بل ښه کار نشته چې انسان وخوري، وڅښي او خوشحاله اوسي. نو دا خوشحالي به د هغه د ژوند په موده کې او د هغه په زیار او زحمت کې له هغه سره مل وي چې خدای هغه ته د اسمان لاندې ورکړې ده.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes8_verse_015.mp3', NULL, 1761758823, 1761758823),
(38465, 'Ecclesiastes 8:16', 'Ecclesiastes', 8, 16, 'کله چې ما د حکمت د پېژندلو هڅه وکړه ترڅو د ځمکې په مخ چې هر کار تر‌سره کیږي وڅېړم، که څه هم دا کار د یو کس د شپې یا د ورځې له خوب کولو څخه مخنیوی کوي،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes8_verse_016.mp3', NULL, 1761758823, 1761758823),
(38466, 'Ecclesiastes 8:17', 'Ecclesiastes', 8, 17, 'نو بیا ما ټول هغه کارونه ولیدل چې خدای تر‌سره کړي وو. په حقیقت کې، هېڅوک دا پټ راز نه شي پیدا کولای چې د اسمان لاندې خدای کوم کارونه تر‌سره کړي دي. انسان د خپل ټول زیار او زحمت سره سره چې د هغه په لټولو کې یې وباسي، لا هم نه شي کولای دا راز پیدا کړي. حتی که یو پوه او هوښیار سړی دعوه وکړي چې زه د خدای په کارونو پوهېږم، خو په حقیقت کې، هغه به هېڅکله دا راز پیدا نه کړي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes8_verse_017.mp3', NULL, 1761758823, 1761758823),
(38467, 'Songofsongs 4:1', 'Songofsongs', 4, 1, 'اے محبوبې، تۀ څومره ښائسته ينه. تۀ څومره نازنينه ينه. د نقاب نه شاته ستا سترګې ګوګوشتکې دينه. ستا زلفى وَل وَل لکه د چېلو د رمو په شان دينه، چې د جِلعاد د غرۀ نه لاندې راکوزيږينه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs4_verse_001.mp3', NULL, 1761758823, 1761758823),
(38468, 'Songofsongs 4:2', 'Songofsongs', 4, 2, 'ستا غاښونه د سپينو ګډو په شان دينه، چې تازه ترې نه وړۍ اخوا شوې وينه، او تازه لمبولے شوے وينه. هر يو غاښ دې د بل سره جوړه دېنه، يو هم کنډم شوے نۀ دېنه', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs4_verse_002.mp3', NULL, 1761758823, 1761758823),
(38469, 'Songofsongs 4:3', 'Songofsongs', 4, 3, 'شونډې دې تکې سرې دينه، خولۀ دې ډېره ښُکلې ښکارينه. ستا اننګى د نقاب شاته لکه د ګلابى انار ځليږينه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs4_verse_003.mp3', NULL, 1761758823, 1761758823),
(38470, 'Songofsongs 4:4', 'Songofsongs', 4, 4, 'ستا غړۍ دومره ښائسته ده لکه د داؤد د ښار مناره، چې د زرګونو بهادرانو په ډالونو باندې شوې وى سينګاره.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs4_verse_004.mp3', NULL, 1761758823, 1761758823),
(38471, 'Songofsongs 4:5', 'Songofsongs', 4, 5, 'ستا سينې لکه د هوسو د جوړه بچو په شان دينه، چې د لاله په ګلونو کښې څريږينه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs4_verse_005.mp3', NULL, 1761758823, 1761758823),
(38472, 'Songofsongs 4:6', 'Songofsongs', 4, 6, 'د دې نه وړاندې چې د سحر باد ولګيږينه او د شپې تيارۀ چې په ختمېدو شينه، زۀ به د مُر غر ته ورمنډه کړمه او د لوبانو غونډو ته به لاړه شمه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs4_verse_006.mp3', NULL, 1761758823, 1761758823),
(38473, 'Songofsongs 4:7', 'Songofsongs', 4, 7, 'زما محبوبې، ستا ښائست کامِل دېنه، په تا کښې هيڅ عېب نشته دېنه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs4_verse_007.mp3', NULL, 1761758823, 1761758823),
(38474, 'Songofsongs 4:8', 'Songofsongs', 4, 8, 'زما ناوې، د لبنان نه ما سره راشه، د لبنان نه ما سره راشه. د امانه د غرۀ د څوکو نه راکوزه شه، د حرمون او د سنير د څوکو نه ما سره راکوزه شه، د زمرو د غارونو او د پړانګانو د غونډو نه راکوزه شه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs4_verse_008.mp3', NULL, 1761758823, 1761758823),
(38475, 'Songofsongs 4:9', 'Songofsongs', 4, 9, 'اے زما دُنيا، اے زما ناوې، زما نه دې زړۀ وړے دېنه، د سترګو په يوه اِشاره دې ما نه زړګے وړے دېنه، او د اميل يو غمى دې ما نه زړګے وړے دېنه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs4_verse_009.mp3', NULL, 1761758823, 1761758823),
(38476, 'Songofsongs 4:10', 'Songofsongs', 4, 10, 'زما دُنيا، زما ناوې زۀ ستا په مينه کښې څومره خوشحاله يمه، د ميو نه څومره خوشحالونکى ده ستا مينه، او ستا خوشبو د هرې مصالحې نه څومره ښۀ ده.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs4_verse_010.mp3', NULL, 1761758823, 1761758823),
(38477, 'Songofsongs 4:11', 'Songofsongs', 4, 11, 'زما ناوې، ستا د شونډو نه د شاتو د ګبين په شان خوږوالے راڅاڅيږينه، ستا د ژبې لاندې شات او پئ پراتۀ دينه، ستا د جامو نه لکه د لبنان د دِيار په شان خوشبو راځينه', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs4_verse_011.mp3', NULL, 1761758823, 1761758823),
(38478, 'Songofsongs 4:12', 'Songofsongs', 4, 12, 'اے زما محبوبې، تۀ زما بنده باغيچه ينه، تۀ زما دُنيا ينه، او زما ناوې ينه، زما پټ باغ، زما پټه چينه ينه،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs4_verse_012.mp3', NULL, 1761758823, 1761758823),
(38479, 'Songofsongs 4:13', 'Songofsongs', 4, 13, 'تۀ لکه د انارو باغيچه ينه، د مزېدارو مېوو نه ډکه ينه، او خوشبو دې لکه د مشکو او عنبرو په شان ده نه،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs4_verse_013.mp3', NULL, 1761758823, 1761758823),
(38480, 'Songofsongs 4:14', 'Songofsongs', 4, 14, 'چرته چې د مشکو، زعفرانو، دارچينو او هر قسمه مصالحو بوټى پېدا کيږينه، او عُود، مُر او لوبانو خوشبوداره عطر پېدا کيږينه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs4_verse_014.mp3', NULL, 1761758823, 1761758823),
(38481, 'Songofsongs 4:15', 'Songofsongs', 4, 15, 'تۀ د باغ چينه ينه، تۀ د تازه اوبو کوهے ينه چې د لبنان د غرونو نه رابهيږينه. محبوبه', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs4_verse_015.mp3', NULL, 1761758823, 1761758823),
(38482, 'Songofsongs 4:16', 'Songofsongs', 4, 16, 'اے د شمال باده، راوالوځه، اے د جنوب باده راشه، زما په باغ باندې راوالوځه او د هغۀ خوشبو هرې خوا ته خوره کړه. زما جانانه خپل باغ ته راشه، او د هغې ښُکلې مېوې وخوره.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs4_verse_016.mp3', NULL, 1761758823, 1761758823),
(38483, 'Job 42:1', 'Job', 42, 1, 'بيا ايُوب مالِک خُدائ له جواب ورکړو،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job42_verse_001.mp3', NULL, 1761758823, 1761758823),
(38484, 'Job 42:2', 'Job', 42, 2, '”ما ته پته ده چې تۀ هر څۀ کولے شې، او تا د خپل کار نه هيڅ څوک نۀ شى ايسارولے.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job42_verse_002.mp3', NULL, 1761758823, 1761758823),
(38485, 'Job 42:3', 'Job', 42, 3, 'تا وفرمائيل چې، ”هغه څوک دے چې زما په حِکمت باندې د ناپوهۍ سره شک کوى؟“ هغه زۀ يم، ما د داسې څيزونو خبره کوله چې ما ته يې هيڅ پته نۀ وه، او هغه خبرې زما دپاره ډېرې عجيبه او لوئې وې.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job42_verse_003.mp3', NULL, 1761758823, 1761758823),
(38486, 'Job 42:4', 'Job', 42, 4, 'تا وفرمائيل چې، ”ما ته غوږ ونيسه او زۀ به وايم، زۀ به تپوس کوم او تۀ به ما له جواب راکوې.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job42_verse_004.mp3', NULL, 1761758823, 1761758823),
(38487, 'Job 42:5', 'Job', 42, 5, 'ما مخکښې صرف ستا په حقله اورېدلى دى، خو اوس مې په خپلو سترګو وليدلې.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job42_verse_005.mp3', NULL, 1761758823, 1761758823),
(38488, 'Job 42:6', 'Job', 42, 6, 'نو ما چې څۀ وئيلى دى نو په هغې شرمنده يم، او په خاورو او ايرو کښې توبه وباسم.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job42_verse_006.mp3', NULL, 1761758823, 1761758823),
(38489, 'Job 42:7', 'Job', 42, 7, 'کله چې مالِک خُدائ د ايُوب سره دا خبرې وکړې، نو مالِک خُدائ تيمانى اليفز ته وفرمائيل، ”زۀ تا او ستا دوو ملګرو ته سخت غصه يم، ځکه چې تاسو زما هغه خبره نۀ ده کړې چې کومه صحيح ده، لکه څنګه چې زما خِدمت کوونکى ايُوب کړې ده.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job42_verse_007.mp3', NULL, 1761758823, 1761758823),
(38490, 'Job 42:8', 'Job', 42, 8, 'نو په دې وجه اوس اووۀ غوَيى او اووۀ ګډان بوځه او زما خِدمت کوونکى ايُوب له ورشه او د خپل ځان دپاره دا د سوزېدونکې نذرانې په توګه پېش کړه، نو زما خِدمت کوونکے ايُوب به ستا دپاره دُعا وکړى، ځکه چې زۀ به د هغۀ دُعا قبلوم او ستاسو د کم عقلتوب په مطابق کار به درسره نۀ کوم، ځکه چې تاسو زما هغه خبره نۀ ده کړې چې کومه صحيح ده، لکه څنګه چې زما خِدمت کوونکى ايُوب کړې ده.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job42_verse_008.mp3', NULL, 1761758823, 1761758823),
(38491, 'Job 42:9', 'Job', 42, 9, 'نو تيمانى اليفز، شوحى بِلداد او نعماتى ضوفر لاړل او چې مالِک خُدائ څنګه فرمائيلى وُو هم هغه شان يې وکړل، او مالِک خُدائ د ايُوب دُعا قبوله کړه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job42_verse_009.mp3', NULL, 1761758823, 1761758823),
(38492, 'Job 42:10', 'Job', 42, 10, 'نو کله چې ايُوب د خپلو ملګرو دپاره دُعا وکړه نو خُدائ پاک هغۀ له بيا برکت ورکړو، او چې ايُوب مخکښې څۀ لرل نو مالِک خُدائ هغۀ له د هغې يو په دوه نور هم زيات ورکړل.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job42_verse_010.mp3', NULL, 1761758823, 1761758823),
(38493, 'Job 42:11', 'Job', 42, 11, 'نو هلته هغۀ له د هغۀ ټول وروڼه خوېندې او ټول پخوانى خپل پردى راغلل او هغوئ د هغۀ په کور کښې روټۍ وخوړه. او هغوئ ورته مينه ښکاره کړه او د هغه تکليفونو په وجه يې هغۀ له تسلى ورکړه چې مالِک خُدائ په هغۀ راوستى وُو. او هغوئ هر يو هغۀ له لږې پېسې او يوه د سرو زرو ګوتمه ورکړه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job42_verse_011.mp3', NULL, 1761758823, 1761758823),
(38494, 'Job 42:12', 'Job', 42, 12, 'نو مالِک خُدائ د ايُوب وروستنے عُمر د اول عُمر نه زيات برکتناک کړو، او د هغۀ څوارلس زره ګډې، شپږ زره اوښان، دوه زره غوَيى او يو زر خرۀ وُو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job42_verse_012.mp3', NULL, 1761758823, 1761758823),
(38495, 'Job 42:13', 'Job', 42, 13, 'د هغۀ اووۀ زامن او درې لوڼه هم وې.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job42_verse_013.mp3', NULL, 1761758823, 1761758823),
(38496, 'Job 42:14', 'Job', 42, 14, 'هغۀ په وړومبۍ لور باندې يميمه، په دوېمه قصياه او په درېمه باندې قرن‌هپوک نوم کېښودو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job42_verse_014.mp3', NULL, 1761758823, 1761758823),
(38497, 'Job 42:15', 'Job', 42, 15, 'او په هغه ټول مُلک کښې د ايُوب د لوڼو په شان ښائسته ښځې نۀ وې، خپل پلار هغوئ له د دوئ د وروڼو په شان ميراث ورکړو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job42_verse_015.mp3', NULL, 1761758823, 1761758823),
(38498, 'Job 42:16', 'Job', 42, 16, 'ايُوب د دې نه پس يو سل او څلوېښت کاله ژوندے وو او د څلورم نسل پورې خپل بچى او نمسى يې وليدل.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job42_verse_016.mp3', NULL, 1761758823, 1761758823),
(38499, 'Job 42:17', 'Job', 42, 17, 'نو بيا ايُوب په پوخ عُمر کښې مړ شو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job42_verse_017.mp3', NULL, 1761758823, 1761758823),
(38500, 'Genesis 47:1', 'Genesis', 47, 1, 'نو یوسف لاړ او فرعون ته یې وویل: «زما پلار او زما ورونه د خپلو رمو، پادو او خپلو ټولو شیانو سره چې درلودل یې د کنعان څخه راغلي دي او اوس د جوشن په سیمه کې دي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_001.mp3', NULL, 1761758823, 1761758823),
(38501, 'Genesis 47:2', 'Genesis', 47, 2, 'هغه د خپلو ورونو څخه پنځه تنه غوره کړل او فرعون ته یې وروپېژندل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_002.mp3', NULL, 1761758823, 1761758823),
(38502, 'Genesis 47:3', 'Genesis', 47, 3, 'فرعون د هغوی څخه پوښتنه وکړه: «تاسو څه کار کوئ؟» هغوی ځواب ورکړ: «مونږ د خپلو نیکونو په شان شپانه یو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_003.mp3', NULL, 1761758823, 1761758823),
(38503, 'Genesis 47:4', 'Genesis', 47, 4, 'مونږ راغلي یو چې د یو څه مودې دپاره په دې وطن کې واوسېږو، ځکه چې د کنعان په خاوره کې ډېره سخته قحطي ده او هلته زمونږ د رمو دپاره څړځای نشته. نو اوس مونږ ته اجازه راکړئ چې د جوشن په سیمه کې واوسېږو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_004.mp3', NULL, 1761758823, 1761758823),
(38504, 'Genesis 47:5', 'Genesis', 47, 5, 'فرعون یوسف ته وویل: «اوس چې ستا پلار او ورونه تاته راغلي دي،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_005.mp3', NULL, 1761758823, 1761758823),
(38505, 'Genesis 47:6', 'Genesis', 47, 6, 'د مصر ځمکه ستا په واک کې ده. پرېږده چې هغوی د جوشن په سیمه کې چې د دې هېواد تر ټولو ښه ځمکه ده، واوسیږي. همدارنګه زه غواړم چې ستاسو ډېر ښه شپانه دې زما پسونه او وزې وساتي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_006.mp3', NULL, 1761758823, 1761758823),
(38506, 'Genesis 47:7', 'Genesis', 47, 7, 'بیا یوسف خپل پلار یعقوب راوست او فرعون ته یې وروپېژانده. یعقوب فرعون ته برکت ورکړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_007.mp3', NULL, 1761758823, 1761758823),
(38507, 'Genesis 47:8', 'Genesis', 47, 8, 'فرعون د یعقوب څخه پوښتنه وکړه: «ستا عمر څومره دی؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_008.mp3', NULL, 1761758823, 1761758823),
(38508, 'Genesis 47:9', 'Genesis', 47, 9, 'یعقوب ځواب ورکړ: «زما د عمر یوسلو دېرش کاله شوي دي او د یو ځای څخه مې بل ځای ته کډه کړې ده. زما پلرونو او نیکونو هم د یو ځای څخه بل ځای ته کډه کړې ده. خو هغوی اوږد عمر درلود او د هغوی ژوند زما د ژوند په شان سخت نه ؤ.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_009.mp3', NULL, 1761758823, 1761758823),
(38509, 'Genesis 47:10', 'Genesis', 47, 10, 'یعقوب یوځل بیا فرعون ته برکت ورکړ او د هغه د حضور څخه لاړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_010.mp3', NULL, 1761758823, 1761758823),
(38510, 'Genesis 47:11', 'Genesis', 47, 11, 'نو یوسف د فرعون د امر سره سم خپل پلار او ورونو ته په مصر کې ډېر ښه ځای چې د رعمسیس ښار ته نژدې ؤ، ورکړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_011.mp3', NULL, 1761758823, 1761758823),
(38511, 'Genesis 47:12', 'Genesis', 47, 12, 'یوسف خپل پلار، خپلو ورونو او د خپل پلار ټولې کورنۍ ته د هغوی د اولادونو د شمېر سره سم خواړه برابرول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_012.mp3', NULL, 1761758823, 1761758823),
(38512, 'Genesis 47:13', 'Genesis', 47, 13, 'قحطي دومره سخته شوه چې په ټوله سیمه کې ډوډۍ نه وه او د کنعان او مصر خلک د لوږې له لاسه کمزوري شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_013.mp3', NULL, 1761758823, 1761758823),
(38513, 'Genesis 47:14', 'Genesis', 47, 14, 'د مصر او کنعان د خلکو سره چې څومره پیسې وې هغه ټولې یې د غلو د اخیستلو په بدل کې یوسف ته ورکړې او یوسف هغه پیسې واخیستلې او د فرعون په خزانه کې یې کېښودلې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_014.mp3', NULL, 1761758823, 1761758823),
(38514, 'Genesis 47:15', 'Genesis', 47, 15, 'کله چې د مصر او د کنعان د خلکو پیسې خلاصې شوې، نو ټول مصریان یوسف ته راغلل او ویې ویل: «زمونږ ټولې پیسې خلاصې شوې، مونږ ته غلې دانې راکړئ. دې ته مو مه پرېږدئ چې تاسو راته ګورئ او مونږ مړه کېږو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_015.mp3', NULL, 1761758823, 1761758823),
(38515, 'Genesis 47:16', 'Genesis', 47, 16, 'یوسف ځواب ورکړ: «که چېرې ستاسو پیسې خلاصې شوې وي، نو خپل حیوانات راولئ. زه به ستاسو د حیواناتو په بدل کې په تاسو باندې غلې دانې خرڅې کړم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_016.mp3', NULL, 1761758823, 1761758823),
(38516, 'Genesis 47:17', 'Genesis', 47, 17, 'نو هغوی یوسف ته خپل حیوانات راوستل او یوسف د هغوی د اسونو، پسونو، وزو، غویانو او خرو په بدل کې ورته غله ورکړه او په هغه کال یې هغوی ته د دوی د ټولو حیواناتو په بدل کې غله ورسوله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_017.mp3', NULL, 1761758823, 1761758823),
(38517, 'Genesis 47:18', 'Genesis', 47, 18, 'کله چې هغه کال تېر شو، د قحطۍ په بل کال هغوی یوسف ته راغلل او ویې ویل: «باداره، ستاسو څخه دا حقیقت نه شو پټولی چې زمونږ ټولې پیسې خلاصې شوې دي او زمونږ حیوانات هم ستاسو شول. زمونږ سره د خپل ځان او ځمکې څخه پرته نور څه نه دي پاتې چې تاسو ته یې درکړو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_018.mp3', NULL, 1761758823, 1761758823),
(38518, 'Genesis 47:19', 'Genesis', 47, 19, 'مونږ دې ته مه پرېږدئ چې مړه شو! مه پرېږدئ چې زمونږ ځمکه شاړه شي. مونږ او زمونږ ځمکه د غلو دانو په بدل کې واخلئ. مونږ به د فرعون غلامان شو او هغه به زمونږ د ځمکې خاوند شي. مونږ ته غله راکړئ چې ژوندي پاتې شو او تخم راکړئ چې خپلې ځمکې وکرو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_019.mp3', NULL, 1761758823, 1761758823),
(38519, 'Genesis 47:20', 'Genesis', 47, 20, 'نو یوسف د مصر ټوله ځمکه فرعون ته واخیستله. مصریانو هر یو خپله ځمکه خرڅه کړه، ځکه چې سخته قحطي شوه او ټوله ځمکه د فرعون شوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_020.mp3', NULL, 1761758823, 1761758823),
(38520, 'Genesis 47:21', 'Genesis', 47, 21, 'یوسف د مصر د یو سر څخه تر بل سر پورې خلک غلامان کړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_021.mp3', NULL, 1761758823, 1761758823),
(38521, 'Genesis 47:22', 'Genesis', 47, 22, 'یوازېنۍ ځمکه چې یوسف په بیه نه وه اخیستې، هغه د کاهنانو ځمکه وه، ځکه چې کاهنانو ته به د فرعون له خوا یو څه ورکول کېدل چې خپل ژوند ورباندې وکړي. په دې سبب هغوی خپله ځمکه خرڅه نه کړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_022.mp3', NULL, 1761758823, 1761758823),
(38522, 'Genesis 47:23', 'Genesis', 47, 23, 'یوسف خلکو ته وویل: «اوس چې ما ستاسو ځمکې او تاسو د فرعون دپاره اخیستي یئ، دا دی تخم ستاسو دپاره چې په خپلو ځمکو کې یې وکرئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_023.mp3', NULL, 1761758823, 1761758823),
(38523, 'Genesis 47:24', 'Genesis', 47, 24, 'خو کله چې د حاصل وخت راشي، نو تاسو به د هغې څخه پنځمه برخه فرعون ته ورکړئ او پاتې څلور برخې د ځمکو د تخم او خپل ځان، خپلو کورنیو او خپلو ماشومانو ته د خوراک دپاره وساتئ.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_024.mp3', NULL, 1761758823, 1761758823),
(38524, 'Genesis 47:25', 'Genesis', 47, 25, 'هغوی وویل: «باداره، تاسو زمونږ سره نېکي وکړه او زمونږ ژوند مو وژغوره. نو مونږ به د فرعون غلامان یو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_025.mp3', NULL, 1761758823, 1761758823),
(38525, 'Genesis 47:26', 'Genesis', 47, 26, 'نو یوسف د مصر په خاوره کې دا قانون وټاکه چې د محصولاتو پنځمه برخه به د فرعون وي. دغه قانون تر نن ورځې پورې په خپل قوت پاتې دی. یوازې د کاهنانو ځمکه د فرعون جایداد نه شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_026.mp3', NULL, 1761758823, 1761758823),
(38526, 'Genesis 47:27', 'Genesis', 47, 27, 'نو اسراییلیان په مصر کې د جوشن په سیمه کې اوسېدل. په هغه ځای کې دوی شتمني لاسته راوړله او د ډېرو اولادونو خاوندان شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_027.mp3', NULL, 1761758823, 1761758823),
(38527, 'Genesis 47:28', 'Genesis', 47, 28, 'یعقوب په مصر کې اوولس کاله ژوند وکړ او په یوسلو اووه څلوېښت کلنۍ کې مړ شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_028.mp3', NULL, 1761758823, 1761758823),
(38528, 'Genesis 47:29', 'Genesis', 47, 29, 'کله چې د یعقوب د مرګ وخت رانژدې شو، هغه خپل زوی یوسف راوغوښت او هغه ته یې وویل: «که چېرې زه درباندې په رښتیا ګران یم، نو خپل لاس دې زما د ورون لاندې کېږده او زما سره قسم وخوره چې ما به په مصر کې نه ښخوې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_029.mp3', NULL, 1761758823, 1761758823),
(38529, 'Genesis 47:30', 'Genesis', 47, 30, 'زه غواړم په هغه ځای کې ښخ کړای شم چې زما نیکونه په کې ښخ دي. ما د مصر څخه یوسه او په کوم ځای کې چې هغوی ښخ شوي دي هلته مې ښخ کړه.» یوسف ځواب ورکړ: «څنګه چې ته وایې همداسې به وکړم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_030.mp3', NULL, 1761758823, 1761758823),
(38530, 'Genesis 47:31', 'Genesis', 47, 31, 'یعقوب وویل: «ماته قسم وخوره چې ته به دا کار کوې.» یوسف قسم وخوړ او یعقوب په خپل کټ باندې سر ټیټ کړ او شکر یې ادا کړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis47_verse_031.mp3', NULL, 1761758823, 1761758823),
(38531, 'Genesis 2:1', 'Genesis', 2, 1, 'نو ځمکه او اسمانونه او نور ټول شیان جوړ شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_001.mp3', NULL, 1761758823, 1761758823),
(38532, 'Genesis 2:2', 'Genesis', 2, 2, 'په اوومه ورځ خدای هغه ټول کارونه چې کول یې، سرته ورسول او کار یې بس کړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_002.mp3', NULL, 1761758823, 1761758823),
(38533, 'Genesis 2:3', 'Genesis', 2, 3, 'خدای اوومه ورځ مبارکه وبلله او هغه یې ځانګړې وګرځوله، ځکه چې په هغه ورځ هغه پیدایښت پوره کړ او کار یې بس کړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_003.mp3', NULL, 1761758823, 1761758823),
(38534, 'Genesis 2:4', 'Genesis', 2, 4, 'په دې ډول ځمکه او اسمانونه پیدا شول. د عدن باغ کله چې څښتن خدای اسمانونه او ځمکه جوړ کړل،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_004.mp3', NULL, 1761758823, 1761758823),
(38535, 'Genesis 2:5', 'Genesis', 2, 5, 'تر هغه وخته پورې لا هېڅ واښه یا نور بوټي راشنه شوي نه وو، ځکه چې څښتن خدای باران نه ؤ اورولی او څوک نه ؤ چې په ځمکه باندې کار وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_005.mp3', NULL, 1761758823, 1761758823),
(38536, 'Genesis 2:6', 'Genesis', 2, 6, 'نو د ځمکې څخه د اوبو ویالې راووتلې او د ځمکې مخ ته یې اوبه ورکړې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_006.mp3', NULL, 1761758823, 1761758823),
(38537, 'Genesis 2:7', 'Genesis', 2, 7, 'څښتن خدای خاوره راواخیستله او د هغې څخه یې انسان جوړ کړ او د هغه په پوزه کې یې د ژوندون روح پو کړ او هغه ژوندی بدن شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_007.mp3', NULL, 1761758823, 1761758823),
(38538, 'Genesis 2:8', 'Genesis', 2, 8, 'څښتن خدای په عدن کې لمرخاته خواته یو باغ جوړ کړ او هغه انسان چې هغه جوړ کړی ؤ، هغه ته یې په دې باغ کې ځای ورکړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_008.mp3', NULL, 1761758823, 1761758823),
(38539, 'Genesis 2:9', 'Genesis', 2, 9, 'څښتن خدای په دې باغ کې هر ډول ښایسته او مېوه لرونکې ونې راشنې کړلې او د باغ په منځ کې دوه نورې ونې وې. یوه د ژوندانه ونه او بله د ښو او بدو د پېژندلو ونه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_009.mp3', NULL, 1761758823, 1761758823),
(38540, 'Genesis 2:10', 'Genesis', 2, 10, 'د عدن څخه یو سیند جاري شو چې باغ ته اوبه ورکړي او دا سیند بیا په څلورو سیندونو باندې ووېشل شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_010.mp3', NULL, 1761758823, 1761758823),
(38541, 'Genesis 2:11', 'Genesis', 2, 11, 'د لومړني سیند نوم فیشون دی چې د حویله په ټول هېواد باندې راتاو شوی دی او هلته سره زر دي،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_011.mp3', NULL, 1761758823, 1761758823),
(38542, 'Genesis 2:12', 'Genesis', 2, 12, 'چې د هغه ځای سره زر ډېر ښه دي. د خوشبویۍ مواد او د عقیقو تیږې هم په کې پیدا کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_012.mp3', NULL, 1761758823, 1761758823),
(38543, 'Genesis 2:13', 'Genesis', 2, 13, 'دوهم یې د جیحون سیند دی چې د کوش د ټولې ځمکې څخه راتاو شوی دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_013.mp3', NULL, 1761758823, 1761758823),
(38544, 'Genesis 2:14', 'Genesis', 2, 14, 'درېم سیند د دجلې په نوم یادیږي چې د آشور لمرخاته خواته بهیږي او څلورم د فرات سیند دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_014.mp3', NULL, 1761758823, 1761758823),
(38545, 'Genesis 2:15', 'Genesis', 2, 15, 'نو څښتن خدای آدم ته د عدن په باغ کې ځای ورکړ چې د هغه خدمت او ساتنه وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_015.mp3', NULL, 1761758823, 1761758823),
(38546, 'Genesis 2:16', 'Genesis', 2, 16, 'څښتن خدای آدم ته وویل: «د باغ د ټولو ونو څخه مېوه خوړلی شې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_016.mp3', NULL, 1761758823, 1761758823),
(38547, 'Genesis 2:17', 'Genesis', 2, 17, 'خو د ښو او بدو د پېژندلو د ونې څخه نه، ځکه کله چې د هغې ونې مېوه وخورې بې له شکه چې مړ به شې.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_017.mp3', NULL, 1761758823, 1761758823),
(38548, 'Genesis 2:18', 'Genesis', 2, 18, 'څښتن خدای وویل: «دا ښه نه دی چې آدم دې یوازې اوسي، زه به د هغه دپاره یوه مناسبه ملګرې جوړوم چې د هغه سره مرسته وکړي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_018.mp3', NULL, 1761758823, 1761758823),
(38549, 'Genesis 2:19', 'Genesis', 2, 19, 'نو بیا څښتن خدای د خاورې څخه ټول حیوانات او مرغان جوړ کړل او هغه یې آدم ته راوستل، ترڅو وګوري چې په هغوی باندې کوم نوم ږدي. په دې ډول په هغوی ټولو باندې نومونه کېښودل شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_019.mp3', NULL, 1761758823, 1761758823),
(38550, 'Genesis 2:20', 'Genesis', 2, 20, 'نو آدم په ټولو کورني او وحشي حیواناتو او مرغانو باندې نومونه کېښودل. د هغوی څخه یو هم د آدم دپاره مناسب ملګری نه ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_020.mp3', NULL, 1761758823, 1761758823),
(38551, 'Genesis 2:21', 'Genesis', 2, 21, 'نو څښتن خدای آدم په درانه خوب باندې ویده کړ او د هغه د پوښتیو څخه یې یوه راواخیستله او د هغې ځای یې په غوښه باندې ډک کړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_021.mp3', NULL, 1761758823, 1761758823),
(38552, 'Genesis 2:22', 'Genesis', 2, 22, 'څښتن خدای د هغې پوښتۍ څخه ښځه جوړه کړه او هغه یې آدم ته راوستله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_022.mp3', NULL, 1761758823, 1761758823),
(38553, 'Genesis 2:23', 'Genesis', 2, 23, 'آدم وویل: دلته اوس شته یو څوک زما په شان اخیستل شوی یې هډوکی زما د هډوکو څخه او غوښه یې زما د غوښې څخه د هغې نوم دی ښځه ځکه اخیستل شوې هغه د سړي څخه ده', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_023.mp3', NULL, 1761758823, 1761758823),
(38554, 'Genesis 2:24', 'Genesis', 2, 24, 'له همدې امله سړی خپل مور او پلار پرېږدي او د خپلې ښځې سره یوځای کیږي او دواړه یو بدن شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_024.mp3', NULL, 1761758823, 1761758823),
(38555, 'Genesis 2:25', 'Genesis', 2, 25, 'سره د دې چې آدم او د هغه ښځه دواړه لوڅ وو، خو دوی نه شرمېدل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis2_verse_025.mp3', NULL, 1761758823, 1761758823),
(38556, 'Hosea 10:1', 'Hosea', 10, 1, 'د اسراییلو قوم د انګورو د یو داسې تاک په شان ؤ چې د انګورو نه ډک ؤ. هرڅومره چې د هغه مېوه زیاتېدله، نو هماغومره ډېر د بتانو د قربانۍ ځایونه به یې جوړول. هرڅومره چې د هغوی د ځمکې حاصلات زیاتېدل، نو هغوی د تیږو مذهبي ستنې ښایسته کولې.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea10_verse_001.mp3', NULL, 1761758823, 1761758823),
(38557, 'Hosea 10:2', 'Hosea', 10, 2, 'د هغو خلکو چې زړونه یې د چل او غولونې نه ډک دي، نو اوس به د خپلو ګناهونو له امله ځوریږي. خدای به د هغوی د قربانۍ ځایونه وران کړي او د هغوی د تیږو ستنې به له منځه یوسي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea10_verse_002.mp3', NULL, 1761758823, 1761758823),
(38558, 'Hosea 10:3', 'Hosea', 10, 3, 'بیا به دا خلک ووایي: «مونږ پاچا نه لرو، ځکه چې مونږ د څښتن څخه ونه وېرېدلو. خو که مونږ پاچا درلودلی، نو هغه به زمونږ دپاره څه کولای شول؟»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea10_verse_003.mp3', NULL, 1761758823, 1761758823),
(38559, 'Hosea 10:4', 'Hosea', 10, 4, 'د اسراییلو پاچاهان هسې خبرې کوي او د دروغو وعدې کوي او بې‌ګټې تړونونه کوي. انصاف په بې‌انصافۍ باندې بدل شوی دی لکه په قلبه شوي پټي کې چې زهرجن بوټي راشنه شي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea10_verse_004.mp3', NULL, 1761758823, 1761758823),
(38560, 'Hosea 10:5', 'Hosea', 10, 5, 'کوم خلک چې په سامرې کې اوسیږي، هغوی به ووېریږي او په بیت‌آون کې د سرو زرو د خوسي د ورکېدلو په خاطر به ویر وکړي. خلک او د بت کاهنان به په دې خاطر چې د هغه شان او شوکت به له منځه لاړ شي، نو هغوی به ورباندې ژړا او انګولا کوي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea10_verse_005.mp3', NULL, 1761758823, 1761758823),
(38561, 'Hosea 10:6', 'Hosea', 10, 6, 'حتی هغه بت به هم آشور ته یووړل شي چې لوی امپراتور ته به د باج په توګه ورکړل شي. د اسراییلو خلک به په هغه بت باندې د تکیه کولو په سبب وشرمیږي او خجالته به شي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea10_verse_006.mp3', NULL, 1761758823, 1761758823),
(38562, 'Hosea 10:7', 'Hosea', 10, 7, 'د سامریې پاچا به داسې یووړل شي لکه د اوبو په سر باندې چې د لرګي یوه کوچنۍ ټوټه روانه وي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea10_verse_007.mp3', NULL, 1761758823, 1761758823),
(38563, 'Hosea 10:8', 'Hosea', 10, 8, 'د آون هغه سیمه‌ییز عبادتځایونه به له منځه لاړ شي چې د اسراییلو خلکو په کې ګناه کوله. د هغوی په قربانګاوو باندې به اغزي او هرزه بوټي راشنه شي. خلک به غرونو ته چیغې وهي چې مونږ پټ کړئ! او غونډیو ته به چیغې وهي چې په مونږ باندې راولوېږئ!', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea10_verse_008.mp3', NULL, 1761758823, 1761758823),
(38564, 'Hosea 10:9', 'Hosea', 10, 9, 'څښتن وایي: «ای د اسراییلو خلکو، د هماغه وخت نه چې تاسو په جبعه کې ګناه کړې ده، تر‌اوسه پورې زما په وړاندې د ګناه کولو نه لاس نه اخلئ. ایا دا مناسبه نه وه چې د جبعې په بدکاره خلکو باندې حمله وشوه؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea10_verse_009.mp3', NULL, 1761758823, 1761758823),
(38565, 'Hosea 10:10', 'Hosea', 10, 10, 'کله چې زه وغواړم، هغوی ته به سزا ورکړم. نور قومونه به د هغوی په وړاندې سره یوځای شي او هغوی به د خپلو زیاتو ګناهونو له امله په زنځیرونو وتړل شي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea10_verse_010.mp3', NULL, 1761758823, 1761758823),
(38566, 'Hosea 10:11', 'Hosea', 10, 11, 'اسراییل په یو وخت کې د ښه روزل شوي خوسي په شان ؤ چې د غلو دانو غوبل کولو ته به خوشحاله ؤ. خو زه به د هغه په ښایسته غاړه باندې جغ ږدم او د سخت کار دپاره به یې تیاروم. ما یهودا دې ته مجبوره کړ چې یوې کش کړي او یعقوب مې مجبور کړ چې ماله کش کړي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea10_verse_011.mp3', NULL, 1761758823, 1761758823),
(38567, 'Hosea 10:12', 'Hosea', 10, 12, 'نو د عدالت تخم وکرئ، ترڅو د تلپاتې مینې حاصل ورڅخه ورېبئ. د خپلو زړونو سخته ځمکه نرمه کړئ، ځکه چې اوس د دې وخت رارسېدلی دی چې د څښتن په لټه کې اوسئ، ترڅو زه راشم او د عدالت باران په تاسو باندې ووروم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea10_verse_012.mp3', NULL, 1761758823, 1761758823),
(38568, 'Hosea 10:13', 'Hosea', 10, 13, 'خو تاسو د بدکارۍ تخم وکاره او د بې‌انصافۍ حاصل مو ورېبه. تاسو د خپلو دروغو د حاصل مېوه وخوړله. ځکه چې تاسو په خپل قوت او په خپلو ډېرو جنګیالیو باندې تکیه وکړه،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea10_verse_013.mp3', NULL, 1761758823, 1761758823),
(38569, 'Hosea 10:14', 'Hosea', 10, 14, 'نو ستاسو په خلکو باندې به د جنګ اوازونه راشي او ستاسو ټولې قوي کلاګانې به ورانې شي. دا به د هغې ورځې په شان وي لکه څنګه چې شلمان پاچا چې د بیت‌اربیل ښار په جنګ کې وران کړ او د هغوی میندې او ماشومان به په ځمکه راوغورځیږي او مړه به شي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea10_verse_014.mp3', NULL, 1761758823, 1761758823),
(38570, 'Hosea 10:15', 'Hosea', 10, 15, 'نو ای د بیت‌ییل خلکو، ستاسو سره به هم د هغو ډېرو بدو عملونو له امله چې کړي مو دي، همداسې کار کیږي. څنګه چې جنګ پیل شي، نو د اسراییلو پاچا به په بشپړه توګه تباه شي.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea10_verse_015.mp3', NULL, 1761758823, 1761758823),
(38571, 'Esther 3:1', 'Esther', 3, 1, 'څه موده وروسته خشایار پاچا د همداتا زوی هامان ته چې د اجاج د طایفې ؤ، ترفیع ورکړه. هغه یې په خپلې امپراتورۍ کې لومړی وزیر کړ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther3_verse_001.mp3', NULL, 1761758823, 1761758823),
(38572, 'Esther 3:2', 'Esther', 3, 2, 'پاچا امر وکړ چې ټول درباریان دې هامان ته د درناوي په خاطر خپل سرونه ټیټ کړي. هغوی ټولو همداسې وکړل، پرته له مردخای څخه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther3_verse_002.mp3', NULL, 1761758823, 1761758823),
(38573, 'Esther 3:3', 'Esther', 3, 3, 'نو هغو نورو درباریانو چې د پاچا خدمت کاوه د مردخای څخه پوښتنه وکړه: «ته ولې د پاچا د حکم څخه سرغړونه کوې؟»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther3_verse_003.mp3', NULL, 1761758823, 1761758823),
(38574, 'Esther 3:4', 'Esther', 3, 4, 'هغوی به هره ورځ مردخای دې ته هڅاوه چې دا خبره ومني، خو هغه به هغوی ته غوږ نه نیوه. هغه به ویل: «زه یهودي یم او نه شم کولای چې هامان ته د درناوي سر ټیټ کړم.» نو هغوی هامان ته په دې هکله خبر ورکړ چې وګوري چې ایا هغه د مردخای چلند زغمي او که نه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther3_verse_004.mp3', NULL, 1761758823, 1761758823),
(38575, 'Esther 3:5', 'Esther', 3, 5, 'کله چې هامان پوه شو چې مردخای ده ته د درناوي په خاطر خپل سر نه ټیټوي، نو هغه سخت په قهر شو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther3_verse_005.mp3', NULL, 1761758823, 1761758823),
(38576, 'Esther 3:6', 'Esther', 3, 6, 'کله چې هغه پوه شو چې مردخای یهودي دی، هغه دا پرېکړه وکړه چې یوازې د مردخای وژل بس نه دي. هغه دا پلان جوړ کړ چې هغه ټول یهودیان چې د خشایار پاچا په ټوله امپراتورۍ کې دي، ووژل شي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther3_verse_006.mp3', NULL, 1761758823, 1761758823),
(38577, 'Esther 3:7', 'Esther', 3, 7, 'د خشایار پاچا د امپراتورۍ د دولسم کال په لومړۍ میاشت چې د نیسان میاشت وه، هامان امر وکړ چې د ده په وړاندې پوریم یعنې پچه واچوي چې د دې دسیسې د سرته رسولو دپاره کومه ورځ او کومه میاشت ښه ده. نو د دولسمې میاشتې یعنې د اذر د میاشتې دیارلسمه ورځ وټاکل شوه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther3_verse_007.mp3', NULL, 1761758823, 1761758823),
(38578, 'Esther 3:8', 'Esther', 3, 8, 'نو هامان خشایار پاچا ته وویل: «یو قوم دی چې ستاسو د امپراتورۍ د ټولو ولایتونو د قومونو په منځ کې خپور شوی دی چې دود یې د هغو ټولو قومونو نه فرق لري او د پاچا د قانون څخه اطاعت نه کوي، دا د پاچا په ګټه نه ده چې هغوی وزغمي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther3_verse_008.mp3', NULL, 1761758823, 1761758823),
(38579, 'Esther 3:9', 'Esther', 3, 9, 'که ستاسو اعلیحضرت خوښه وي، یو فرمان جاري کړئ چې هغوی ووژل شي. که تاسو دا کار وکړئ، نو زه وعده کوم چې درې سوه څلوېښت ټنه سپین زر به د شاهي اداري چارو دپاره شاهي خزانې ته ورکړم.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther3_verse_009.mp3', NULL, 1761758823, 1761758823),
(38580, 'Esther 3:10', 'Esther', 3, 10, 'پاچا خپله د مهر ګوته چې په هغې باندې د پاچا فرمانونه مهر کېدل، د خپلې ګوتې راوویستله او هغه یې هامان د اجاجي همداتا زوی ته چې د یهودیانو دښمن ؤ، ورکړه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther3_verse_010.mp3', NULL, 1761758823, 1761758823),
(38581, 'Esther 3:11', 'Esther', 3, 11, 'پاچا هغه ته وویل: «دا قوم او د هغوی پیسې دې ستا وي، نو څنګه چې ستا خوښه وي هماغسې ورسره وکړه.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther3_verse_011.mp3', NULL, 1761758823, 1761758823),
(38582, 'Esther 3:12', 'Esther', 3, 12, 'نو د لومړۍ میاشتې په دیارلسمه ورځ هامان د پاچا منشیان راوغوښتل. هغوی د هامان امرونه هر ولایت ته د هغوی په خط او د هر قوم په ژبه د پاچا له خوا ټاکل شویو والیانو، د بېلابېلو ولایتونو نورو والیانو او د مختلفو قومونو مامورینو ته ولیکل. هغه فرمانونه د خشایار پاچا په نامه ولیکل او مهر شول.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther3_verse_012.mp3', NULL, 1761758823, 1761758823),
(38583, 'Esther 3:13', 'Esther', 3, 13, 'پیغامونه د دې امر سره د قاصدانو په وسیله د پاچا ټولو ولایتونو ته ولېږل شول چې ټول یهودیان، زوړ او ځوان، ښځې او ماشومان دې په یوه ورځ یعنې د دولسمې میاشتې په دیارلسمه نېټه چې د اذر میاشت وه، ووژل شي. هغوی دې په بې رحمۍ سره ووژل شي او د هغوی مالونه دې لوټ شي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther3_verse_013.mp3', NULL, 1761758823, 1761758823),
(38584, 'Esther 3:14', 'Esther', 3, 14, 'د فرمان د متن یو نقل دې د قانون په توګه هر ولایت ته صادر شي او د هر قوم خلکو ته دې په ډاګه شي، ترڅو هغوی د هغې ورځې دپاره تیار اوسي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther3_verse_014.mp3', NULL, 1761758823, 1761758823),
(38585, 'Esther 3:15', 'Esther', 3, 15, 'د پاچا په امر دا فرمان د شوش په بالاحصار کې خپور شو او قاصدانو دغه خبر په بیړه ولایتونو ته ورساوه. په داسې حال کې چې پاچا او هامان ناست وو او شراب یې څښل، خو د شوش په ښار کې وارخطایي او ګډوډي وه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther3_verse_015.mp3', NULL, 1761758823, 1761758823),
(38586, 'Job 17:1', 'Job', 17, 1, 'زما زور ختم شوے دے او زما ورځې لنډې شوې دى، او قبر زما دپاره تيار دے.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job17_verse_001.mp3', NULL, 1761758823, 1761758823),
(38587, 'Job 17:2', 'Job', 17, 2, 'زما نه ګېرچاپېره مسخرې کوونکى راتاو دى، او زۀ ګورم چې هغوئ ما ته سپکې خبرې کوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job17_verse_002.mp3', NULL, 1761758823, 1761758823),
(38588, 'Job 17:3', 'Job', 17, 3, 'اے خُدايه پاکه، تۀ زما ضمانت وکړه، ځکه چې بل هيڅ څوک به زما ذمه وارى وانۀ خلى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job17_verse_003.mp3', NULL, 1761758823, 1761758823),
(38589, 'Job 17:4', 'Job', 17, 4, 'ځکه چې تا د هغوئ په ذهنونو باندې پړدې لګولې دى، هغوئ مۀ پرېږده چې په ما غالب شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job17_verse_004.mp3', NULL, 1761758823, 1761758823),
(38590, 'Job 17:5', 'Job', 17, 5, 'څوک چې د خپلې فائدې دپاره دوستان دوکه کوى، نو د هغوئ د اولاد سترګې به ړندې شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job17_verse_005.mp3', NULL, 1761758823, 1761758823),
(38591, 'Job 17:6', 'Job', 17, 6, 'خُدائ پاک زۀ د خلقو دپاره د خندا کړے يم، هغوئ زما په مخ باندې توکاڼى توکى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job17_verse_006.mp3', NULL, 1761758823, 1761758823),
(38592, 'Job 17:7', 'Job', 17, 7, 'د غم په وجه زما سترګې سرې شوې دى، او زما بدن اوچ کلک شوے دے.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job17_verse_007.mp3', NULL, 1761758823, 1761758823),
(38593, 'Job 17:8', 'Job', 17, 8, 'کله چې نېکان خلق ما وګورى نو په لړزان شى، او بې‌ګناه خلق د خُدائ پاک نه د منکرو خلقو مخالفت کوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job17_verse_008.mp3', NULL, 1761758823, 1761758823),
(38594, 'Job 17:9', 'Job', 17, 9, 'خو صادقان د خپلې لارې نه نۀ اوړى، چې صادقان ورځ په ورځ نور هم تکړه کيږى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job17_verse_009.mp3', NULL, 1761758823, 1761758823),
(38595, 'Job 17:10', 'Job', 17, 10, 'اوس تاسو ټول چرته ما ته څۀ سمه خبره وکړئ، خو بيا به هم په تاسو کښې يو هوښيار کس پېدا نۀ کړم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job17_verse_010.mp3', NULL, 1761758823, 1761758823),
(38596, 'Job 17:11', 'Job', 17, 11, 'زما دوران تېر شو او زما منصوبې ناکامه شوې، زما نه زما اُميدونه ختم شول.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job17_verse_011.mp3', NULL, 1761758823, 1761758823),
(38597, 'Job 17:12', 'Job', 17, 12, 'هغوئ د شپې نه ورځ جوړوى، او رڼا ته تيارۀ وائى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job17_verse_012.mp3', NULL, 1761758823, 1761758823),
(38598, 'Job 17:13', 'Job', 17, 13, 'زۀ د مرګ په طمع يم، او زۀ به تل په تيارۀ کښې پروت يم،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job17_verse_013.mp3', NULL, 1761758823, 1761758823),
(38599, 'Job 17:14', 'Job', 17, 14, 'کۀ زۀ قبر ته ووايم چې تۀ زما پلار يې، او چينجو ته ووايم چې تاسو زما مور يا خور يئ،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job17_verse_014.mp3', NULL, 1761758823, 1761758823),
(38600, 'Job 17:15', 'Job', 17, 15, 'نو بيا زما اُميد چرته دے؟ او دا چا ته ښکارى؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job17_verse_015.mp3', NULL, 1761758823, 1761758823),
(38601, 'Job 17:16', 'Job', 17, 16, 'نو زما ټول اُميدونه به په قبر کښې فنا شى؟ او زما ټول ارمانونه به خاورې شى څۀ؟“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job17_verse_016.mp3', NULL, 1761758823, 1761758823),
(38602, 'Job 20:1', 'Job', 20, 1, 'بيا ضوفر نعماتى ورته ووئيل،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_001.mp3', NULL, 1761758823, 1761758823),
(38603, 'Job 20:2', 'Job', 20, 2, '”زما زړۀ وائى چې جواب درکړم، ځکه چې ستا خبرو زۀ خفه کړے يم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_002.mp3', NULL, 1761758823, 1761758823),
(38604, 'Job 20:3', 'Job', 20, 3, 'تا چې څۀ وفرمائيل هغه زما بې‌عزتى ده، او زما زړۀ ما ته وائى چې جواب درکړم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_003.mp3', NULL, 1761758823, 1761758823),
(38605, 'Job 20:4', 'Job', 20, 4, 'تا ته د ډېر وخت نه د دې پته ده، د هغه وخت نه چې کله بنى آدم په زمکه پېدا شوے وو،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_004.mp3', NULL, 1761758823, 1761758823),
(38606, 'Job 20:5', 'Job', 20, 5, 'د بدعمله کس کاميابى لنډه وى، او د خُدائ پاک نه منکرو خلقو خوشحالى د لږ وخت دپاره وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_005.mp3', NULL, 1761758823, 1761758823),
(38607, 'Job 20:6', 'Job', 20, 6, 'کۀ هغوئ د آسمانونو پورې هم اوچت شوى وى، او د هغوئ سرونه وريځو ته رسېدلى وى،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_006.mp3', NULL, 1761758823, 1761758823),
(38608, 'Job 20:7', 'Job', 20, 7, 'هغوئ به د خپلو متيازو په شان د تل دپاره ختم شى، چا چې هغوئ ليدلى وى نو هغوئ به ووائى چې څۀ شول؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_007.mp3', NULL, 1761758823, 1761758823),
(38609, 'Job 20:8', 'Job', 20, 8, 'هغوئ به د يو خوب په شان تېر شى او ورک به شى، هغوئ به د شپې د خوب په شان فنا شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_008.mp3', NULL, 1761758823, 1761758823),
(38610, 'Job 20:9', 'Job', 20, 9, 'کومو خلقو چې هغوئ ليدلى وى نو هغه به يې نور ونۀ ګورى، او چې چرته اوسېدل نو د هغه ځائ خلق به يې ياد نۀ کړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_009.mp3', NULL, 1761758823, 1761758823),
(38611, 'Job 20:10', 'Job', 20, 10, 'د هغوئ د اولاد نه به هغه مال دولت واپس لاړ شى، چې کوم يې د غريبانانو نه اخستے وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_010.mp3', NULL, 1761758823, 1761758823),
(38612, 'Job 20:11', 'Job', 20, 11, 'هغوئ به په ځوانۍ کښې مړۀ شى او په خاورو کښې به ښخ شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_011.mp3', NULL, 1761758823, 1761758823),
(38613, 'Job 20:12', 'Job', 20, 12, 'په بدعملۍ کښې خوند وى، او د دې خوند تر ډېر وخته پورې وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_012.mp3', NULL, 1761758823, 1761758823),
(38614, 'Job 20:13', 'Job', 20, 13, 'او د خوږ څيز په شان يې په خولۀ کښې د ډېر وخت پورې ساتى،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_013.mp3', NULL, 1761758823, 1761758823),
(38615, 'Job 20:14', 'Job', 20, 14, 'خو ناګهانه د هغوئ خوراک په خېټه کښې تريخ شى، او د دې نه دننه زهر جوړ شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_014.mp3', NULL, 1761758823, 1761758823),
(38616, 'Job 20:15', 'Job', 20, 15, 'هغوئ مال دولت تېر کړى خو بيا يې اولټۍ کړى، خُدائ پاک د هغوئ دولت د هغوئ د خېټې نه واپس راوغورزوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_015.mp3', NULL, 1761758823, 1761758823),
(38617, 'Job 20:16', 'Job', 20, 16, 'هغوئ به د مارانو زهر وخورى، او زهرژن مار به هغوئ ووژنى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_016.mp3', NULL, 1761758823, 1761758823),
(38618, 'Job 20:17', 'Job', 20, 17, 'هغوئ به سيندونه ونۀ ګورى، هغه نِهرونه چې شات او پئ په کښې بهيږى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_017.mp3', NULL, 1761758823, 1761758823),
(38619, 'Job 20:18', 'Job', 20, 18, 'د هغوئ ناجائزه ګټه به د هغوئ نه واپس وځى، او په مال دولت باندې به خوشحالى ونۀ کړى،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_018.mp3', NULL, 1761758823, 1761758823),
(38620, 'Job 20:19', 'Job', 20, 19, 'ځکه چې هغوئ غريبانان وهلى دى او نهر يې پرېښى دى، او د هغوئ کورونه يې قبضه کړى دى کوم چې هغوئ نۀ دى جوړ کړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_019.mp3', NULL, 1761758823, 1761758823),
(38621, 'Job 20:20', 'Job', 20, 20, 'د هغوئ د حرص ختمېدل نشته، چې په څۀ خوشحاليږى نو د هغې نه به ورسره هيڅ پاتې نۀ شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_020.mp3', NULL, 1761758823, 1761758823),
(38622, 'Job 20:21', 'Job', 20, 21, 'هغوئ چې څۀ خورى نو د هغې نه هيڅ نۀ پاتې کيږى، نو په دې وجه د هغوئ مالدارى ختميږى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_021.mp3', NULL, 1761758823, 1761758823),
(38623, 'Job 20:22', 'Job', 20, 22, 'کله چې هغوئ ښۀ کامياب وى، نو د غم چپې به په هغوئ باندې راشى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_022.mp3', NULL, 1761758823, 1761758823),
(38624, 'Job 20:23', 'Job', 20, 23, 'چې کله هغوئ خپلې خېټې ډکې کړى نو خُدائ پاک دې په هغوئ باندې سخت قهر راولى، او دا قهر دې په هغوئ لکه د ږلۍ راوريږى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_023.mp3', NULL, 1761758823, 1761758823),
(38625, 'Job 20:24', 'Job', 20, 24, 'هغوئ به د اوسپنې د وسلې نه تښتى، خو د زېړو په غشى به هغوئ ولګى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_024.mp3', NULL, 1761758823, 1761758823),
(38626, 'Job 20:25', 'Job', 20, 25, 'هغه غشے د هغوئ د ملا نه وويستلے شى، او دا غشے په وينه سور وى، يره به په هغوئ باندې راشى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_025.mp3', NULL, 1761758823, 1761758823),
(38627, 'Job 20:26', 'Job', 20, 26, 'د هغوئ خزانه به په تکه توره تيارۀ کښې پټه شى، يو داسې اور به هغوئ تباه کړى چې هيچا بل کړے نۀ وى، او د هغوئ په کور کښې پاتې هر څۀ به تباه شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_026.mp3', NULL, 1761758823, 1761758823),
(38628, 'Job 20:27', 'Job', 20, 27, 'آسمانونه به د هغوئ ګناه ښکاره کړى، او زمکه به د هغوئ خِلاف ګواهى ورکوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_027.mp3', NULL, 1761758823, 1761758823),
(38629, 'Job 20:28', 'Job', 20, 28, 'يو سېلاب به د هغۀ کور يوسى، د خُدائ پاک قهر به په هغوئ سېلاب راولى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_028.mp3', NULL, 1761758823, 1761758823),
(38630, 'Job 20:29', 'Job', 20, 29, 'دا د خُدائ پاک د طرف نه د بدعمله کسانو اَنجام دے، دا د هغوئ هغه ميراث دے چې د خُدائ پاک د طرف نه يې فېصله شوې ده.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job20_verse_029.mp3', NULL, 1761758823, 1761758823),
(38631, 'Isaiah 45:1', 'Isaiah', 45, 1, 'څښتن ټاکلی دی کوروش چې شي پاچا او زور او واک یې دی ورکړی ورته چې قومونه یې تابع شي چې کړي لېرې پاچاهان له واکه څښتن به خلاصې دروازې کړي د ښار د هغه دپاره او نورې به نه بندیږي څښتن کوروش ته داسې وایي:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_001.mp3', NULL, 1761758823, 1761758823),
(38632, 'Isaiah 45:2', 'Isaiah', 45, 2, '«زه به په خپله ځمه ستا نه مخکې او هوار به کړمه غرونه زه به برنجي دروازې ماتې کړمه او اړمونه به یې د اوسپنې ټوټې ټوټې کړم', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_002.mp3', NULL, 1761758823, 1761758823),
(38633, 'Isaiah 45:3', 'Isaiah', 45, 3, 'زه به تاته خزانې درکړم د تورو تیارو ځایونو او هم به درکړم شتمني تاته د پټو ځایونو بیا به ته پوه شې چې زه څښتن د اسراییلو خدای یم څوک چې تاته کړي په نوم اواز', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_003.mp3', NULL, 1761758823, 1761758823),
(38634, 'Isaiah 45:4', 'Isaiah', 45, 4, 'ته مې ټاکلی یې ترڅو مرسته وکړې زما د خدمتګار یعقوب او مرسته وکړې زما د غوره شوي قوم اسراییلو سره سره له دې چې ته ما نه پېژنې زه په نوم اواز کومه تاته او درکوم لقب د عزت تاته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_004.mp3', NULL, 1761758823, 1761758823),
(38635, 'Isaiah 45:5', 'Isaiah', 45, 5, 'زه څښتن یم، نشته بل خدای پرته له ما سره له دې چې ته ما نه پېژنې زه به تاته درکړم توان', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_005.mp3', NULL, 1761758823, 1761758823),
(38636, 'Isaiah 45:6', 'Isaiah', 45, 6, 'د دې دپاره زه کوم دا کار چې له ختیځه تر لوېدیځه پورې ټول خلک پوه شي په دې چې زه څښتن یم او بل خدای نشته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_006.mp3', NULL, 1761758823, 1761758823),
(38637, 'Isaiah 45:7', 'Isaiah', 45, 7, 'زه خالق یم د تیارې او رڼا زه راولمه مصیبت او سوله زه څښتن یم او کوم دا ټول کارونه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_007.mp3', NULL, 1761758823, 1761758823),
(38638, 'Isaiah 45:8', 'Isaiah', 45, 8, 'ای اسمانه، ای ورېځو راووروه ته عدالت لکه باران په شان ځمکه دې پرانیستل شي ترڅو خلاصون او عدالت راشين شي او په کې وغوړیږي د عدالت او د خلاصون غوټۍ زه څښتن کوم دا ټول کارونه»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_008.mp3', NULL, 1761758823, 1761758823),
(38639, 'Isaiah 45:9', 'Isaiah', 45, 9, 'افسوس په حال د هغه چې کړي جګړه د خپل خالق سره هغه داسې دی لکه منګی چې د کلال سره کوي جګړه ایا خټه کولای شي وکړي پوښتنه د کلال څخه دا چې ته څه جوړوې؟ یا خټه ووایي کلال ته چې ته مهارت نه لرې؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_009.mp3', NULL, 1761758823, 1761758823),
(38640, 'Isaiah 45:10', 'Isaiah', 45, 10, 'افسوس په حال د هغه چا چې ووایي خپل مور او پلار ته: «تاسو ولې په دې شکل زېږولی یمه؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_010.mp3', NULL, 1761758823, 1761758823),
(38641, 'Isaiah 45:11', 'Isaiah', 45, 11, 'څښتن، سپېڅلی خدای د اسراییلو او خالق د هغوی داسې وایي: «تاسو کولای شئ پوښتنه وکړئ ما نه راتلونکي وخت په هکله خو حق نه لرئ چې پوښتنه وکړئ ما نه زما د اولادو په اړه او یا راته ووایئ چې باید څه وکړم', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_011.mp3', NULL, 1761758823, 1761758823),
(38642, 'Isaiah 45:12', 'Isaiah', 45, 12, 'زه هغه ذات یم چې مې جوړه کړله ځمکه او انسان مې خلق کړ چې په کې واوسیږي اسمانونه مې خپاره کړل په خپل لاس لمر، سپوږمۍ او ستوري دي زما فرمان کې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_012.mp3', NULL, 1761758823, 1761758823),
(38643, 'Isaiah 45:13', 'Isaiah', 45, 13, 'ما په خپله هڅولی دی کوروش چې وکړي سم او د عدالت کارونه په کومو لارو چې سفر کړي هغه هغه به سمې کړمه هغه به بېرته زما ښار اورشلیم ودان کړي او زما خلک به ازاد له اسارت کړي دا کار به وکړي کوروش په وړیا توګه نه به پیسې واخلي او نه به سوغات» داسې وایي مطلق قادر څښتن', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_013.mp3', NULL, 1761758823, 1761758823),
(38644, 'Isaiah 45:14', 'Isaiah', 45, 14, 'څښتن اسراییلو ته داسې وایي: «مال او شتمني د مصر او ایتوپیا به وي د ستاسو او د سیبا لوړ قدي خلک به غلامان وي ستاسو په زنځیرونو کې روان به وي هغوی تاسو پسې تاسو ته ټیټ به خپل سرونه کړي او اقرار به وکړي چې څښتن مل دی یوازې تاسو سره نشته بل خدای پرته له هغه نه»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_014.mp3', NULL, 1761758823, 1761758823),
(38645, 'Isaiah 45:15', 'Isaiah', 45, 15, 'ای د اسراییلو خدایه او ای ژغورونکیه په رښتیا ته هغه خدای یې چې خپل ځان پټوي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_015.mp3', NULL, 1761758823, 1761758823),
(38646, 'Isaiah 45:16', 'Isaiah', 45, 16, 'څوک چې بتان جوړوي ټول به وشرمیږي او شي به رسوا', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_016.mp3', NULL, 1761758823, 1761758823),
(38647, 'Isaiah 45:17', 'Isaiah', 45, 17, 'خو څښتن به اسراییل وژغوري او خلاصون به یې پایښت ومومي د تل دپاره د رسوایۍ سره به مخ نه شي د هغه قوم هېڅکله', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_017.mp3', NULL, 1761758823, 1761758823),
(38648, 'Isaiah 45:18', 'Isaiah', 45, 18, 'څښتن هغه خدای دی چې یې جوړ کړل اسمانونه هغه جوړه کړله ځمکه، هغه یې کړه ټینګه او کلکه جوړه یې نه کړله خالي هغه هغه یې جوړه کړه د دې دپاره چې په کې واوسیږي خلک دا هغه ذات دی چې داسې وایي: «زه یم څښتن او نشته بل خدای', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_018.mp3', NULL, 1761758823, 1761758823),
(38649, 'Isaiah 45:19', 'Isaiah', 45, 19, 'ما نه دي کړې پټې خبرې پټ مې ساتلی نه دی خپل مقصد د یعقوب اولادې ته مې ویلي نه دي چې ما لټوئ بېځایه زه څښتن یم او رښتیا وایم او اعلانوم زه حق»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_019.mp3', NULL, 1761758823, 1761758823),
(38650, 'Isaiah 45:20', 'Isaiah', 45, 20, 'څښتن وایي: «ای له قومونو پاتې شویو ژوندي خلکو شئ راټول او راشئ زما حضور ته! چې ګرځوي څوک د لرګیو بتان د خپل ځانه سره دعا کوي هغو خدایانو ته چې دوی ژغورلی نه شي هغوی جاهل دي او په هېڅ نه پوهیږي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_020.mp3', NULL, 1761758823, 1761758823),
(38651, 'Isaiah 45:21', 'Isaiah', 45, 21, 'راشئ او خپله دعوه وړاندې کړئ په محکمه کې خلک پرېږدئ چې مشوره وکړي یو د بله سره چا وه کړې پېشګویي له ډېر پخوا نه چې څه به کیږي؟ ایا هغه څښتن زه نه وم؟ زه ژغورونکی او عادل خدای یم زما نه پرته بل خدای نشته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_021.mp3', NULL, 1761758823, 1761758823),
(38652, 'Isaiah 45:22', 'Isaiah', 45, 22, 'ای د ټولې نړۍ خلکو راستانه شئ ماته ترڅو وژغورل شئ ځکه چې زه یوازېنی خدای یم او زما نه پرته بل خدای نشته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_022.mp3', NULL, 1761758823, 1761758823),
(38653, 'Isaiah 45:23', 'Isaiah', 45, 23, 'ما په خپل ذات باندې قسم خوړلی زما وعده ده رښتیا او د باور وړ ده او تل هغې ته وفادار یم هر یو راځي به او په ګونډو به شي زما په مخکې او هره ژبه به قسم خوري زما په نوم', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_023.mp3', NULL, 1761758823, 1761758823),
(38654, 'Isaiah 45:24', 'Isaiah', 45, 24, 'خلک به وایي چې بری او توان یوازې څښتن پورې اړه لري هرڅوک چې په قهر دي په ما باندې هغوی به راشي زما حضور ته او هغوی به وشرمیږي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_024.mp3', NULL, 1761758823, 1761758823),
(38655, 'Isaiah 45:25', 'Isaiah', 45, 25, 'بریالی به شي ټول قوم د اسراییلو د څښتن په وسیله او خوشحالي به هغوی وکړي د هغه په خاطر»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah45_verse_025.mp3', NULL, 1761758823, 1761758823),
(38656, 'Ruth 2:1', 'Ruth', 2, 1, 'نعومي یو شتمن او مهم خپلوان درلود چې بوعز نومېده چې د هغې د مېړه الیملک د کورنۍ څخه ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ruth2_verse_001.mp3', NULL, 1761758823, 1761758823),
(38657, 'Ruth 2:2', 'Ruth', 2, 2, 'یوه ورځ روت نعومي ته وویل: «که ستا خوښه وي زه به پټیو ته لاړه شم او هغه وږي به راټول کړم چې د لوګرو څخه پاتې شوي دي. زه باور لرم داسې یو څوک به پیدا کړم چې ماته د دې کار د کولو اجازه راکړي.» نعومي ځواب ورکړ: «ځه لورې لاړه شه.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ruth2_verse_002.mp3', NULL, 1761758823, 1761758823),
(38658, 'Ruth 2:3', 'Ruth', 2, 3, 'نو روت پټیو ته لاړه، د لوګرو پسې روانه شوه او هغه وږي یې راټولول چې د دوی څخه به پاتې کېدل. په هغو پټیو کې چې هغې کار کاوه، هغه د بوعز وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ruth2_verse_003.mp3', NULL, 1761758823, 1761758823),
(38659, 'Ruth 2:4', 'Ruth', 2, 4, 'څه وخت وروسته بوعز په خپله د بیت لحم نه راغی او لوګرو ته یې وویل: «څښتن مو مل شه!» هغوی ورته په ځواب کې وویل: «څښتن دې تاته برکت درکړي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ruth2_verse_004.mp3', NULL, 1761758823, 1761758823),
(38660, 'Ruth 2:5', 'Ruth', 2, 5, 'بوعز د لوګرو د مشر څخه پوښتنه وکړه: «هغه ځوانه ښځه څوک ده؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ruth2_verse_005.mp3', NULL, 1761758823, 1761758823),
(38661, 'Ruth 2:6', 'Ruth', 2, 6, 'سړي په ځواب کې وویل: «دا هغه موآبۍ ښځه ده چې د نعومي سره د موآب نه راغلې ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ruth2_verse_006.mp3', NULL, 1761758823, 1761758823),
(38662, 'Ruth 2:7', 'Ruth', 2, 7, 'هغې زما څخه اجازه وغوښتله چې لاړه شي او هغه وږي راټول کړي چې د لوګرو څخه پاتې کیږي. هغه د سهار وختي نه تر اوسه پورې کار کوي او همدا اوس یې کار بس کړ چې د جونګړې لاندې لږ ارام وکړي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ruth2_verse_007.mp3', NULL, 1761758823, 1761758823),
(38663, 'Ruth 2:8', 'Ruth', 2, 8, 'نو بیا بوعز روت ته ورغی او ویې ویل: «زه فکر کوم تاته به دا ډېره ښه وي چې د بل چا په پټیو کې وږي راټول نه کړې. ته همدلته د ښځو سره پاتې شه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ruth2_verse_008.mp3', NULL, 1761758823, 1761758823),
(38664, 'Ruth 2:9', 'Ruth', 2, 9, 'او زما په پټیو کې د لوګرو پسې وږي راټول کړه. ما سړیو ته امر کړی چې تا ونه ځوروي او هرکله چې تږې کېږې، د هغو منګیو څخه اوبه څښلی شې چې هغوی ډک کړي دي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ruth2_verse_009.mp3', NULL, 1761758823, 1761758823),
(38665, 'Ruth 2:10', 'Ruth', 2, 10, 'روت د درناوي په خاطر ټیټه شوه او ویې ویل: «ته پوهېږې چې زه د بل هېواد څخه راغلې یم. ته ولې زما سره دومره نېکي کوې؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ruth2_verse_010.mp3', NULL, 1761758823, 1761758823),
(38666, 'Ruth 2:11', 'Ruth', 2, 11, 'بوعز په ځواب کې وویل: «ما د ټولو هغو شیانو په هکله اورېدلي دي چې تا د خپلې خواښې دپاره د خپل مېړه د مرګ څخه وروسته تر سره کړي دي. زه پوهېږم چې څنګه تا خپله مور او پلار او خپل هېواد پرېښود او څنګه راغلې، ترڅو د داسې خلکو په منځ کې واوسېږې چې تا پخوا هېڅ نه پېژندل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ruth2_verse_011.mp3', NULL, 1761758823, 1761758823),
(38667, 'Ruth 2:12', 'Ruth', 2, 12, 'زه دعا کوم چې څښتن دې د دې کار دپاره تاته اجر درکړي. د اسراییلو څښتن خدای چې تا ورته پناه وروړې ده، د دې کار پوره اجر درکړي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ruth2_verse_012.mp3', NULL, 1761758823, 1761758823),
(38668, 'Ruth 2:13', 'Ruth', 2, 13, 'روت په ځواب کې وویل: «باداره، دا ستا ډېره نېکي ده چې ته په ډېرې مهربانۍ سره زما سره خبرې کوې او زما هرکلی کوې، زه حتی ستا د یوې وینځې برابره هم نه یم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ruth2_verse_013.mp3', NULL, 1761758823, 1761758823),
(38669, 'Ruth 2:14', 'Ruth', 2, 14, 'د ډوډۍ خوړلو په وخت کې بوعز روت ته وویل: «راځه مونږ سره ډوډۍ وخوره. لږه ډوډۍ واخله او په سرکه کې یې لمده کړه.» هغه د لوګرو سره کښېناستله او بوعز هغې ته وریتې شوې غلې دانې ورکړې، روت چې څومره غوښتل ویې خوړې او لږې ورڅخه پاتې هم شوې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ruth2_verse_014.mp3', NULL, 1761758823, 1761758823),
(38670, 'Ruth 2:15', 'Ruth', 2, 15, 'وروسته د هغې چې روت د وږو د راټولولو دپاره لاړه، بوعز خپلو سړیو ته وویل: «هغه پرېږدئ چې د ګېډیو څخه هم وږي واخلي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ruth2_verse_015.mp3', NULL, 1761758823, 1761758823),
(38671, 'Ruth 2:16', 'Ruth', 2, 16, 'د ګېډیو څخه هم یو څه وږي راوباسئ او ورته یې پرېږدئ او د هغې سره سختې خبرې مه کوئ!»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ruth2_verse_016.mp3', NULL, 1761758823, 1761758823),
(38672, 'Ruth 2:17', 'Ruth', 2, 17, 'نو روت په پټیو کې تر ماښامه پورې کار وکړ. کله چې هغې ټول وږي وټکول، نو هغه لس کیلو ګرامه وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ruth2_verse_017.mp3', NULL, 1761758823, 1761758823),
(38673, 'Ruth 2:18', 'Ruth', 2, 18, 'هغې دا وږي ښار ته یووړل او خپلې خواښې ته یې وروښودل چې څومره یې راټول کړي وو. روت هغه ډوډۍ هم ورته ورکړه چې د غرمې نه پاتې شوې وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ruth2_verse_018.mp3', NULL, 1761758823, 1761758823),
(38674, 'Ruth 2:19', 'Ruth', 2, 19, 'نعومي وویل: «تا نن چېرته او د چا په پټیو کې کار وکړ؟ خدای دې هغه سړي ته برکت ورکړي چې ستا سره یې ډېر ښه چلند وکړ!» بیا روت هغې ته وویل: «ما د یو سړي په پټیو کې کار وکړ چې بوعز نومېده.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ruth2_verse_019.mp3', NULL, 1761758823, 1761758823),
(38675, 'Ruth 2:20', 'Ruth', 2, 20, 'نعومي په ځواب کې وویل: «څښتن دې بوعز ته برکت ورکړي! څښتن تل د مړو او ژوندیو سره وفادار دی.» نعومي زیاته کړه: «بوعز زمونږ د هغو نژدې خپلوانو د ډلې څخه دی چې زمونږ ساتنه کوي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ruth2_verse_020.mp3', NULL, 1761758823, 1761758823),
(38676, 'Ruth 2:21', 'Ruth', 2, 21, 'روت هغې ته وویل: «بوعز حتی ماته وویل چې د لو تر خلاصېدلو پورې زما د لوګرو سره وږي راټولوه.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ruth2_verse_021.mp3', NULL, 1761758823, 1761758823),
(38677, 'Ruth 2:22', 'Ruth', 2, 22, 'نعومي په ځواب کې وویل: «زما لورې دا ښه خبره ده چې ته د هغو ښځو سره وږي راټول کړې چې د بوعز په پټیو کې کار کوي، ځکه کېدای شي د بل چا په پټیو کې ستا سره بد چلند وشي!»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ruth2_verse_022.mp3', NULL, 1761758823, 1761758823),
(38678, 'Ruth 2:23', 'Ruth', 2, 23, 'نو بیا روت د کار کولو په وخت کې نورو ښځو سره نژدې اوسېدله. روت تر هغه وخته پورې په پټیو کې کار کاوه، ترڅو چې ټولې اوربشې او غنم ورېبل شول. په دې ټوله موده کې هغه د خپلې خواښې سره اوسېدله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ruth2_verse_023.mp3', NULL, 1761758823, 1761758823),
(38679, 'Genesis 25:1', 'Genesis', 25, 1, 'ابراهیم بله ښځه وکړه چې نوم یې قطوره ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_001.mp3', NULL, 1761758823, 1761758823),
(38680, 'Genesis 25:2', 'Genesis', 25, 2, 'د هغې څخه د ابراهیم زامن زمران، یقشان، مدان، مدیان، یشباق او شوحا پیدا شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_002.mp3', NULL, 1761758823, 1761758823),
(38681, 'Genesis 25:3', 'Genesis', 25, 3, 'یقشان د شیبا او ددان پلار ؤ او آشوریم، لطوشیم او لیومیم د ددان اولاده وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_003.mp3', NULL, 1761758823, 1761758823),
(38682, 'Genesis 25:4', 'Genesis', 25, 4, 'عیفه، عیفر، حنوک، ابیداع او الداعه د مدیان زامن وو. دا ټول د قطورې اولاده وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_004.mp3', NULL, 1761758823, 1761758823),
(38683, 'Genesis 25:5', 'Genesis', 25, 5, 'ابراهیم خپله ټوله شتمني اسحاق ته پرېښودله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_005.mp3', NULL, 1761758823, 1761758823),
(38684, 'Genesis 25:6', 'Genesis', 25, 6, 'خو هغه لا ژوندی ؤ چې د خپلو وینځو زامنو ته یې سوغاتونه ورکړل او هغوی یې د خپل زوی اسحاق څخه د ختیځ خواته لېرې ولېږل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_006.mp3', NULL, 1761758823, 1761758823),
(38685, 'Genesis 25:7', 'Genesis', 25, 7, 'ابراهیم پوره یوسلو پنځه اویا کاله ژوند وکړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_007.mp3', NULL, 1761758823, 1761758823),
(38686, 'Genesis 25:8', 'Genesis', 25, 8, 'هغه په پاخه عمر کې مړ شو او د خپلو نیکونو سره یوځای شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_008.mp3', NULL, 1761758823, 1761758823),
(38687, 'Genesis 25:9', 'Genesis', 25, 9, 'د هغه زامنو اسحاق او اسماعیل هغه ممري ته نژدې د حیتي صوحار د زوی عفرون په پټي کې د مکفیله په سمڅه کې ښخ کړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_009.mp3', NULL, 1761758823, 1761758823),
(38688, 'Genesis 25:10', 'Genesis', 25, 10, 'دا هغه پټی ؤ چې ابراهیم د حیتیانو څخه په بیه اخیستی ؤ. ابراهیم او د هغه ښځه ساره دواړه په هغه کې ښخ کړای شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_010.mp3', NULL, 1761758823, 1761758823),
(38689, 'Genesis 25:11', 'Genesis', 25, 11, 'د ابراهیم د مرګ څخه وروسته خدای د هغه زوی اسحاق ته برکت ورکړ او اسحاق بئرلحي ریي ته نژدې اوسېده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_011.mp3', NULL, 1761758823, 1761758823),
(38690, 'Genesis 25:12', 'Genesis', 25, 12, 'دا د ابراهیم د زوی اسماعیل اولاده ده. دا هغه اسماعیل ؤ چې د ساره د مصرۍ وینځې هاجرې څخه پیدا شوی ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_012.mp3', NULL, 1761758823, 1761758823),
(38691, 'Genesis 25:13', 'Genesis', 25, 13, 'د اسماعیل د زامنو نومونه د هغوی د زېږېدلو د ترتیب له مخې چې په لست کې لیکل شوي دي دا دي: د اسماعیل مشر زوی نبایوت، قیدار، ادبیل، مبسام،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_013.mp3', NULL, 1761758823, 1761758823),
(38692, 'Genesis 25:14', 'Genesis', 25, 14, 'مشماع، دومه، مسا،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_014.mp3', NULL, 1761758823, 1761758823),
(38693, 'Genesis 25:15', 'Genesis', 25, 15, 'حداد، تیما، یطور، نافیش او قدمه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_015.mp3', NULL, 1761758823, 1761758823),
(38694, 'Genesis 25:16', 'Genesis', 25, 16, 'دا د اسماعیل زامن وو او دا د دولسو قبیلو د مشرانو نومونه وو چې د هغوی د کلیو او کمپونو له مخې وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_016.mp3', NULL, 1761758823, 1761758823),
(38695, 'Genesis 25:17', 'Genesis', 25, 17, 'اسماعیل پوره د یوسلو اووه دېرشو کالو په عمر مړ شو او د خپلو نیکونو سره یوځای شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_017.mp3', NULL, 1761758823, 1761758823),
(38696, 'Genesis 25:18', 'Genesis', 25, 18, 'د هغه اولاده د شور او حویلې ترمنځ سیمه کې اوسېدله چې د مصر پولې ته نژدې د آشور په لاره پرته ده. هغوی د خپلو ټولو ورونو سره په دښمنۍ کې ژوند کاوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_018.mp3', NULL, 1761758823, 1761758823),
(38697, 'Genesis 25:19', 'Genesis', 25, 19, 'دا د ابراهیم د زوی اسحاق اولاده ده: د ابراهیم څخه اسحاق پیدا شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_019.mp3', NULL, 1761758823, 1761758823),
(38698, 'Genesis 25:20', 'Genesis', 25, 20, 'اسحاق د څلوېښتو کالو په عمر ؤ چې د ربکا سره یې واده وکړ. هغه د آرامي بتوییل چې د بین‌النهرین څخه ؤ، لور او د لابان خور وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_020.mp3', NULL, 1761758823, 1761758823),
(38699, 'Genesis 25:21', 'Genesis', 25, 21, 'اسحاق د خپلې ښځې په خاطر چې شنډه وه، څښتن ته دعا وکړه. څښتن د هغه دعا قبوله کړه او د هغه ښځه ربکا امیدواره شوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_021.mp3', NULL, 1761758823, 1761758823),
(38700, 'Genesis 25:22', 'Genesis', 25, 22, 'مخکې له دې چې ربکا اولاد وزېږوي، هغه پوه شوه چې هغه به غبرګوني وزېږوي، ځکه چې هغې دا احساس کړه چې هغوی د مور په نس کې یو د بل سره جګړه کوي. هغې وویل: «زما سره ولې داسې کیږي؟» نو هغې د څښتن څخه پوښتنه وکړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_022.mp3', NULL, 1761758823, 1761758823),
(38701, 'Genesis 25:23', 'Genesis', 25, 23, 'څښتن هغې ته وویل: ستا دواړو زامنو څخه جوړ به شي دوه رقیب قومونه هغو دواړو کې به کشر وي قوي او مشر به وي غلام د هغه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_023.mp3', NULL, 1761758823, 1761758823),
(38702, 'Genesis 25:24', 'Genesis', 25, 24, 'کله چې د هغې د اولاد د زېږولو وخت راورسېد، د هغې څخه غبرګوني پیدا شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_024.mp3', NULL, 1761758823, 1761758823),
(38703, 'Genesis 25:25', 'Genesis', 25, 25, 'لومړنی زوی چې پیدا شو، هغه سور ؤ او د هغه ټول بدن لکه د ببرې چپنې په شان ؤ، نو د هغه نوم یې عیسو کېښود.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_025.mp3', NULL, 1761758823, 1761758823),
(38704, 'Genesis 25:26', 'Genesis', 25, 26, 'د هغه څخه وروسته د هغه ورور پیدا شو او هغه د عیسو پونده په خپل لاس کې کلکه نیولې وه، نو ځکه د هغه نوم یعقوب شو. اسحاق د شپېتو کالو په عمر ؤ چې دوی پیدا شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_026.mp3', NULL, 1761758823, 1761758823),
(38705, 'Genesis 25:27', 'Genesis', 25, 27, 'هلکان لوی شول. عیسو یو تکړه ښکاري او داسې سړی ؤ چې صحرا یې خوښېدله، خو یعقوب یو ارام سړی ؤ او د کور څخه به نه وت.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_027.mp3', NULL, 1761758823, 1761758823),
(38706, 'Genesis 25:28', 'Genesis', 25, 28, 'اسحاق د عیسو سره مینه کوله، ځکه چې هغه د هغو حیواناتو غوښه خوړله چې عیسو به ښکار کول. خو په ربکا باندې یعقوب ګران ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_028.mp3', NULL, 1761758823, 1761758823),
(38707, 'Genesis 25:29', 'Genesis', 25, 29, 'یوه ورځ یعقوب د قورمې په پخولو باندې بوخت ؤ. عیسو د ښکار څخه راغی او ډېر وږی ؤ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_029.mp3', NULL, 1761758823, 1761758823),
(38708, 'Genesis 25:30', 'Genesis', 25, 30, 'او یعقوب ته یې وویل: «زه د لوږې له لاسه مړ کېږم، د دې لوبیا له قورمې څخه لږه راکړه!» (په دې خاطر یې په هغه باندې د ادوم نوم هم کېښود.)', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_030.mp3', NULL, 1761758823, 1761758823),
(38709, 'Genesis 25:31', 'Genesis', 25, 31, 'یعقوب ځواب ورکړ: «لومړی په ما باندې خپل د مشرتوب حق خرڅ کړه.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_031.mp3', NULL, 1761758823, 1761758823),
(38710, 'Genesis 25:32', 'Genesis', 25, 32, 'عیسو وویل: «ګوره، زه مړ کېږم. دا مشرتوب ماته څه ګټه رسوي؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_032.mp3', NULL, 1761758823, 1761758823),
(38711, 'Genesis 25:33', 'Genesis', 25, 33, 'خو یعقوب وویل: «لومړی ماته قسم وخوره.» نو هغه قسم وخوړ او خپل د مشرتوب حق یې په یعقوب باندې خرڅ کړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_033.mp3', NULL, 1761758823, 1761758823),
(38712, 'Genesis 25:34', 'Genesis', 25, 34, 'بیا یعقوب عیسو ته لږه ډوډۍ او قورمه ورکړه. هغه خوراک او څښاک وکړ، بیا پاڅېده او لاړ. نو عیسو د خپل مشرتوب حق ته په سپکه سترګه وکتل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis25_verse_034.mp3', NULL, 1761758823, 1761758823),
(38713, 'Genesis 12:1', 'Genesis', 12, 1, 'څښتن ابرام ته وویل: «خپل وطن، خپلوان او د خپل پلار کور پرېږده او هغه هېواد ته لاړ شه چې زه یې درته ښایم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis12_verse_001.mp3', NULL, 1761758823, 1761758823),
(38714, 'Genesis 12:2', 'Genesis', 12, 2, 'زه به ستا څخه لوی قوم جوړ کړم او برکت به درکړم. ستا نوم به مشهور کړم او د نورو دپاره به د برکت سبب وګرځې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis12_verse_002.mp3', NULL, 1761758823, 1761758823),
(38715, 'Genesis 12:3', 'Genesis', 12, 3, 'څوک چې تاته درکوي برکت زه به ورکړمه هغوی ته برکت خو څوک چې ووایي په تا باندې لعنت زه به ووایم هغوی باندې لعنت او وربه کړم ستا په وسیله برکت ټولو قومونو د دنیا ته»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis12_verse_003.mp3', NULL, 1761758823, 1761758823),
(38716, 'Genesis 12:4', 'Genesis', 12, 4, 'لکه څنګه چې څښتن ابرام ته ویلي وو، هغه لاړ او لوط هم ورسره لاړ. ابرام د پنځه اویا کالو په عمر ؤ چې د حران څخه روان شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis12_verse_004.mp3', NULL, 1761758823, 1761758823),
(38717, 'Genesis 12:5', 'Genesis', 12, 5, 'ابرام خپله ښځه سارای، خپل وراره لوط، خپل غلامان او هغه ټوله شتمني چې په حران کې یې پیدا کړې وه، د ځان سره واخیستل او کنعان ته روان شول. کله چې هلته ورسېدل،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis12_verse_005.mp3', NULL, 1761758823, 1761758823),
(38718, 'Genesis 12:6', 'Genesis', 12, 6, 'ابرام په هغې خاوره کې ګرځېده، ترڅو د موره سپېڅلې ونې ته چې هغه په شکیم کې یو پاک ځای ؤ، ورسېده. (په هغه وخت کې په هغې خاورې کې کنعانیان اوسېدل.)', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis12_verse_006.mp3', NULL, 1761758823, 1761758823),
(38719, 'Genesis 12:7', 'Genesis', 12, 7, 'څښتن ابرام ته ښکاره شو او هغه ته یې وویل: «دا هغه وطن دی چې زه غواړم هغه ستا اولادې ته ورکړم.» نو ابرام په هغه ځای کې چې څښتن ورته ورښکاره شوی ؤ، د قربانۍ ځای جوړ کړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis12_verse_007.mp3', NULL, 1761758823, 1761758823),
(38720, 'Genesis 12:8', 'Genesis', 12, 8, 'بیا یې هغې غرنۍ سیمې ته کډه وکړه چې د لمرپرېواته خوا څخه بیت‌ییل او د لمرخاته خوا څخه عای ته رسیږي. ابرام په هغه ځای کې خپلې خېمې ودرولې او هلته یې د قربانۍ ځای جوړ کړ او د څښتن عبادت یې وکړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis12_verse_008.mp3', NULL, 1761758823, 1761758823),
(38721, 'Genesis 12:9', 'Genesis', 12, 9, 'بیا هغه د یو ځای څخه بل ځای ته کډه کوله او د کنعان جنوب خواته لاړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis12_verse_009.mp3', NULL, 1761758823, 1761758823),
(38722, 'Genesis 12:10', 'Genesis', 12, 10, 'خو په کنعان کې قحطي راغله او هغه دومره سخته شوه چې ابرام مصر ته لاړ چې هلته د لږ وخت دپاره واوسیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis12_verse_010.mp3', NULL, 1761758823, 1761758823),
(38723, 'Genesis 12:11', 'Genesis', 12, 11, 'کله چې هغه د مصر سرحد ته ورنژدې شو، خپلې ښځې سارای ته یې وویل: «ته ښایسته ښځه یې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis12_verse_011.mp3', NULL, 1761758823, 1761758823),
(38724, 'Genesis 12:12', 'Genesis', 12, 12, 'کله چې مصریان تا وویني، وبه وایي: ‹دا د هغه ښځه ده.› نو دوی به ما ووژني او تا به ژوندۍ پرېږدي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis12_verse_012.mp3', NULL, 1761758823, 1761758823),
(38725, 'Genesis 12:13', 'Genesis', 12, 13, 'هغوی ته ووایه چې ته زما خور یې، نو ستا په خاطر به هغوی زما سره ښه چلند وکړي او ما به ژوندی پرېږدي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis12_verse_013.mp3', NULL, 1761758823, 1761758823),
(38726, 'Genesis 12:14', 'Genesis', 12, 14, 'کله چې هغه مصر ته ورننوت، مصریانو ولیدل چې د هغه ښځه ډېره ښایسته وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis12_verse_014.mp3', NULL, 1761758823, 1761758823),
(38727, 'Genesis 12:15', 'Genesis', 12, 15, 'کله چې د فرعون درباریانو هغه ولیدله، هغوی د فرعون په مخکې د هغې صفت وکړ او هغه یې د فرعون ماڼۍ ته وروستله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis12_verse_015.mp3', NULL, 1761758823, 1761758823),
(38728, 'Genesis 12:16', 'Genesis', 12, 16, 'فرعون د هغې په خاطر د ابرام سره ښه چلند وکړ او هغه ته یې رمې او پادې، خره او خرې، اوښان، وینځې او غلامان ورکړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis12_verse_016.mp3', NULL, 1761758823, 1761758823),
(38729, 'Genesis 12:17', 'Genesis', 12, 17, 'خو څښتن فرعون او د هغه درباریان د ابرام د ښځې سارای په سبب په خطرناکو ناروغیو باندې اخته کړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis12_verse_017.mp3', NULL, 1761758823, 1761758823),
(38730, 'Genesis 12:18', 'Genesis', 12, 18, 'نو فرعون ابرام راوغوښت او د هغه څخه یې پوښتنه وکړه: «زما سره دې څه وکړل؟ ولې دې ماته ونه ویل چې هغه ستا ښځه ده؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis12_verse_018.mp3', NULL, 1761758823, 1761758823),
(38731, 'Genesis 12:19', 'Genesis', 12, 19, 'ولې دې وویل چې هغه ستا خور ده، کېدای شو چې ما د هغې سره واده کړی وای؟ ګوره، دا ستا ښځه ده. هغه واخله او لاړ شه!»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis12_verse_019.mp3', NULL, 1761758823, 1761758823),
(38732, 'Genesis 12:20', 'Genesis', 12, 20, 'فرعون خپلو کسانو ته حکم وکړ چې ابرام او د هغه ښځه د هر هغه څه سره چې درلودل یې، ولېږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis12_verse_020.mp3', NULL, 1761758823, 1761758823),
(38733, 'Psalms 138:1', 'Psalms', 138, 1, 'د زړه د اخلاصه دې وباسم شکر ای څښتنه نورو خدایانو مخکې زه وایم ستا د ثنا سندره', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms138_verse_001.mp3', NULL, 1761758823, 1761758823),
(38734, 'Psalms 138:2', 'Psalms', 138, 2, 'کوم سجده ستا د سپېڅلي کور په لور او ثنا او صفت دې د نامه کومه ستا د تلپاتې مینې او وفادارۍ په خاطر ځکه خپل نوم او خپل کلام دې کړ اوچت ټولو شیانو باندې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms138_verse_002.mp3', NULL, 1761758823, 1761758823),
(38735, 'Psalms 138:3', 'Psalms', 138, 3, 'چې کله سوال درته ما کړی قبول کړی دی تا په خپل قدرت دې قوي کړی یم زه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms138_verse_003.mp3', NULL, 1761758823, 1761758823),
(38736, 'Psalms 138:4', 'Psalms', 138, 4, 'د نړۍ ټول پاچاهان به ستا ستاینه کوي ای څښتنه په دې خاطر چې ستا کلام دی اورېدلی هغوی', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms138_verse_004.mp3', NULL, 1761758823, 1761758823),
(38737, 'Psalms 138:5', 'Psalms', 138, 5, 'وایي سندرې به هغوی هغو کارو په هکله کوم چې کړي دي تا ځکه چې لوی دی ستا جلال', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms138_verse_005.mp3', NULL, 1761758823, 1761758823),
(38738, 'Psalms 138:6', 'Psalms', 138, 6, 'سره له دې چې ډېر عظیم یې ته خو پام کوې په عاجزانو باندې خو کبرجن خلک ته پېژنې له لېرې څخه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms138_verse_006.mp3', NULL, 1761758823, 1761758823),
(38739, 'Psalms 138:7', 'Psalms', 138, 7, 'کله چې زه لاس او ګرېوان یم تکلیفونو سره ته مې خوندي ساتې ته ودرېږې زما د قهرجنو دښمنانو مخې ته او بچ کوې مې ته په خپل قوي لاسونو باندې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms138_verse_007.mp3', NULL, 1761758823, 1761758823),
(38740, 'Psalms 138:8', 'Psalms', 138, 8, 'ته به سرته رسوې خپل مقصد زما دپاره ده ابدي ستا مینه ای څښتنه تا پیدا کړي یو او مونږ مه پرېږده ته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms138_verse_008.mp3', NULL, 1761758823, 1761758823),
(38741, 'Jeremiah 25:1', 'Jeremiah', 25, 1, 'يرمياه ته د يهوداه بادشاه د يوسياه د زوئ يهويقيم د بادشاهۍ په څلورم کال، د يهوداه د ټولو خلقو په حقله د مالِک خُدائ د طرف نه پېغام ورکړے شو. په هم دغه کال باندې نبوکدنضر د بابل په تخت کښېناستو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_001.mp3', NULL, 1761758823, 1761758823),
(38742, 'Jeremiah 25:2', 'Jeremiah', 25, 2, 'نو بيا يرمياه نبى د يروشلم ټولو اوسېدونکو او د يهوداه ټول قوم ته بيان وکړو او ورته يې وفرمائيل،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_002.mp3', NULL, 1761758823, 1761758823),
(38743, 'Jeremiah 25:3', 'Jeremiah', 25, 3, '”د يهوداه بادشاه د امون د زوئ يوسياه د بادشاهۍ د ديارلسم کال نه واخله، تر اوسه پورې مالِک خُدائ د درويشتو کالو دپاره ما ته پېغام راکړو او ما هغه تاسو ته څو ځله در رسولے دے، خو تاسو ما ته غوږ ونۀ نيولو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_003.mp3', NULL, 1761758823, 1761758823),
(38744, 'Jeremiah 25:4', 'Jeremiah', 25, 4, 'سره د دې چې مالِک خُدائ بيا بيا خپل خِدمتګاران پېغمبران رالېږلى دى، تاسو هغوئ ته نۀ غوږ نيولو او نۀ مو هغوئ ته توجو ورکوله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_004.mp3', NULL, 1761758823, 1761758823),
(38745, 'Jeremiah 25:5', 'Jeremiah', 25, 5, 'هغوئ به تاسو ته فرمائيل چې، تاسو هر يو خپلې خرابې طريقې او هغه بد کارونه پرېږدئ کوم چې تاسو کوئ، نو بيا تاسو په هغه مُلک کښې تر تله پورې اوسېدلے شئ کوم چې ما تاسو او ستاسو پلار نيکۀ له ورکړے دے.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_005.mp3', NULL, 1761758823, 1761758823),
(38746, 'Jeremiah 25:6', 'Jeremiah', 25, 6, 'هغوئ به تاسو ته فرمائيل چې د نورو معبودانو عبادت او خِدمت مۀ کوئ، تاسو چې په خپلو لاسونو کوم بُتان جوړ کړى دى هغوئ ته په عبادت کولو زما قهر مۀ راپاروئ. نو بيا به زۀ تاسو ته نقصان نۀ درکوم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_006.mp3', NULL, 1761758823, 1761758823),
(38747, 'Jeremiah 25:7', 'Jeremiah', 25, 7, 'مالِک خُدائ وفرمائيل چې، خو تاسو ما ته غوږ ونۀ نيولو، او تاسو چې څۀ جوړ کړى وُو د هغې په وجه تاسو زۀ په قهر او غصه کړم، او تاسو په خپله خپل ځان ته نقصان ورسولو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_007.mp3', NULL, 1761758823, 1761758823),
(38748, 'Jeremiah 25:8', 'Jeremiah', 25, 8, 'نو په دې وجه مالِک خُدائ ربُ الافواج داسې فرمائى چې، ځکه چې تاسو زما پېغام ته غوږ ونۀ نيولو،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_008.mp3', NULL, 1761758823, 1761758823),
(38749, 'Jeremiah 25:9', 'Jeremiah', 25, 9, 'زۀ به د شمال ټول خلق او خپل خدمتګار د بابل بادشاه نبوکدنضر د دې مُلک او په دې کښې د اوسېدونکو خلقو او د خواوشا ټولو قومونو په خلاف د جنګ دپاره راولېږم. زۀ به هغوئ بلکل تباه کړم او هغوئ به د خلقو دپاره د يرې دهشت، ټوقو، او مسخرو يو مثال وګرځوم، او په ابدى کنډرو به يې بدل کړم. مالِک خُدائ دا فرمائى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_009.mp3', NULL, 1761758823, 1761758823),
(38750, 'Jeremiah 25:10', 'Jeremiah', 25, 10, 'زۀ به د هغوئ د خندا او د خوشحالۍ چغې د دې ځائ نه خاموش کړم او زۀ به د هغوئ د وادۀ د ناوې او د زلمى د خوشحالۍ آوازونه خاموش کړم. د هغوئ د مېچونو آوازونه به خاموش کړم او د هغوئ ډيوې به مړې کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_010.mp3', NULL, 1761758823, 1761758823),
(38751, 'Jeremiah 25:11', 'Jeremiah', 25, 11, 'دا ټول مُلک به په شاړو او خرابو باندې بدل شى، او دا قومونه به د اويا کالونو دپاره د بابل د بادشاه خِدمت کوى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_011.mp3', NULL, 1761758823, 1761758823),
(38752, 'Jeremiah 25:12', 'Jeremiah', 25, 12, 'خو چې کله اويا کالونه پوره شى، نو بيا به زۀ د بابل بادشاه او د هغۀ قوم، او د هغۀ مُلک له سزا ورکړم، د هغوئ د هغه ګناهونو په وجه کوم چې هغوئ کړى دى، مالِک خُدائ دا فرمائى، او د تل دپاره به د بابل مُلک په دشته او خرابه بدل کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_012.mp3', NULL, 1761758823, 1761758823),
(38753, 'Jeremiah 25:13', 'Jeremiah', 25, 13, 'زۀ به په دې مُلک هغه ټول افتونه راولم کوم چې ما د دۀ خلاف بيان کړى دى، او په دې کِتاب کښې ليکلے شوى دى او کوم چې د يرمياه نبى په ذريعه د ټولو قومونو خلاف پېشګوئې شوې ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_013.mp3', NULL, 1761758823, 1761758823),
(38754, 'Jeremiah 25:14', 'Jeremiah', 25, 14, 'نور ډېر قومونه او غټ بادشاهان به هغوئ غلامان جوړ کړى، او زۀ به هغوئ ته هم هغه شان سزا ورکړم کومه سزا چې هغوئ نورو ته ورکړې وه.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_014.mp3', NULL, 1761758823, 1761758823),
(38755, 'Jeremiah 25:15', 'Jeremiah', 25, 15, 'مالِک خُدائ چې د بنى اِسرائيلو خُدائ پاک دے ما ته يې وفرمائيل، ”زما د لاس نه دا پيالۍ واخله چې زما د غضب د شرابو نه ډکه ده او ټولو قومونو ته چې زۀ تا استوم په هغوئ يې وڅښوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_015.mp3', NULL, 1761758823, 1761758823),
(38756, 'Jeremiah 25:16', 'Jeremiah', 25, 16, 'کله چې هغوئ دا وڅښى، نو هغوئ ټول به زنګيږى او تيندکونه به خورى او کوم جنګ چې زۀ په دوئ باندې راولم د هغې په وجه به ليونى شى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_016.mp3', NULL, 1761758823, 1761758823),
(38757, 'Jeremiah 25:17', 'Jeremiah', 25, 17, 'نو بيا ما د مالِک خُدائ د لاس نه پيالۍ واخستله او په هغه ټولو قومونو مې وڅښله چې زۀ چا ته هغۀ ورلېږلے وم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_017.mp3', NULL, 1761758823, 1761758823),
(38758, 'Jeremiah 25:18', 'Jeremiah', 25, 18, 'زۀ يروشلم او د يهوداه ټولو ښارونو او د هغوئ بادشاهانو او مشرانو له لاړم او هغوئ ټولو د غضب د پيالۍ نه وڅښل. د هغه وخت نه تر اوسه پورې، دا مُلک تباه شو، او د هغوئ دپاره د يرې او دهشت، ټوقو مسخرو شو او خلقو د هغوئ په نومونو لعنت وئيلو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_018.mp3', NULL, 1761758823, 1761758823),
(38759, 'Jeremiah 25:19', 'Jeremiah', 25, 19, 'ما دا پيالۍ فِرعون د مِصر بادشاه او د هغۀ نوکرانو او آفسرانو له او ټولو مِصريانو له ورکړه،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_019.mp3', NULL, 1761758823, 1761758823),
(38760, 'Jeremiah 25:20', 'Jeremiah', 25, 20, 'او نورو ټولو هغه پردو خلقو ته څوک چې په دې مُلک کښې اوسېدل، او د عُوض ټولو بادشاهانو ته، د فلستيه د ټولو ښارونو بادشاهانو ته لکه اسقلون، غزه، عقرون، او کوم خلق چې په اشدود کښې پاتې وُو ورکړه،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_020.mp3', NULL, 1761758823, 1761758823),
(38761, 'Jeremiah 25:21', 'Jeremiah', 25, 21, 'د ادوم، موآب او عمون قومونه ته،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_021.mp3', NULL, 1761758823, 1761758823),
(38762, 'Jeremiah 25:22', 'Jeremiah', 25, 22, 'د صور او صيدا ټولو بادشاهانو ته، او د سمندر د ساحلى علاقو بادشاهانو ته،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_022.mp3', NULL, 1761758823, 1761758823),
(38763, 'Jeremiah 25:23', 'Jeremiah', 25, 23, 'د ددان، تيما او بُوز ښارونو او هغه ټولو خلقو ته څوک چې لرې اوسېدل،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_023.mp3', NULL, 1761758823, 1761758823),
(38764, 'Jeremiah 25:24', 'Jeremiah', 25, 24, 'د عربو ټولو بادشاهانو ته او د ټولو هغه اجنبيانو بادشاهانو ته چې هلته په ريګستان کښې اوسېدل،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_024.mp3', NULL, 1761758823, 1761758823),
(38765, 'Jeremiah 25:25', 'Jeremiah', 25, 25, 'د زِمرى، عيلام او د مادى ټولو بادشاهانو ته،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_025.mp3', NULL, 1761758823, 1761758823),
(38766, 'Jeremiah 25:26', 'Jeremiah', 25, 26, 'او ما د شمال ټولو نزدې لرې بادشاهانو ته، او پرله پسې د زمکې په مخ ټولو بادشاهتونو ته ورکړه. او د دې هر څۀ نه وروستو د بابل بادشاه به يې هم وڅښى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_026.mp3', NULL, 1761758823, 1761758823),
(38767, 'Jeremiah 25:27', 'Jeremiah', 25, 27, 'بيا مالِک خُدائ ما ته وفرمائيل، ”اوس هغوئ ته ووايه چې، مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى، تاسو وڅښئ چې نشه شئ او اولټۍ وکړئ، او چې راوغورزېږئ چې بيا هيڅکله راپورته نۀ شئ ځکه چې زۀ به په تاسو جنګ راولم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_027.mp3', NULL, 1761758823, 1761758823),
(38768, 'Jeremiah 25:28', 'Jeremiah', 25, 28, 'خو کۀ هغوئ ستا د لاس د پيالۍ اخستلو او څښلو نه اِنکار وکړى، هغوئ ته ووايه، مالِک خُدائ ربُ الافواج فرمائى چې، دا پيالۍ به ضرور څښئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_028.mp3', NULL, 1761758823, 1761758823),
(38769, 'Jeremiah 25:29', 'Jeremiah', 25, 29, 'ګورئ چې ما د تباهۍ کار په يروشلم کښې شروع کړلو کوم ښار چې زما په نوم ياديږى. نو ولې تاسو به د سزا نه خلاص شئ څۀ؟ تاسو به بې‌سزا پاتې نۀ شئ، ځکه چې زۀ په ټوله زمکه کښې او د هغوئ په ټولو اوسېدونکو باندې جنګ راولم، مالِک خُدائ ربُ الافواج دا فرمائى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_029.mp3', NULL, 1761758823, 1761758823),
(38770, 'Jeremiah 25:30', 'Jeremiah', 25, 30, 'نو اوس دا ټولې خبرې د هغوئ خلاف بيان کړه او هغوئ ته ووايه چې، مالِک خُدائ به د آسمان د اوچتو او مقدسو ځايونو نه لکه د ازمرى په شان وغړمبيږى او هغه به د خپل وطن خلاف زورَور آوازونه وکړى. او هغه به داسې په تېزه آوازونه وکړى لکه څنګه چې د انګورو نچوړونکى په هغه وخت کښې شور کوى. او هغه به د هغوئ ټولو خلاف په زوره چغې ووهى څوک چې په دُنيا کښې اوسيږى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_030.mp3', NULL, 1761758823, 1761758823),
(38771, 'Jeremiah 25:31', 'Jeremiah', 25, 31, 'او د هغۀ د عدالت آواز به د دُنيا د يو سر نه تر بل سره پورې ورسيږى. ځکه چې مالِک خُدائ د قومونو خِلاف عدالت کوى. او هغه به د ټولو انسانانو فېصله واوروى او بدکاران به جنګونو ته حواله کړى. مالِک خُدائ دا فرمائى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_031.mp3', NULL, 1761758823, 1761758823),
(38772, 'Jeremiah 25:32', 'Jeremiah', 25, 32, 'ربُ الافواج داسې فرمائى چې، وګورئ، افت د يو مُلک نه بل مُلک ته پيوسته خوريږى او يو لوئ طوفان د دُنيا د بل سر نه راروان دے.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_032.mp3', NULL, 1761758823, 1761758823),
(38773, 'Jeremiah 25:33', 'Jeremiah', 25, 33, 'په هغه ورځ به چې کوم خلق مالِک خُدائ وژلى وى د هغوئ لاشونه به هر چرته د دُنيا د يو سر نه تر بل سره پورې پراتۀ وى. په هغوئ باندې به نۀ څوک ماتم کوى او نۀ به يې څوک رايوځائ کولے شى او نۀ به ښخولے شى خو په زمکه به لکه د ډيران د ډيرى په شان پراتۀ وى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_033.mp3', NULL, 1761758823, 1761758823),
(38774, 'Jeremiah 25:34', 'Jeremiah', 25, 34, 'اے د قوم شپونکو تاسو په خپل ځان باندې ژړا او ماتم وکړئ، او اے د قومونو مشرانو تاسو په خاورو ايرو کښې ورغړېږئ. ځکه ستاسو د حلالېدلو او خورېدلو وخت رارسېدلے دے. تاسو به د خټو د نازک لوښى په شان راوغورزېږئ او ټوکړې ټوکړې به شئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_034.mp3', NULL, 1761758823, 1761758823),
(38775, 'Jeremiah 25:35', 'Jeremiah', 25, 35, 'د شپونکو سره به د تېښتې دپاره يو ځائ هم نۀ وى، او د قوم د مشرانو سره به د منډې دپاره يو ځائ هم نۀ وى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_035.mp3', NULL, 1761758823, 1761758823),
(38776, 'Jeremiah 25:36', 'Jeremiah', 25, 36, 'د شپونکو ژړا انګولا واورئ، او د قوم د مشرانو ژړا او فرياد واورئ، ځکه چې مالِک خُدائ د هغوئ مُلک تباه کوى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_036.mp3', NULL, 1761758823, 1761758823),
(38777, 'Jeremiah 25:37', 'Jeremiah', 25, 37, 'د مالِک خُدائ د يروونکى قهر په وجه به د آرام ځايونه خراب شى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_037.mp3', NULL, 1761758823, 1761758823),
(38778, 'Jeremiah 25:38', 'Jeremiah', 25, 38, 'مالِک خُدائ لکه د يو طاقتور ازمرى په شان کله چې د خپل غار نه راوځى او په خلقو حمله وکړى نو دغه شان به د ظالم تيره تُوره او د مالِک خُدائ سخت قهر به د هغوئ مُلک تباه کړى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah25_verse_038.mp3', NULL, 1761758823, 1761758823),
(38779, 'Jeremiah 12:1', 'Jeremiah', 12, 1, 'اے مالِکه خُدايه، تۀ همېشه ما سره اِنصاف کوې کله چې زۀ يوه مسئله ستا په حضور کښې وړاندې کړم. نو ما ته د مقدمې کولو اجازت راکړه، نو دا بدکاران ولې دومره ترقى کوى؟ او ولې ټول غداران دومره په آرام ژوند تېروى؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah12_verse_001.mp3', NULL, 1761758823, 1761758823),
(38780, 'Jeremiah 12:2', 'Jeremiah', 12, 2, 'تا هغوئ کَرلى دى او دوئ جرړې کړې دى، دا لوئ شى او مېوه ونيسى. تۀ هر وخت د هغوئ په خولۀ يې، خو د هغوئ د زړونو نه لرې يې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah12_verse_002.mp3', NULL, 1761758823, 1761758823),
(38781, 'Jeremiah 12:3', 'Jeremiah', 12, 3, 'خو اے مالِکه خُدايه، تۀ ما پېژنې، او تۀ ما وينې او تۀ په ما آزمېښت وکړه چې زۀ ستا يم. دا بدعمله خلق داسې راکاږه لکه څنګه چې يو ګډ د حلالولو دپاره راښکلے شى، او د حلالولو پورې يې يوې خوا ته وساته.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah12_verse_003.mp3', NULL, 1761758823, 1761758823),
(38782, 'Jeremiah 12:4', 'Jeremiah', 12, 4, 'دا زمکه به تر کومې پورې ماتم کوى او په پټو کښې به يې ګياه اوچيږى؟ څوک چې په دې مُلک کښې اوسيږى نو د هغوئ د بدعملۍ په وجه مارغان او ځناور تباه شوى دى، او هم په دې وجه خلق دا وائى چې، ”خُدائ به هم حيران وى چې مونږ سره به څۀ کيږى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah12_verse_004.mp3', NULL, 1761758823, 1761758823),
(38783, 'Jeremiah 12:5', 'Jeremiah', 12, 5, 'مالِک خُدائ ورته وفرمائيل، ”اے يرمياه، کۀ چرې تۀ د انسانانو سره په منډه وهلو دومره ستړے کېږې، نو تۀ به د آسونو سره څۀ مقابله وکړې؟ کۀ چرې تۀ په يو هوار او محفوظه مېدان کښې تيندکونه خورې او راغورزېږې، نو تۀ به د اُردن سره په ګڼ ځنګل کښې څۀ کوې؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah12_verse_005.mp3', NULL, 1761758823, 1761758823),
(38784, 'Jeremiah 12:6', 'Jeremiah', 12, 6, 'تر دې چې ستا وروڼه، او ستا د خپل خاندان خلق ستا مخالفت کوى. هغوئ ستا خلاف شکايتونه کوى. په هغوئ باور مۀ کوه، کۀ څۀ هم چې هغوئ ستا ښۀ وائى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah12_verse_006.mp3', NULL, 1761758823, 1761758823),
(38785, 'Jeremiah 12:7', 'Jeremiah', 12, 7, 'مالِک خُدائ فرمائى، ”ما خپل خلق پرېښودل، چې زما خاص ميراث دے. ما ته ډېر ګران خلق مې د دشمنانو لاسونو ته حواله کړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah12_verse_007.mp3', NULL, 1761758823, 1761758823),
(38786, 'Jeremiah 12:8', 'Jeremiah', 12, 8, 'زما غوره شوے قوم لکه د ځنګل د زمرى په شان ما ته وغړمبېدو، نو په دې وجه زۀ د هغوئ نه نفرت کوم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah12_verse_008.mp3', NULL, 1761758823, 1761758823),
(38787, 'Jeremiah 12:9', 'Jeremiah', 12, 9, 'آيا دا مُلک د ګيدړانو غار دے چې ټپوسان پرې بره الوځى رالوځى. خو ځنګلى ځناور دې راشى چې د هغوئ لاشونه وخورى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah12_verse_009.mp3', NULL, 1761758823, 1761758823),
(38788, 'Jeremiah 12:10', 'Jeremiah', 12, 10, 'ډېرو حاکمانو زما د انګورو باغونه برباد کړى دى، او هغوئ ټول بوټى د پښو لاندې کړى دى او ښائست يې ورله ختم او په بيابان بدل کړے دے.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah12_verse_010.mp3', NULL, 1761758823, 1761758823),
(38789, 'Jeremiah 12:11', 'Jeremiah', 12, 11, 'هغوئ د دې نه تش بيابان جوړ کړے دے او ما د خپلو خلقو د ماتم ژړا اورېدلې ده، او زما د ټول مُلک نه دشته بيابان جوړ شوے دے، او څوک يې هم پرواه نۀ کوى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah12_verse_011.mp3', NULL, 1761758823, 1761758823),
(38790, 'Jeremiah 12:12', 'Jeremiah', 12, 12, 'د بيابان په ټولو اوچتو او خُشکو غونډو د قتل و غارت فوج ليدلے کيږى، ځکه چې د مالِک خُدائ تُوره به د يو سر نه تر بل سره پورې هغوئ هلاک کړى. نو څوک به هم محفوظ نۀ وى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah12_verse_012.mp3', NULL, 1761758823, 1761758823),
(38791, 'Jeremiah 12:13', 'Jeremiah', 12, 13, 'زما خلقو غنم وکَرل، خو تش ازغى يې ورېبل، هغوئ ډېر محنت وکړو خو هيڅ فائده يې حاصله نۀ کړه. ځکه د مالِک خُدائ د سختې غصې په وجه، هغوئ صرف د رُسوايۍ او شرم فصل ورېبلو.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah12_verse_013.mp3', NULL, 1761758823, 1761758823),
(38792, 'Jeremiah 12:14', 'Jeremiah', 12, 14, 'مالِک خُدائ فرمائى، ”زۀ به د بنى اِسرائيلو نه هغه ټول شريره او بدکاره ګاونډيان د جرړې نه راوکاږم څوک چې د هغوئ په زمکه قبضه کول غواړى، او زۀ به يهوداه هم د بنى اِسرائيلو د مينځ نه راوکاږم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah12_verse_014.mp3', NULL, 1761758823, 1761758823),
(38793, 'Jeremiah 12:15', 'Jeremiah', 12, 15, 'خو کله چې زۀ هغوئ راوباسم، نو بيا به زۀ په هغوئ باندې رحم وکړم، او زۀ به هغوئ هر يو قوم خپل ميراث او خپل مُلک ته واپس راولم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah12_verse_015.mp3', NULL, 1761758823, 1761758823),
(38794, 'Jeremiah 12:16', 'Jeremiah', 12, 16, 'او بيا کۀ چرې دا قومونه په رښتيا سره زما د خلقو طريقې زده کړى، او کۀ هغوئ زما په نوم قسم خوړل زده کړى او وائى چې په يقين سره مالِک خُدائ ژوندے دے، لکه څنګه چې هغوئ يو وخت زما قوم ته د بعل د بُت په نوم قسم خوړل ور زده کړى وُو، نو هغوئ به بيا زما د قوم په مينځ کښې آباد شى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah12_verse_016.mp3', NULL, 1761758823, 1761758823),
(38795, 'Jeremiah 12:17', 'Jeremiah', 12, 17, 'خو کۀ چرې هر يو قوم زما خبرو ته غوږ ونۀ نيسى، نو بيا به زۀ هغه قوم په مکمل توګه د بېخ نه راوکاږم او نيست و نابود به يې کړم.“ دا د مالِک خُدائ وينا ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah12_verse_017.mp3', NULL, 1761758823, 1761758823),
(38796, 'Deuteronomy 30:1', 'Deuteronomy', 30, 1, 'تاسو ته مې اوس د برکت او لعنت د غوره کولو حق درکړی دی. کله چې په تاسو باندې دا ټولې پېښې وشي او تاسو د هغو قومونو په منځ کې ژوند وکړئ چې خپل څښتن خدای هلته شړلي یئ، نو زما هغه خبره به در په یاده شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy30_verse_001.mp3', NULL, 1761758823, 1761758823),
(38797, 'Deuteronomy 30:2', 'Deuteronomy', 30, 2, 'که چېرې تاسو او ستاسو اولاده بېرته څښتن ته رجوع وکړئ او د زړه له کومي د هغه د ټولو حکمونو چې نن یې درکوم اطاعت وکړئ،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy30_verse_002.mp3', NULL, 1761758823, 1761758823),
(38798, 'Deuteronomy 30:3', 'Deuteronomy', 30, 3, 'بیا به خپل څښتن خدای په تاسو باندې رحم وکړي. هغه به تاسو د هغو قومونو څخه چې تاسو یې په کې خپاره کړي یئ، بېرته راولي او بېرته به مو نېکمرغه کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy30_verse_003.mp3', NULL, 1761758823, 1761758823),
(38799, 'Deuteronomy 30:4', 'Deuteronomy', 30, 4, 'حتی که تاسو د دنیا په بل سر کې هم اوسئ، ستاسو څښتن خدای به تاسو راپیدا کړي او بېرته به مو راولي،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy30_verse_004.mp3', NULL, 1761758823, 1761758823),
(38800, 'Deuteronomy 30:5', 'Deuteronomy', 30, 5, 'ترڅو ستاسو اولاده بیا هغه خاوره تر لاسه کړي چې یو وخت د هغوی نیکونه په کې اوسېدل. هغه به ستاسو اولاده د خپلو نیکونو څخه نوره هم نېکمرغه او زیاته کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy30_verse_005.mp3', NULL, 1761758823, 1761758823),
(38801, 'Deuteronomy 30:6', 'Deuteronomy', 30, 6, 'تاسو او ستاسو اولادې ته به خپل څښتن خدای منونکي زړونه درکړي، ترڅو د زړه له کومي د هغه سره مینه وکړئ او په هغه خاوره کې خپل ژوند وکړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy30_verse_006.mp3', NULL, 1761758823, 1761758823),
(38802, 'Deuteronomy 30:7', 'Deuteronomy', 30, 7, 'هغه به دا ټول لعنتونه ستاسو په دښمنانو باندې چې ستاسو څخه یې کرکه کوله او تاسو یې ځورولئ، راولي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy30_verse_007.mp3', NULL, 1761758823, 1761758823),
(38803, 'Deuteronomy 30:8', 'Deuteronomy', 30, 8, 'او تاسو به بیا د څښتن او د هغه د ټولو حکمونو اطاعت کوئ چې زه یې نن درکوم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy30_verse_008.mp3', NULL, 1761758823, 1761758823),
(38804, 'Deuteronomy 30:9', 'Deuteronomy', 30, 9, 'څښتن به تاسو ته په خپلو ټولو کارونو کې زیات بریالیتوبونه درکړي. تاسو به ډېر اولادونه او حیوانات ولرئ او ستاسو پټي به پرېمانه فصلونه کوي. هغه به ستاسو په نېکمرغه کولو باندې هماغسې خوشحاله وي لکه څنګه چې ستاسو د نیکونو په نېکمرغه کولو باندې خوشحاله ؤ،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy30_verse_009.mp3', NULL, 1761758823, 1761758823),
(38805, 'Deuteronomy 30:10', 'Deuteronomy', 30, 10, 'خو تاسو به مجبور یئ چې د څښتن اطاعت وکړئ او د هغو ټولو قوانینو څخه پیروي وکړئ چې په دې کتاب کې لیکل شوي دي. تاسو به مجبور یئ چې د زړه له کومي هغه ته رجوع وکړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy30_verse_010.mp3', NULL, 1761758823, 1761758823),
(38806, 'Deuteronomy 30:11', 'Deuteronomy', 30, 11, 'هغه امرونه چې نن یې تاسو ته درکوم په هغو باندې پوهېدل او عمل کول ډېر سخت کار نه دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy30_verse_011.mp3', NULL, 1761758823, 1761758823),
(38807, 'Deuteronomy 30:12', 'Deuteronomy', 30, 12, 'هغه امرونه پورته په اسمان کې نه دي، ترڅو تاسو دې ته مجبور شئ چې داسې پوښتنه وکړئ: ‹څوک به پورته وخېژي چې هغه مونږ ته لاندې راوړي، ترڅو هغه واورو او عمل ورباندې وکړو؟›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy30_verse_012.mp3', NULL, 1761758823, 1761758823),
(38808, 'Deuteronomy 30:13', 'Deuteronomy', 30, 13, 'نه هغه د بحیرې په بلې غاړې باندې دي، ترڅو دې ته مجبور شئ چې داسې پوښتنه وکړئ: څوک به د بحیرې څخه تېر شي چې هغه مونږ ته راوړي، ترڅو هغه واورو او عمل ورباندې وکړو؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy30_verse_013.mp3', NULL, 1761758823, 1761758823),
(38809, 'Deuteronomy 30:14', 'Deuteronomy', 30, 14, 'نه، دا حکمونه تاسو ته نژدې دي. هغه ستاسو په خوله او ستاسو په زړونو کې دي، نو تاسو باید ورباندې عمل وکړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy30_verse_014.mp3', NULL, 1761758823, 1761758823),
(38810, 'Deuteronomy 30:15', 'Deuteronomy', 30, 15, 'نن زه تاسو ته د نېکمرغۍ او بدبختۍ او ژوند او مرګ د غوره کولو حق درکوم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy30_verse_015.mp3', NULL, 1761758823, 1761758823),
(38811, 'Deuteronomy 30:16', 'Deuteronomy', 30, 16, 'که چېرې تاسو د خپل څښتن خدای حکمونو ته چې زه یې نن درکوم غاړه کېږدئ، که چېرې د هغه سره مینه وکړئ، اطاعت یې وکړئ او د هغه د ټولو قوانینو څخه پیروي وکړئ، بیا به تاسو نېکمرغه شئ او یو لوی قوم به درڅخه جوړ شي. تاسو ته به خپل څښتن خدای په هغه خاوره کې چې تاسو به یې زر ونیسئ، برکت درکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy30_verse_016.mp3', NULL, 1761758823, 1761758823),
(38812, 'Deuteronomy 30:17', 'Deuteronomy', 30, 17, 'خو که چېرې سرغړونه وکړئ او غوږ ورته ونه نیسئ او نور خلک تاسو بې لارې کړي او د نورو خدایانو عبادت وکړئ،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy30_verse_017.mp3', NULL, 1761758823, 1761758823),
(38813, 'Deuteronomy 30:18', 'Deuteronomy', 30, 18, 'نو تاسو به تباه شئ. زه تاسو ته اوس همدلته خبرداری درکوم. تاسو به په هغه خاوره کې چې د اردن د سیند په بلې غاړې باندې پرته ده او زر به یې ونیسئ، ډېره موده ژوند ونه کړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy30_verse_018.mp3', NULL, 1761758823, 1761758823),
(38814, 'Deuteronomy 30:19', 'Deuteronomy', 30, 19, 'زه اوس تاسو ته د ژوند او مرګ، د خدای د برکت او لعنت د غوره کولو حق درکوم او زه ځمکه او اسمان د دې خبرې دپاره شاهدان نیسم چې تاسو کوم شی غوره کوئ. تاسو ژوند غوره کړئ، ترڅو تاسو او ستاسو اولاده ژوندي پاتې شئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy30_verse_019.mp3', NULL, 1761758823, 1761758823),
(38815, 'Deuteronomy 30:20', 'Deuteronomy', 30, 20, 'خپل څښتن خدای ته پوره وفادار اوسئ، د هغه سره مینه کوئ او څه چې درته وایي هغه کوئ. یوازې څښتن دی چې ژوندون ورکولای شي. هغه به تاسو ته په هغه خاوره کې چې ستاسو د نیکونو ابراهیم، اسحاق او یعقوب سره یې وعده کړې ده، زیات عمر درکړي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy30_verse_020.mp3', NULL, 1761758823, 1761758823),
(38816, 'Psalms 47:1', 'Psalms', 47, 1, 'ای ټولو خلکو پړکوئ لاسونه! د خدای ثنا په خوشحالۍ او لوړو چیغو وکړئ!', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms47_verse_001.mp3', NULL, 1761758823, 1761758823),
(38817, 'Psalms 47:2', 'Psalms', 47, 2, 'چې هیبتناکه دی څښتن تعالی هغه ډېر لوی پاچا دی کوي حکومت ټولې دنیا باندې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms47_verse_002.mp3', NULL, 1761758823, 1761758823),
(38818, 'Psalms 47:3', 'Psalms', 47, 3, 'نورو قومونو باندې مونږ ته یې بری راکړی او یې هغه قومونه لاندې کړل زمونږ تر‌پښو', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms47_verse_003.mp3', NULL, 1761758823, 1761758823),
(38819, 'Psalms 47:4', 'Psalms', 47, 4, 'ده غوره کړې ځمکه مونږ دپاره ویاړو پر دې مونږ د یعقوب اولاده خدای ورسره مینه چې کړي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms47_verse_004.mp3', NULL, 1761758823, 1761758823),
(38820, 'Psalms 47:5', 'Psalms', 47, 5, 'وخاته خدای خپل تخت ته وې هلته چیغې د خوښۍ هلته غږونه د سرنو وو چې څښتن پورته لاړ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms47_verse_005.mp3', NULL, 1761758823, 1761758823),
(38821, 'Psalms 47:6', 'Psalms', 47, 6, 'وایاست سندرې او ثنا خدای ته! وایاست سندرې او ثنا خپل شاه ته!', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms47_verse_006.mp3', NULL, 1761758823, 1761758823),
(38822, 'Psalms 47:7', 'Psalms', 47, 7, 'ځکه چې خدای د ټول جهان پاچا دی ثنا یې ووایاست سندرې باندې!', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms47_verse_007.mp3', NULL, 1761758823, 1761758823),
(38823, 'Psalms 47:8', 'Psalms', 47, 8, 'خدای کړي پاچاهي ټولو قومونو باندې خدای دی په خپل سپېڅلي تخت باندې ناست', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms47_verse_008.mp3', NULL, 1761758823, 1761758823),
(38824, 'Psalms 47:9', 'Psalms', 47, 9, 'د قومونو رهبران دي راټول شوي په یو ځای د ابراهیم د خدای د قومه سره د دنیا ټول شاهان د خدای واک کې دي هغه ډېر لوړ خدای دی', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms47_verse_009.mp3', NULL, 1761758823, 1761758823),
(38825, 'Joshua 24:1', 'Joshua', 24, 1, 'یوشع په شکیم کې د اسراییلو ټولې قبیلې راټولې کړې. هغه د اسراییلو سپین ږیري، مشران، قاضیان او مامورین راوغوښتل. هغوی راغلل او د خدای په حضور کې ودرېدل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_001.mp3', NULL, 1761758823, 1761758823),
(38826, 'Joshua 24:2', 'Joshua', 24, 2, 'یوشع ټول قوم ته وویل: «د اسراییلو څښتن خدای داسې وایي: ‹ډېره موده مخکې ستاسو نیکونه چې په هغو کې د ابراهیم او د ناحور پلار یعنې تارح شامل ؤ، د فرات د سیند په بلې غاړې باندې اوسېدل او د نورو خدایانو عبادت به یې کاوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_002.mp3', NULL, 1761758823, 1761758823),
(38827, 'Joshua 24:3', 'Joshua', 24, 3, 'بیا ما ستاسو نیکه ابراهیم د هغه ځای څخه بوته او د کنعان په ټوله خاوره کې مې وګرځاوه. هغه ته مې اسحاق ورکړ او د اسحاق په وسیله مې هغه ته ډېره اولاده ورکړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_003.mp3', NULL, 1761758823, 1761758823),
(38828, 'Joshua 24:4', 'Joshua', 24, 4, 'اسحاق ته مې دوه زامن ورکړل یعنې یعقوب او عیسو. عیسو ته مې د ادوم غرنۍ سیمه د هغه د ملکیت په توګه ورکړه، خو ستاسو نیکه یعقوب او د هغه اولادونه مصر ته لاړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_004.mp3', NULL, 1761758823, 1761758823),
(38829, 'Joshua 24:7', 'Joshua', 24, 7, 'هغوی ماته د مرستې دپاره فریاد وکړ او ما د هغوی او مصریانو ترمنځ تیاره رامنځته کړه. په مصریانو باندې مې اوبه راوستلې او هغوی مې په بحیره کې ډوب کړل. تاسو په خپلو سترګو ولیدل چې ما په مصر باندې څه وکړل. له هغې وروسته تاسو ډېره موده په دښته کې اوسېدلئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_007.mp3', NULL, 1761758823, 1761758823),
(38830, 'Joshua 24:8', 'Joshua', 24, 8, 'بیا مې تاسو هغې خاورې ته راوستلئ چې د اردن د سیند په ختیځ کې وه. هلته اموریان اوسېدل او هغوی ستاسو سره جګړه وکړه، خو تاسو زما په مرسته هغوی ته ماتې ورکړه، هغوی مو له منځه یووړل او د هغوی خاوره مو ونیوله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_008.mp3', NULL, 1761758823, 1761758823),
(38831, 'Joshua 24:9', 'Joshua', 24, 9, 'کله چې د موآب پاچا د صفور زوی بالاق ستاسو په وړاندې ودرېده، هغه د بعور زوی بلعام راوغوښت او د هغه څخه یې وغوښتل چې په تاسو باندې لعنت ووایي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_009.mp3', NULL, 1761758823, 1761758823),
(38832, 'Joshua 24:10', 'Joshua', 24, 10, 'خو ما د بلعام خبرو ته غوږ ونه نیوه. هغه مې مجبور کړ چې تاسو ته برکت درکړي. په دې ډول مې تاسو د بالاق څخه وژغورلئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_010.mp3', NULL, 1761758823, 1761758823),
(38833, 'Joshua 24:11', 'Joshua', 24, 11, 'بیا تاسو د اردن د سیند څخه پورې وتلئ او اریحا ته راغلئ. د اریحا خلکو د اموریانو، فرزیانو، کنعانیانو، حیتیانو، جرجاشیانو، حویانو او یبوسیانو په شان ستاسو سره جګړه وکړه. خو ما تاسو ته په هغوی ټولو باندې بری درکړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_011.mp3', NULL, 1761758823, 1761758823),
(38834, 'Joshua 24:12', 'Joshua', 24, 12, 'ستاسو دښمنان ستاسو څخه وتښتېدل، خو ستاسو د تورو، لیندو او غشو له امله نه. ما ستاسو په دښمنانو کې سخته وېره راپیدا کړه او هغوی وتښتېدل لکه څنګه چې مې د هغو دوو اموریایي پاچاهانو سره کړي وو چې د اردن د سیند په ختیځ کې اوسېدل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_012.mp3', NULL, 1761758823, 1761758823),
(38835, 'Joshua 24:13', 'Joshua', 24, 13, 'ما تاسو ته ځمکه درکړه په کومې باندې چې تاسو زحمت نه ؤ ویستلی او ښارونه مې درکړل چې هغه تاسو نه وو ودان کړي او اوس په هغو کې اوسېږئ. د انګورو او زیتونو د باغونو څخه چې تاسو کرلي نه وو، خواړه خورئ.›»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_013.mp3', NULL, 1761758823, 1761758823),
(38836, 'Joshua 24:14', 'Joshua', 24, 14, 'بیا یوشع وویل: «نو د څښتن څخه ووېرېږئ او په پوره وفادارۍ سره د هغه عبادت وکړئ. هغه بتان چې ستاسو نیکونو یې په مصر او د فرات د سیند په بله غاړه باندې عبادت کاوه، لېرې ګوزار کړئ او د څښتن عبادت وکړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_014.mp3', NULL, 1761758823, 1761758823),
(38837, 'Joshua 24:15', 'Joshua', 24, 15, 'که چېرې تاسو د هغه عبادت کول نه غواړئ، نو نن پرېکړه وکړئ چې د کومو خدایانو عبادت به کوئ. ایا د هغو خدایانو عبادت به کوئ چې ستاسو نیکونو یې د فرات د سیند په بله غاړه باندې عبادت کاوه او یا به د اموریانو د خدایانو چې تاسو اوس د هغوی په خاوره کې اوسېږئ، عبادت کوئ. خو زه به د خپلې کورنۍ سره د څښتن عبادت کوم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_015.mp3', NULL, 1761758823, 1761758823),
(38838, 'Joshua 24:16', 'Joshua', 24, 16, 'قوم په ځواب کې وویل: «مونږ به هېڅکله داسې ونه کړو چې څښتن پرېږدو او د نورو خدایانو عبادت وکړو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_016.mp3', NULL, 1761758823, 1761758823),
(38839, 'Joshua 24:17', 'Joshua', 24, 17, 'دا په خپله زمونږ څښتن خدای ؤ چې مونږ یې د خپلو نیکونو سره د مصر څخه چې په کې غلامان وو راوویستلو او مونږ هغه معجزې ولیدلې چې هغه وښودلې. په خپل ټول سفر کې او د هغو ټولو قومونو په منځ کې چې مونږ ورڅخه تېرېدلو، هغه وساتلو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_017.mp3', NULL, 1761758823, 1761758823),
(38840, 'Joshua 24:18', 'Joshua', 24, 18, 'څښتن زمونږ د مخې څخه هغه ټول قومونه لېرې کړل چې په دې خاوره کې اوسېدل چې په هغو کې اموریان هم شامل وو. نو مونږ به هم د څښتن عبادت او اطاعت کوو، ځکه چې هغه زمونږ خدای دی.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_018.mp3', NULL, 1761758823, 1761758823),
(38841, 'Joshua 24:19', 'Joshua', 24, 19, 'یوشع قوم ته وویل: «کېدای شي چې تاسو د څښتن عبادت ونه شئ کولای، ځکه چې هغه سپېڅلی او غیرتي خدای دی. تاسو باید هغه ته پوره وفادار اوسئ. که چېرې تاسو د هغه په وړاندې ګناه او سرکښي وکړئ، نو هغه به تاسې ونه بخښي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_019.mp3', NULL, 1761758823, 1761758823),
(38842, 'Joshua 24:20', 'Joshua', 24, 20, 'که چېرې تاسو هغه پرېږدئ او د نورو قومونو د بتانو عبادت وکړئ، هغه به ستاسو په ضد شي او تاسو ته به سزا درکړي. که څه هم مخکې هغه ستاسو سره ښه ؤ، خو تاسې به له منځه یوسي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_020.mp3', NULL, 1761758823, 1761758823),
(38843, 'Joshua 24:21', 'Joshua', 24, 21, 'قوم یوشع ته وویل: «نه! مونږ به د څښتن عبادت او اطاعت کوو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_021.mp3', NULL, 1761758823, 1761758823),
(38844, 'Joshua 24:22', 'Joshua', 24, 22, 'یوشع هغوی ته وویل: «تاسو د خپلو ځانونو شاهدان یئ. تاسو وویل چې مونږ د څښتن عبادت او اطاعت کول غوره کړي دي.» هغوی وویل: «هو، مونږ شاهدان یو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_022.mp3', NULL, 1761758823, 1761758823),
(38845, 'Joshua 24:23', 'Joshua', 24, 23, 'هغه غوښتنه وکړه: «خو لکه د هغو بتانو په شان چې نور قومونه یې عبادت کوي ستاسو سره هم یو څه بتان شته. هغه لېرې ګوزار کړئ او د اسراییلو د څښتن خدای سره د وفادارۍ لوظ وکړئ.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_023.mp3', NULL, 1761758823, 1761758823),
(38846, 'Joshua 24:24', 'Joshua', 24, 24, 'قوم یوشع ته وویل: «مونږ به یوازې د خپل څښتن خدای عبادت کوو او د هغه حکمونو ته به غاړه ږدو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_024.mp3', NULL, 1761758823, 1761758823),
(38847, 'Joshua 24:25', 'Joshua', 24, 25, 'په هغه ورځ یوشع په شکیم کې د اسراییلو د خلکو استازیتوب وکړ او د هغوی او څښتن ترمنځ یې یو تړون وکړ او هغوی ته یې قوانین او اصول ورکړل چې ورڅخه پیروي وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_025.mp3', NULL, 1761758823, 1761758823),
(38848, 'Joshua 24:26', 'Joshua', 24, 26, 'یوشع دا خبرې د خدای د قوانینو په کتاب کې ولیکلې. بیا هغه یوه لویه تیږه واخیستله او د څښتن د عبادت په ځای کې یې د څېړۍ د ونې لاندې ودروله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_026.mp3', NULL, 1761758823, 1761758823),
(38849, 'Joshua 24:27', 'Joshua', 24, 27, 'هغه ټول قوم ته وویل: «ګورئ، دا تیږه به زمونږ شاهده وي. دې تیږې هغه ټولې خبرې واورېدلې چې څښتن مونږ ته وکړې. نو که چېرې تاسو د خپل خدای څخه منکر شئ، نو دا تیږه به ستاسو په خلاف شهادت ورکوي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_027.mp3', NULL, 1761758823, 1761758823),
(38850, 'Joshua 24:28', 'Joshua', 24, 28, 'بیا یوشع قوم رخصت کړ او هر یو کس د خپلې برخې ځمکې ته ور ستون شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_028.mp3', NULL, 1761758823, 1761758823),
(38851, 'Joshua 24:29', 'Joshua', 24, 29, 'څه موده وروسته د څښتن خدمتګار د نون زوی یوشع د یوسلو لسو کالو په عمر مړ شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_029.mp3', NULL, 1761758823, 1761758823),
(38852, 'Joshua 24:30', 'Joshua', 24, 30, 'هغه یې په خپله ځمکه یعنې په تمنه سارح کې چې د افرایم په غرنۍ سیمه او د جاعش د غره په شمال کې وه، ښخ کړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_030.mp3', NULL, 1761758823, 1761758823),
(38853, 'Joshua 24:31', 'Joshua', 24, 31, 'ترڅو پورې چې یوشع ژوندی ؤ، د اسراییلو خلکو د څښتن عبادت او اطاعت کاوه. حتی د هغه د مړینې څخه وروسته هم ترڅو پورې چې د قوم هغه سپین ږیري ژوندي وو چې د څښتن هغه ټول کارونه په خپلو سترګو لیدلي وو چې د اسراییلو دپاره یې کړي وو، هغوی څښتن ته وفادار پاتې شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_031.mp3', NULL, 1761758823, 1761758823),
(38854, 'Joshua 24:32', 'Joshua', 24, 32, 'د یوسف مړی چې د اسراییلو خلکو د مصر څخه راوړی ؤ، په شکیم کې په هغې ټوټه ځمکه کې ښخ کړای شو چې یعقوب د شکیم د ښار د بنیاد ایښودونکي حمور د زامنو څخه د سپینو زرو په سلو سکو باندې اخیستې وه. دا ځمکه د یوسف اولادې ته په میراث پاتې شوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_032.mp3', NULL, 1761758823, 1761758823),
(38855, 'Joshua 24:33', 'Joshua', 24, 33, 'د هارون زوی العازار هم مړ شو او په جبعه کې چې د افرایم په غرنۍ سیمه کې یو ښارګوټی ؤ ښخ کړای شو، دا ښارګوټی د هغه زوی فینحاس ته ورکړل شوی ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua24_verse_033.mp3', NULL, 1761758823, 1761758823),
(38856, 'Psalms 70:1', 'Psalms', 70, 1, 'ای خدایه ته ما خلاص کړه ای څښتنه، زر کومک راسره وکړه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms70_verse_001.mp3', NULL, 1761758823, 1761758823),
(38857, 'Psalms 70:2', 'Psalms', 70, 2, 'هغوی چې هڅه کوي ما ووژني هغوی دې ماتې سره مخ شي وارخطا دې شي چې زما په کړاوونو خوشحالي کړي هغوی دې تېښتې سره مخ شي او رسوا دې شي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms70_verse_002.mp3', NULL, 1761758823, 1761758823),
(38858, 'Psalms 70:3', 'Psalms', 70, 3, 'څوک چې په ما باندې ملنډې وهي له خپلې ماتې دې دوی وبوګنیږي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms70_verse_003.mp3', NULL, 1761758823, 1761758823),
(38859, 'Psalms 70:4', 'Psalms', 70, 4, 'هغه ټول خلک چې کړي تاته رجوع شي دې خوشحاله او خوښي دې کړي له تا نه هغه چې مینه کړي ستا د خلاصون سره او دوی دې تل وایي: «څومره عظیم دی خدای»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms70_verse_004.mp3', NULL, 1761758823, 1761758823),
(38860, 'Psalms 70:5', 'Psalms', 70, 5, 'زه یم غریب او زه محتاج یمه زر شه او زما کومک ته راشه خدایه ته مې مددګار او خلاصوونکی یې بیړه وکړه او کومک لره مې راشه ای څښتنه!', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms70_verse_005.mp3', NULL, 1761758823, 1761758823),
(38861, 'Joshua 13:1', 'Joshua', 13, 1, 'کله چې یوشع زوړ شو، څښتن هغه ته وویل: «ته ډېر زوړ شوی یې، خو ډېره ځمکه لا پاتې ده چې باید ونیول شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_001.mp3', NULL, 1761758823, 1761758823),
(38862, 'Joshua 13:2', 'Joshua', 13, 2, 'دا هغه ځمکه ده چې پاتې ده: د فلسطینیانو او د جشوریانو ټوله سیمه،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_002.mp3', NULL, 1761758823, 1761758823),
(38863, 'Joshua 13:3', 'Joshua', 13, 3, 'همدارنګه د عویانو سیمه تر جنوب پورې (د شیحور څخه نیولې چې د مصر په پولې کې وه د عقرون تر پولې پورې چې په شمال کې وه، د کنعانیانو ځمکه ګڼل کېدله. د فلسطین پاچاهان په غزه، اشدود، اشقلون، جت او عقرون کې اوسېدل)،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_003.mp3', NULL, 1761758823, 1761758823),
(38864, 'Joshua 13:4', 'Joshua', 13, 4, 'د کنعانیانو ټول هېواد او میعاره چې په صیدونیانو پورې اړه لري تر افیق پورې چې د اموریانو په پوله کې دی،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_004.mp3', NULL, 1761758823, 1761758823),
(38865, 'Joshua 13:5', 'Joshua', 13, 5, 'د جبالیانو ځمکه او ټول لبنان تر ختیځ پورې، د بعل جاد څخه نیولې چې د حرمون د غره جنوب خواته پروت دی د حمات تر غاښي پورې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_005.mp3', NULL, 1761758823, 1761758823),
(38866, 'Joshua 13:6', 'Joshua', 13, 6, 'په دې کې د صیدونیانو چې د لبنان د غرونو او د مسرفوت مایم ترمنځ په غرنۍ سیمه کې اوسیږي، ټوله سیمه شامله ده. زه به په خپله د اسراییلو له مخې څخه دا خلک لېرې کړم. څنګه چې ما په تا باندې حکم کړی دی، ته باید دا ځمکه د اسراییلیانو په منځ کې ووېشې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_006.mp3', NULL, 1761758823, 1761758823),
(38867, 'Joshua 13:7', 'Joshua', 13, 7, 'بیا دا ځمکه په هغو نهو قبیلو او د منسي په نیمې قبیلې ووېشه چې تر اوسه پورې ځمکه نه لري چې د هغوی ملکیت شي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_007.mp3', NULL, 1761758823, 1761758823),
(38868, 'Joshua 13:8', 'Joshua', 13, 8, 'موسی لا پخوا د روبین او جاد قبیلو او د منسي بلې نیمې قبیلې ته هغه ځمکه ورکړې وه چې د اردن د سیند په ختیځه غاړه باندې پرته وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_008.mp3', NULL, 1761758823, 1761758823),
(38869, 'Joshua 13:9', 'Joshua', 13, 9, 'دا سیمه د هغه ښار څخه چې د ارنون د درې په منځ کې ؤ او په هغې کې د عروعیر ښار چې د هغې درې په شمالي څنډه کې ؤ شامل ؤ، شمال خواته غزېدلې ده. په هغې کې د دیبون په شمال کې د میدیبا لوړه جلګه شامله وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_009.mp3', NULL, 1761758823, 1761758823),
(38870, 'Joshua 13:10', 'Joshua', 13, 10, 'د هغوی سیمه د عمون تر پولې پورې رسېدله. همدارنګه په هغې کې هغه ټول ښارونه هم شامل وو چې د اموریانو پاچا سیحون به ورباندې د حشبون د ښار څخه حکومت کاوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_010.mp3', NULL, 1761758823, 1761758823),
(38871, 'Joshua 13:11', 'Joshua', 13, 11, 'په هغې کې جلعاد، د جشور او معکې سیمې، د حرمون ټول غر او ټول باشان تر سلخه پورې شامل وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_011.mp3', NULL, 1761758823, 1761758823),
(38872, 'Joshua 13:12', 'Joshua', 13, 12, 'په هغې کې د عوج پاچاهي شامله وه. عوج د رفاییانو د جملې څخه یوازېنی کس ؤ چې ژوندی پاتې شوی ؤ او په عشتاروت او ادرعي کې یې پاچاهي کوله. موسی دې خلکو ته ماتې ورکړې وه او هغوی یې شړلي وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_012.mp3', NULL, 1761758823, 1761758823),
(38873, 'Joshua 13:13', 'Joshua', 13, 13, 'خو بیاهم اسراییلیانو جشوریان او معکیان ونه شړل، نو هغوی تر نن ورځې پورې د اسراییلیانو په منځ کې اوسیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_013.mp3', NULL, 1761758823, 1761758823),
(38874, 'Joshua 13:14', 'Joshua', 13, 14, 'موسی د لاوي قبیلې ته هېڅ ځمکه نه وه ورکړې، ځکه چې د اسراییلو څښتن خدای هغوی ته ویلي وو: «تاسو به د ځمکې په ځای هغه قربانۍ تر لاسه کوئ چې زما د قربانۍ په ځای باندې سوځول کیږي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_014.mp3', NULL, 1761758823, 1761758823),
(38875, 'Joshua 13:15', 'Joshua', 13, 15, 'موسی د روبین په قبیله کې هرې یوې طایفې ته ځمکه ورکړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_015.mp3', NULL, 1761758823, 1761758823),
(38876, 'Joshua 13:16', 'Joshua', 13, 16, 'د هغوی ځمکه په جنوب کې په هغه ښارګوټي کې شروع کېدله چې د ارنون د درې په منځ کې ؤ. په هغې کې د عروعیر ښارګوټی چې د درې په شمالي څنډه کې ؤ، شامل ؤ او په شمال کې د میدیبا د شاوخوا لوړې جلګې پورې رسېدله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_016.mp3', NULL, 1761758823, 1761758823),
(38877, 'Joshua 13:17', 'Joshua', 13, 17, 'په دې کې حشبون او کوم ښارګوټي چې په لوړې جلګې باندې پراته وو یعنې دیبون، باموت بعل، بیت بعل معون،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_017.mp3', NULL, 1761758823, 1761758823),
(38878, 'Joshua 13:18', 'Joshua', 13, 18, 'یاهص، قدیموت، میفاعت،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_018.mp3', NULL, 1761758823, 1761758823),
(38879, 'Joshua 13:19', 'Joshua', 13, 19, 'قریتایم، سبمه، سارت شحر چې په دره کې په غونډۍ باندې ؤ،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_019.mp3', NULL, 1761758823, 1761758823),
(38880, 'Joshua 13:20', 'Joshua', 13, 20, 'بیت فغور، د پیسګاه د غره ډډې او بیت یشیموت ټول شامل وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_020.mp3', NULL, 1761758823, 1761758823),
(38881, 'Joshua 13:21', 'Joshua', 13, 21, 'هغه ټول ښارګوټي چې په لوړې جلګې باندې پراته وو او د سیحون ټوله پاچاهي (سیحون د اموریانو پاچا ؤ او په حشبون کې یې حکومت کاوه) شامل وو. موسی سیحون او د مدیانیانو مشرانو یعنې اوي، راقم، صور، حور او رابع ته ماتې ورکړې وه. دا مشران چې په هغه هېواد کې اوسېدل، د سیحون سره ملګري شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_021.mp3', NULL, 1761758823, 1761758823),
(38882, 'Joshua 13:22', 'Joshua', 13, 22, 'په هغو خلکو کې چې د اسراییلیانو له خوا وژل شوي وو، بلعام د بعور زوی چې فال کتونکی ؤ هم شامل ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_022.mp3', NULL, 1761758823, 1761758823),
(38883, 'Joshua 13:23', 'Joshua', 13, 23, 'دا سیمه او د هغې ښارونه او کلي د روبین قبیلې ته د هغوی د ملکیت په توګه ورکړل شول او د اردن سیند د هغې لوېدیځه پوله وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_023.mp3', NULL, 1761758823, 1761758823),
(38884, 'Joshua 13:24', 'Joshua', 13, 24, 'همدارنګه موسی د جاد په قبیله کې هرې یوې طایفې ته ځمکه ورکړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_024.mp3', NULL, 1761758823, 1761758823),
(38885, 'Joshua 13:25', 'Joshua', 13, 25, 'د هغوی په سیمه کې یعزیر، د جلعاد ټول ښارګوټي او د عمون نیمه ځمکه تر عروعیر پورې چې د ربه په ختیځ کې وه شامل وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_025.mp3', NULL, 1761758823, 1761758823),
(38886, 'Joshua 13:26', 'Joshua', 13, 26, 'د هغوی ځمکه د حشبون څخه نیولې تر رامت مصفه او بطونیم پورې او د محنایم څخه نیولې د دبیر تر سیمې پورې غزېدلې وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_026.mp3', NULL, 1761758823, 1761758823),
(38887, 'Joshua 13:27', 'Joshua', 13, 27, 'د اردن د درې په هغه سیمه کې چې جاد ته ورکړل شوې وه په هغې کې بیت هارام، بیت نمره، سوکوت او صافون یعنې د حشبون د پاچا سیحون پخوانۍ پاچاهي شامله وه. د هغوی لوېدیځه پوله د اردن سیند ؤ او هغه په شمال کې د جلیل تر بحیرې پورې رسېدله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_027.mp3', NULL, 1761758823, 1761758823),
(38888, 'Joshua 13:28', 'Joshua', 13, 28, 'دا هغه سیمې او د هغو ښارګوټي او کلي وو چې د جاد قبیلې ته ورکړل شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_028.mp3', NULL, 1761758823, 1761758823),
(38889, 'Joshua 13:29', 'Joshua', 13, 29, 'موسی د منسي په نیمه قبیله کې هرې یوې طایفې ته ځمکه ورکړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_029.mp3', NULL, 1761758823, 1761758823),
(38890, 'Joshua 13:30', 'Joshua', 13, 30, 'د هغوی سیمه تر محنایم پورې وه او په هغې کې د باشان پاچا عوج ټوله پاچاهي او همدارنګه په باشان کې د یاییر ټول شپېته کلي شامل وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_030.mp3', NULL, 1761758823, 1761758823),
(38891, 'Joshua 13:31', 'Joshua', 13, 31, 'په دې کې نیم جلعاد، همدارنګه عشتاروت او ادرعي یعنې په باشان کې د عوج د پاچاهۍ شاهي ښارونه شامل وو. دا ټول هغو نیمو طایفو ته ورکړل شول چې د ماخیر یعنې د منسي د زوی څخه د اولادې په توګه پاتې وې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_031.mp3', NULL, 1761758823, 1761758823),
(38892, 'Joshua 13:32', 'Joshua', 13, 32, 'په دې ډول موسی د موآب ډاګونه چې د اردن د سیند په بله غاړه او د اریحا په ختیځ کې وو، ووېشل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_032.mp3', NULL, 1761758823, 1761758823),
(38893, 'Joshua 13:33', 'Joshua', 13, 33, 'خو موسی د لاوي قبیلې ته هېڅ ځمکه ورنه کړه، ځکه چې څښتن وعده کړې وه چې هغه به تل د هغوی اړتیاوې پوره کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua13_verse_033.mp3', NULL, 1761758823, 1761758823),
(38894, 'Jeremiah 47:1', 'Jeremiah', 47, 1, 'دا د مالِک خُدائ هغه کلام دے چې د فِرعون د لښکرو په غزه د حملې کولو نه مخکښې، په يرمياه نبى د فلستيانو په حقله نازل شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah47_verse_001.mp3', NULL, 1761758823, 1761758823),
(38895, 'Jeremiah 47:2', 'Jeremiah', 47, 2, '”مالِک خُدائ وفرمائيل چې، وګوره، د شمال نه اوبۀ څنګه راوچتيږى، او د سېلاب په شان په زور شور راروانې دى، دا به ټوله زمکه او هر څۀ چې په کښې دى رالاندې کړى، ښارونه او د هغې اوسېدونکى به ډوب کړى، ټول خلق به د مدد دپاره چغې وهى او څومره خلق چې په کښې اوسيږى هغوئ به ژړا کوى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah47_verse_002.mp3', NULL, 1761758823, 1761758823),
(38896, 'Jeremiah 47:3', 'Jeremiah', 47, 3, 'هغوئ به د آسونو د سومونو او پښو ټکار واورى، او د دشمن د جنګى ګاډو غرار او د هغوئ د پايو شور به واورى. پلاران به د يرې نه جام شى او د خپلو بې‌وسه ماشومانو د بچ کولو دپاره به شاته نۀ ګورى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah47_verse_003.mp3', NULL, 1761758823, 1761758823),
(38897, 'Jeremiah 47:4', 'Jeremiah', 47, 4, 'د ټولو فلستيانو د تباهۍ ورځ رارسېدلې ده او ورسره د هغوئ هم څوک چې به د صور او صيدا خلقو سره مدد کوى. مالِک خُدائ په خپله هغه فلستيان تباه کوى، هغوئ څوک چې ژوندى پاتې شوى دى او د کريت د ساحل نه راغلى دى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah47_verse_004.mp3', NULL, 1761758823, 1761758823),
(38898, 'Jeremiah 47:5', 'Jeremiah', 47, 5, 'غزه لور به د غم نه خپل سر ګنجے کړى او د اسقلون ښار به وران او خاموشه شى. اے د مېدانى علاقې پاتې شوو خلقو ترڅو پورې به خپل ځان وهئ او ماتم به کوئ؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah47_verse_005.mp3', NULL, 1761758823, 1761758823),
(38899, 'Jeremiah 47:6', 'Jeremiah', 47, 6, 'تاسو چغې وهئ، اے د مالِک خُدائ تُورې، ترڅو پورې به تۀ زخمى کول کوې؟ خپل کاش ته واپس لاړه شه، او هلته په آرام پرته اوسه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah47_verse_006.mp3', NULL, 1761758823, 1761758823),
(38900, 'Jeremiah 47:7', 'Jeremiah', 47, 7, 'خو دا به څنګه په آرام شى چې ورته مالِک خُدائ حکم کړے دے، کله چې هغۀ ورته په اسقلون او په ساحل د حملې کولو حکم کړے دے؟“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah47_verse_007.mp3', NULL, 1761758823, 1761758823),
(38901, 'Proverbs 26:1', 'Proverbs', 26, 1, 'لکه څنګه چې په اوړي کې واوره او د لو په وخت کې باران مناسب نه دی همداسې کم‌عقل انسان ته درناوی کول هم مناسب نه دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_001.mp3', NULL, 1761758823, 1761758823),
(38902, 'Proverbs 26:2', 'Proverbs', 26, 2, 'لکه څنګه چې چڼچڼه اخوا دې خوا الوزي او یا توتکۍ ګرځي راګرځي او نه کښېني همداسې بېځایه سپکې سپورې په چا پورې نه نښلي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_002.mp3', NULL, 1761758823, 1761758823),
(38903, 'Proverbs 26:3', 'Proverbs', 26, 3, 'لکه څنګه چې د اس دپاره قمچینه او د خره دپاره قیضه ده همداسې د کم‌عقلانو د ملا دپاره لښته ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_003.mp3', NULL, 1761758823, 1761758823),
(38904, 'Proverbs 26:4', 'Proverbs', 26, 4, 'کم‌عقل ته د هغه د جهالت سره سم ځواب مه ورکوه هسې نه چې ته په خپله هم د هغه په شان شې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_004.mp3', NULL, 1761758823, 1761758823),
(38905, 'Proverbs 26:5', 'Proverbs', 26, 5, 'کم‌عقل ته د هغه د جهالت سره سم ځواب ورکوه هسې نه چې هغه ځان د حکمت خاوند وګڼي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_005.mp3', NULL, 1761758823, 1761758823),
(38906, 'Proverbs 26:6', 'Proverbs', 26, 6, 'د کم‌عقل په لاس پیغام لېږل داسې دي لکه خپلې پښې غوڅول او د ظلم زهر څښل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_006.mp3', NULL, 1761758823, 1761758823),
(38907, 'Proverbs 26:7', 'Proverbs', 26, 7, 'د کم‌عقل د خولې متل داسې دی لکه د ګوډ سړي پښه چې بېځایه زنګیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_007.mp3', NULL, 1761758823, 1761758823),
(38908, 'Proverbs 26:8', 'Proverbs', 26, 8, 'کم‌عقل ته درناوی کول داسې دي لکه څوک چې په مچنوغزه کې تیږه د سر نه تاوه کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_008.mp3', NULL, 1761758823, 1761758823),
(38909, 'Proverbs 26:9', 'Proverbs', 26, 9, 'د کم‌عقل د خولې متل داسې دی لکه د نشه انسان په لاس کې چې د اغزیو لښته وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_009.mp3', NULL, 1761758823, 1761758823),
(38910, 'Proverbs 26:10', 'Proverbs', 26, 10, 'هغه څوک چې کم‌عقل او لاروی سړی مزدور نیسي د هغه غشي ویشتونکي په څېر دی چې هرڅوک ټپي کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_010.mp3', NULL, 1761758823, 1761758823),
(38911, 'Proverbs 26:11', 'Proverbs', 26, 11, 'لکه څنګه چې سپی خپلې کانګې بېرته څټي همداسې کم‌عقل خپل جهالت بیا تکراروي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_011.mp3', NULL, 1761758823, 1761758823),
(38912, 'Proverbs 26:12', 'Proverbs', 26, 12, 'څوک چې خپل ځان د حکمت خاوند ګڼي نو هغه د یو کم‌عقل نه هم ډېر بد دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_012.mp3', NULL, 1761758823, 1761758823),
(38913, 'Proverbs 26:13', 'Proverbs', 26, 13, 'لټ سړی له کور څخه نه وځي او وایي: «په کوڅه کې زمری دی! او په چوکونو کې غړمبېدونکي زمري ګرځي راګرځي!»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_013.mp3', NULL, 1761758823, 1761758823),
(38914, 'Proverbs 26:14', 'Proverbs', 26, 14, 'لکه څنګه چې دروازه په خپلو قبضو باندې تاویږي راتاویږي همداسې لټ سړی په خپل کټ کې اوړي را‌اوړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_014.mp3', NULL, 1761758823, 1761758823),
(38915, 'Proverbs 26:15', 'Proverbs', 26, 15, 'لټ انسان کاسې ته لاس غزولی شي خو د لټۍ نه یې بېرته خولې ته وړلی نه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_015.mp3', NULL, 1761758823, 1761758823),
(38916, 'Proverbs 26:16', 'Proverbs', 26, 16, 'لټ انسان خپل ځان د حکمت خاوند ګڼي د اووه هوښیارانو نه چې په حکمت ځواب ورکوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_016.mp3', NULL, 1761758823, 1761758823),
(38917, 'Proverbs 26:17', 'Proverbs', 26, 17, 'څوک چې په غوسه د بل په شخړه کې لاس وهنه کوي لکه څوک چې کوڅه‌ډب سپی له غوږونو نه راونیسي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_017.mp3', NULL, 1761758823, 1761758823),
(38918, 'Proverbs 26:18', 'Proverbs', 26, 18, 'لکه څنګه چې یو لېونی د اور سکروټې او وژونکي غشي وروي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_018.mp3', NULL, 1761758823, 1761758823),
(38919, 'Proverbs 26:19', 'Proverbs', 26, 19, 'د هغه چا په شان دی څوک چې بل غولوي او بیا وایي چې ما ټوکې کولې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_019.mp3', NULL, 1761758823, 1761758823),
(38920, 'Proverbs 26:20', 'Proverbs', 26, 20, 'له لرګیو او پوکي پرته اور مړ کیږي او د غیبت پرته جنګ ختمیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_020.mp3', NULL, 1761758823, 1761758823),
(38921, 'Proverbs 26:21', 'Proverbs', 26, 21, 'لکه څنګه چې لرګي اور اخلي او سکاره په سکروټو بدلیږي همداسې د جنګ اور له جګړه‌مار سړي نه پورته کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_021.mp3', NULL, 1761758823, 1761758823),
(38922, 'Proverbs 26:22', 'Proverbs', 26, 22, 'د غیبت کوونکي خبرې د خوندور خوراک په شان دي چې د انسان له ستوني تېریږي او د ګېډې تل ته ښکته کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_022.mp3', NULL, 1761758823, 1761758823),
(38923, 'Proverbs 26:23', 'Proverbs', 26, 23, 'خوږې خبرې د زړه شرارت پټوي لکه په خاورین لوښي چې رنګ پورې شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_023.mp3', NULL, 1761758823, 1761758823),
(38924, 'Proverbs 26:24', 'Proverbs', 26, 24, 'کینه ناک انسان په خوږو خبرو خپله کرکه پټوي خو د زړه په تل کې یې ټګي ساتلې وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_024.mp3', NULL, 1761758823, 1761758823),
(38925, 'Proverbs 26:25', 'Proverbs', 26, 25, 'کله چې هغه خوږې خبرې کوي نو باور پرې مه کوه ځکه زړه یې د اووه بدیو نه ډک دی چې د کرکې وړ دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_025.mp3', NULL, 1761758823, 1761758823),
(38926, 'Proverbs 26:26', 'Proverbs', 26, 26, 'که د هغه کرکه په دروغو د پردې لاندې پټه وي خو شرارت به یې ټولو خلکو ته بیاهم ښکاره شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_026.mp3', NULL, 1761758823, 1761758823),
(38927, 'Proverbs 26:27', 'Proverbs', 26, 27, 'څوک چې بل ته کنده کیندي نو په خپله به په کې راوغورځیږي او څوک چې د بل په طرف تیږه ورغړوي نو په خپله به پرې راورغړیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_027.mp3', NULL, 1761758823, 1761758823),
(38928, 'Proverbs 26:28', 'Proverbs', 26, 28, 'دروغجنه ژبه او کرکه د سړي زړه ټوټې ټوټې کوي او د غوړه‌مالۍ خبرې تباهي راولي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs26_verse_028.mp3', NULL, 1761758823, 1761758823),
(38929, 'Proverbs 11:1', 'Proverbs', 11, 1, 'څښتن د تلې له غلط کارولو نه کرکه کوي خو په پوره کاڼي تول تل خوښوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_001.mp3', NULL, 1761758823, 1761758823),
(38930, 'Proverbs 11:2', 'Proverbs', 11, 2, 'کله چې غرور راشي نو رسوایي هم راځي خو د عاجزۍ سره حکمت راځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_002.mp3', NULL, 1761758823, 1761758823),
(38931, 'Proverbs 11:3', 'Proverbs', 11, 3, 'د صادقانو پاک زړه د هغوی لارښوونه کوي خو د خاینانو ګمراهي هغوی تباه کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_003.mp3', NULL, 1761758823, 1761758823),
(38932, 'Proverbs 11:4', 'Proverbs', 11, 4, 'د عدالت په ورځ دولت ګټه نه لري خو صداقت انسان له مرګ نه ژغوري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_004.mp3', NULL, 1761758823, 1761758823),
(38933, 'Proverbs 11:5', 'Proverbs', 11, 5, 'د پاک انسان صداقت د هغه لار سموي خو د بدکاره انسان بدي هغه راغورځوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_005.mp3', NULL, 1761758823, 1761758823),
(38934, 'Proverbs 11:6', 'Proverbs', 11, 6, 'د رښتینو خلکو صداقت هغوی ژغوري خو د خاینانو غوښتنې هغوی په دام کې نښلوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_006.mp3', NULL, 1761758823, 1761758823),
(38935, 'Proverbs 11:7', 'Proverbs', 11, 7, 'کله چې یو بدکاره مري هیله یې تباه کیږي نو زر او زور او ټول ارمانونه یې هم تباه کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_007.mp3', NULL, 1761758823, 1761758823),
(38936, 'Proverbs 11:8', 'Proverbs', 11, 8, 'نېک انسان له سختۍ نه ژغورل کیږي او په ځای یې بدکاره انسان د تکلیف په لور روانیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_008.mp3', NULL, 1761758823, 1761758823),
(38937, 'Proverbs 11:9', 'Proverbs', 11, 9, 'بې‌ایمانه انسان په خپلو خبرو نور تباه کوي خو نېکان د خپل علم له امله ژغورل کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_009.mp3', NULL, 1761758823, 1761758823),
(38938, 'Proverbs 11:10', 'Proverbs', 11, 10, 'نېکان چې بریالي کیږي ټول ښار پرې خوشحالیږي او بدکاران چې تباه کیږي د خوشحالۍ چیغې وهل کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_010.mp3', NULL, 1761758823, 1761758823),
(38939, 'Proverbs 11:11', 'Proverbs', 11, 11, 'ښار د رښتینو خلکو په برکت ودانیږي خو د بدکارانو د خولې په خبرو ورانیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_011.mp3', NULL, 1761758823, 1761758823),
(38940, 'Proverbs 11:12', 'Proverbs', 11, 12, 'څوک چې بل ته په سپکه سترګه ګوري ناپوهه دی خو د پوهې خاوند خپله خوله پټه ساتي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_012.mp3', NULL, 1761758823, 1761758823),
(38941, 'Proverbs 11:13', 'Proverbs', 11, 13, 'غیبت کوونکی د نورو راز ښکاره کوي خو باوري انسان د بل په راز پرده اچوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_013.mp3', NULL, 1761758823, 1761758823),
(38942, 'Proverbs 11:14', 'Proverbs', 11, 14, 'کله چې ښې مشورې نه وي نو ولس له پښو غورځیږي خو که مشوره ورکوونکي ډېر وي د بریالیتوب سبب ګرځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_014.mp3', NULL, 1761758823, 1761758823),
(38943, 'Proverbs 11:15', 'Proverbs', 11, 15, 'په قرض کې د بل چا ضمانت کوونکي به زیان ومومي خو په قرض کې له لاس ورکولو نه ډډه کوونکی به ډاډه وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_015.mp3', NULL, 1761758823, 1761758823),
(38944, 'Proverbs 11:16', 'Proverbs', 11, 16, 'مهربانه ښځه تل عزت ګټي خو ظالمان یوازې دولت ګټي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_016.mp3', NULL, 1761758823, 1761758823),
(38945, 'Proverbs 11:17', 'Proverbs', 11, 17, 'مهربان انسان ځان ته ګټه رسوي خو بې‌رحمه انسان ځان ته زیان رسوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_017.mp3', NULL, 1761758823, 1761758823),
(38946, 'Proverbs 11:18', 'Proverbs', 11, 18, 'د بدکاره سړي ګټه بې‌برکته ده خو د نېکۍ کرونکی حقیقي حاصل رېبي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_018.mp3', NULL, 1761758823, 1761758823),
(38947, 'Proverbs 11:19', 'Proverbs', 11, 19, 'څوک چې په صداقت ولاړ وي نېکمرغه ژوند لري شرارت پېښوونکی په خپل مرګ پسې ګرځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_019.mp3', NULL, 1761758823, 1761758823),
(38948, 'Proverbs 11:20', 'Proverbs', 11, 20, 'څښتن د کږو لارو له خاوندانو نه کرکه کوي خو د پاک زړه خاوندان خوښوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_020.mp3', NULL, 1761758823, 1761758823),
(38949, 'Proverbs 11:21', 'Proverbs', 11, 21, 'باور ولره چې بدکاران به بې‌سزا پاتې نه شي خو د نېکانو اولادونه به خلاصون ومومي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_021.mp3', NULL, 1761758823, 1761758823),
(38950, 'Proverbs 11:22', 'Proverbs', 11, 22, 'د بې‌تمیزه او بې‌حیا ښځې ښکلا داسې ده لکه د خوګ په پوزه کې چې د سرو زرو پېزوان وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_022.mp3', NULL, 1761758823, 1761758823),
(38951, 'Proverbs 11:23', 'Proverbs', 11, 23, 'د نېکانو هیلې په برکت تمامیږي خو د بدکارانو امیدونه د غضب سبب ګرځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_023.mp3', NULL, 1761758823, 1761758823),
(38952, 'Proverbs 11:24', 'Proverbs', 11, 24, 'څوک چې سخاوت کوي نور به هم شتمن شي خو څوک چې سختي کوي نور به هم نېستمن شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_024.mp3', NULL, 1761758823, 1761758823),
(38953, 'Proverbs 11:25', 'Proverbs', 11, 25, 'یو سخي سړی به تل اباد شي څوک چې د نورو تنده ماتوي خپله تنده به یې هم ماته شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_025.mp3', NULL, 1761758823, 1761758823),
(38954, 'Proverbs 11:26', 'Proverbs', 11, 26, 'د ګرانۍ په مقصد غله ساتونکي باندې لعنت ویل کیږي خو په خرڅوونکي باندې تل برکت ویل کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_026.mp3', NULL, 1761758823, 1761758823),
(38955, 'Proverbs 11:27', 'Proverbs', 11, 27, 'څوک چې د ښو په لټه کې وي نو د نورو په رضا پسې ګرځي خو څوک چې په شرارت پسې ګرځي نو له مصیبت سره مخامخ کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_027.mp3', NULL, 1761758823, 1761758823),
(38956, 'Proverbs 11:28', 'Proverbs', 11, 28, 'څوک چې په خپلې شتمنۍ تکیه کوي نو راغورځیږي خو نېکان د شنو پاڼو په شان تازه کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_028.mp3', NULL, 1761758823, 1761758823),
(38957, 'Proverbs 11:29', 'Proverbs', 11, 29, 'خپلې کورنۍ ته مصیبت رسوونکی په باد پسې منډې وهي او جاهل سړی تل د حکمت د خاوند غلام وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_029.mp3', NULL, 1761758823, 1761758823),
(38958, 'Proverbs 11:30', 'Proverbs', 11, 30, 'د نېک انسان د کار ثمره د ژوندانه ونه ده او د حکمت خاوند د خلکو زړونه لاسته راوړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_030.mp3', NULL, 1761758823, 1761758823),
(38959, 'Proverbs 11:31', 'Proverbs', 11, 31, 'که نېکانو ته په دې دنیا کې انعام ورکول کیږي نو د بدکارانو او ګناهکارانو به څه حال وي؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs11_verse_031.mp3', NULL, 1761758823, 1761758823),
(38960, 'Psalms 25:1', 'Psalms', 25, 1, 'څښتنه ستا درګاه ته زه دعا کومه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms25_verse_001.mp3', NULL, 1761758823, 1761758823),
(38961, 'Psalms 25:2', 'Psalms', 25, 2, 'زما خدایه، توکل دی زما په تا مه مې پرېږده چې شرمنده شم مه پرېږده چې دښمنان مې شي خوشحال راباندې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms25_verse_002.mp3', NULL, 1761758823, 1761758823),
(38962, 'Psalms 25:3', 'Psalms', 25, 3, 'چې په تا کوي توکل هغه به نه شي شرمنده بې‌سببه چې خیانت کړي شي هغوی به شرمنده', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms25_verse_003.mp3', NULL, 1761758823, 1761758823),
(38963, 'Psalms 25:4', 'Psalms', 25, 4, 'ای څښتنه، خپلې لارې دې راوښایه ته ماته طریقې د ژوند رازده کړه خپلې ماته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms25_verse_004.mp3', NULL, 1761758823, 1761758823),
(38964, 'Psalms 25:5', 'Psalms', 25, 5, 'حقیقي لاره راوښایه ما پوه کړه ځکه ته زما ژغورونکی خدای یې تل په تا باندې توکل کړم', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms25_verse_005.mp3', NULL, 1761758823, 1761758823),
(38965, 'Psalms 25:6', 'Psalms', 25, 6, 'در په یاد کړه ای څښتنه هغه خپل رحم او تلپاتې مینه چې دې کوله له ازله ځینې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms25_verse_006.mp3', NULL, 1761758823, 1761758823),
(38966, 'Psalms 25:7', 'Psalms', 25, 7, 'ګناهونه او سرکښۍ د ځوانۍ مې کړه ته هېرې در په یاد مې کړه څښتنه په تلپاتې مینې خپلې مهربان یې ای څښتنه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms25_verse_007.mp3', NULL, 1761758823, 1761758823),
(38967, 'Psalms 25:8', 'Psalms', 25, 8, 'څښتن نېک دی او صادق دی ګناهکارو ته ورښایي سمه لاره', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms25_verse_008.mp3', NULL, 1761758823, 1761758823),
(38968, 'Psalms 25:9', 'Psalms', 25, 9, 'عاجزانو ته ورښایي نېغه لاره طریقه خپله وروښایي هغوی ته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms25_verse_009.mp3', NULL, 1761758823, 1761758823),
(38969, 'Psalms 25:10', 'Psalms', 25, 10, 'هغو خلکو ته به وکړي لارښوونه په مینه او وفا چې ولاړ د ده په لوظ وي او مني د ده حکمونه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms25_verse_010.mp3', NULL, 1761758823, 1761758823),
(38970, 'Psalms 25:11', 'Psalms', 25, 11, 'د خپل نوم په خاطر دې ای څښتنه ګناهونه زما معاف کړه ځکه زیات دي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms25_verse_011.mp3', NULL, 1761758823, 1761758823),
(38971, 'Psalms 25:12', 'Psalms', 25, 12, 'هغه څوک چې کوي وېره له څښتنه هغه وبه ښایي هغه ته سمه لاره چې پرې لاړ شي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms25_verse_012.mp3', NULL, 1761758823, 1761758823),
(38972, 'Psalms 25:13', 'Psalms', 25, 13, 'دی همېش به وي سوکاله اولاده به یې د ځمکې وارثان شي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms25_verse_013.mp3', NULL, 1761758823, 1761758823),
(38973, 'Psalms 25:14', 'Psalms', 25, 14, 'دی څښتن ملګری د هغو خلکو څوک چې کوي وېره د هغه ځینې دی به هغوی سره خپل لوظ کړي تایید', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms25_verse_014.mp3', NULL, 1761758823, 1761758823),
(38974, 'Psalms 25:15', 'Psalms', 25, 15, 'سترګې په لاره یمه همېش څښتن ته ځکه هغه مې خلاصوي د دښمن له دامه څخه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms25_verse_015.mp3', NULL, 1761758823, 1761758823),
(38975, 'Psalms 25:16', 'Psalms', 25, 16, 'زما خواته نظر وکړه ای څښتنه رحم وکړه په ما ځکه چې زه یمه تنها او هم مظلوم یمه زه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms25_verse_016.mp3', NULL, 1761758823, 1761758823),
(38976, 'Psalms 25:17', 'Psalms', 25, 17, 'د زړه غمونه مې زیات شوي دي ټولو سختیو نه نجات راکړه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms25_verse_017.mp3', NULL, 1761758823, 1761758823),
(38977, 'Psalms 25:18', 'Psalms', 25, 18, 'زما غمونو، تکلیفونو ته نظر وکړه ته او ګناهونه راته وبخښه ټول', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms25_verse_018.mp3', NULL, 1761758823, 1761758823),
(38978, 'Psalms 25:19', 'Psalms', 25, 19, 'ګوره څومره زیات دي دښمنان زما ګوره څومره سخت کوي نفرت له ما', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms25_verse_019.mp3', NULL, 1761758823, 1761758823),
(38979, 'Psalms 25:20', 'Psalms', 25, 20, 'ته مې وساته خلاصون راکړه ته ماته مه پرېږده چې شرمنده شم له همدې وجې پناه راوړمه تاته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms25_verse_020.mp3', NULL, 1761758823, 1761758823),
(38980, 'Psalms 25:21', 'Psalms', 25, 21, 'کړي نېکي او صداقت دې زما ساتنه ځکه چې زه کوم توکل په تا', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms25_verse_021.mp3', NULL, 1761758823, 1761758823),
(38981, 'Psalms 25:22', 'Psalms', 25, 22, 'ته کړه خلاص ای خدایه اسراییل له خپلو ټولو تکلیفونو', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms25_verse_022.mp3', NULL, 1761758823, 1761758823),
(38982, 'Psalms 12:1', 'Psalms', 12, 1, 'مرسته وکړه ای څښتنه! دیندار خلک پاتې نه شول وفادار انسانان ورک شول له دنیا نه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms12_verse_001.mp3', NULL, 1761758823, 1761758823),
(38983, 'Psalms 12:2', 'Psalms', 12, 2, 'دروغ وایي یو بل ته هغوی ټول هغوی یو بل غولوي په چاپلوسۍ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms12_verse_002.mp3', NULL, 1761758823, 1761758823),
(38984, 'Psalms 12:3', 'Psalms', 12, 3, 'غوړه‌مالې ژبې غوڅې کړه څښتنه! بندې هم لاپوکې خولې کړه چې وایي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms12_verse_003.mp3', NULL, 1761758823, 1761758823),
(38985, 'Psalms 12:4', 'Psalms', 12, 4, '«مونږ په خپلو ژبو شو ګټلی هرڅه مونږ ویلی شو هرڅه چې مونږ یې غواړو هېڅوک نه شي کړای زمونږه مخنیوی»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms12_verse_004.mp3', NULL, 1761758823, 1761758823),
(38986, 'Psalms 12:5', 'Psalms', 12, 5, '«خو به زه راپاڅېږمه اوس» څښتن وایي «دا په دې چې په غریبانو ظلم کیږي محتاجان کوي زګېروي له خپله درده ورته ور به کړم امنیت چې په ارمان یې دي»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms12_verse_005.mp3', NULL, 1761758823, 1761758823),
(38987, 'Psalms 12:6', 'Psalms', 12, 6, 'د څښتن ټولې وعدې داسې سوچه دي لکه اووه ځله چې سپین زر په داشونو کې سوچه شي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms12_verse_006.mp3', NULL, 1761758823, 1761758823),
(38988, 'Jeremiah 6:1', 'Jeremiah', 6, 1, 'اے د بنيامين خلقو، د خپل ځان د بچ کېدو دپاره منډه کړئ او د يروشلم نه وتښتئ. په تقوع کښې بيګل وغږوئ او په بيت‌هکرم کښې د خطرې اعلان وکړئ. ځکه چې د شمال طرف نه لوئ افت او بربادى راروانه ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_001.mp3', NULL, 1761758823, 1761758823),
(38989, 'Jeremiah 6:2', 'Jeremiah', 6, 2, 'زما د صيون ښکلې او نازکې لورې تۀ زما خوښه يې خو زۀ به دې تباه کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_002.mp3', NULL, 1761758823, 1761758823),
(38990, 'Jeremiah 6:3', 'Jeremiah', 6, 3, 'تا به دشمن داسې محاصره کړى لکه څنګه چې شپانو د ښار نه ګېرچاپېره خېمې لګولې وى. هر يو به خپل فوجى ته د تباه کولو ځائ ورښائى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_003.mp3', NULL, 1761758823, 1761758823),
(38991, 'Jeremiah 6:4', 'Jeremiah', 6, 4, 'دوئ به چغې وهى، ”راشئ او د جنګ دپاره تيار شئ. راځئ چې مونږ د غرمې په وخت حمله وکړُو. خو افسوس چې اوس ډېر ناوخته شو، د ورځ رڼا په ختمېدو شوه، او د ماښام تيارې راخورې شوې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_004.mp3', NULL, 1761758823, 1761758823),
(38992, 'Jeremiah 6:5', 'Jeremiah', 6, 5, 'راځئ چې د شپې په تيارۀ کښې حمله وکړُو او ټول محلونه يې تباه کړُو.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_005.mp3', NULL, 1761758823, 1761758823),
(38993, 'Jeremiah 6:6', 'Jeremiah', 6, 6, 'مالِک ربُ الافواج خُدائ فرمائى چې، ”ونې يې ووهئ، او د خاورو د ډېرو نه د يروشلم محاصره وکړئ. دې ښار ته دې سزا ورکړے شى، ځکه چې په دې کښې د ظلم او زياتى نه بغېر نور څۀ په نظر نۀ راځى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_006.mp3', NULL, 1761758823, 1761758823),
(38994, 'Jeremiah 6:7', 'Jeremiah', 6, 7, 'لکه څنګه چې د يو کوهى نه تازه اوبۀ راوځى، دغه شان د دې ښار نه تازه تازه فساد او شرارت راوځى. د دې ښار په هرې خوا او ګوټونو او کوڅو کښې د ظلم او زياتى آوازونه اورېدلے کيږى. د دې ښار بيمارى او زخمونه هر وخت زما د سترګو د وړاندې دى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_007.mp3', NULL, 1761758823, 1761758823),
(38995, 'Jeremiah 6:8', 'Jeremiah', 6, 8, 'اے د يروشلم خلقو د دې خبردارى نه سبق حاصل کړئ، کۀ زۀ تاسو نه لاس په سر شم، نو ستاسو ښار به تباه کړم، او هغه به نور د اوسېدو قابل نۀ وى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_008.mp3', NULL, 1761758823, 1761758823),
(38996, 'Jeremiah 6:9', 'Jeremiah', 6, 9, 'مالِک خُدائ ربُ الافواج فرمائى، ”تر دې چې کوم کسان په اِسرائيل کښې پاتې شوى دى هغوئ به دوباره راوشوکولے شى، لکه څنګه چې باغوان دوباره په بوټى کښې د پاتې شوو انګورو دانو د راشوکولو لټون کوى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_009.mp3', NULL, 1761758823, 1761758823),
(38997, 'Jeremiah 6:10', 'Jeremiah', 6, 10, 'ما ورته ووئيل، ”چا سره زۀ خبرې وکړم، چا ته خبردارے ورکړم؟ څوک به ما ته غوږ ونيسى؟ هغوئ خپل غوږونه کاڼۀ کړى دى او هغوئ اورېدل نۀ غواړى. دوئ د مالِک خُدائ کلام پورې خندا کوى. او په هغې خوشحاليږى نه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_010.mp3', NULL, 1761758823, 1761758823),
(38998, 'Jeremiah 6:11', 'Jeremiah', 6, 11, 'نو د دې دپاره زۀ د مالِک خُدائ د قهر نه ډک شوے يم، او د برداشت نه بهر شوے يم.“ مالِک خُدائ ما ته وفرمائيل چې، ”زۀ خپله غصه په کوڅو کښې په ماشومانو او د زلمو په ډلو او په ښځې او خاوند او په سپين‌ږيرو او بوډاګانو نازلوم.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_011.mp3', NULL, 1761758823, 1761758823),
(38999, 'Jeremiah 6:12', 'Jeremiah', 6, 12, 'مالِک خُدائ فرمائى چې، ”د هغوئ کورونه او زمکې سره د هغوئ د ښځو نورو ته حواله کړم، ځکه چې زۀ به خپل لاس د دې مُلک د خلقو په خلاف وراوږد کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_012.mp3', NULL, 1761758823, 1761758823),
(39000, 'Jeremiah 6:13', 'Jeremiah', 6, 13, 'د ماشومانو نه واخله تر بوډاګانو پورې هر يو د ناجائزه ګټې په لالچ کښې دى، د ‎پېغمبر نه واخله تر اِمام پورې ټول دوکه ماران دى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_013.mp3', NULL, 1761758823, 1761758823),
(39001, 'Jeremiah 6:14', 'Jeremiah', 6, 14, 'هغوئ زما د خلقو د سختو زخمونو عرضى علاج کوى. او کله چې خير نۀ وى نو هغوئ وائى چې، خير دے، خير به شى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_014.mp3', NULL, 1761758823, 1761758823),
(39002, 'Jeremiah 6:15', 'Jeremiah', 6, 15, 'آيا هغوئ په خپل دې پليت عمل شرمېدل څۀ؟ نه، هغوئ بلکل شرم نۀ لرلو، هغوئ په دې هم نۀ پوهيږى چې شرم څۀ ته وائى. دوئ به د تباه شوو په مينځ کښې حساب شى. زۀ به دوئ هم ختم کړم کله چې زۀ هغوئ ته سزا ورکوم،“ مالِک خُدائ فرمائى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_015.mp3', NULL, 1761758823, 1761758823),
(39003, 'Jeremiah 6:16', 'Jeremiah', 6, 16, 'مالِک خُدائ داسې فرمائى چې، ”لاړ شئ او په چوکونو کښې ودرېږئ او ګورئ. د پخوانو او هغه لارو تپوس وکړئ کومې چې د خير طرف ته ځى. په دې لاره باندې تلل به تاسو ته خير درکړى. خو تاسو ووئيل، ”نه، مونږ به په دې باندې نۀ ځُو.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_016.mp3', NULL, 1761758823, 1761758823),
(39004, 'Jeremiah 6:17', 'Jeremiah', 6, 17, 'بيا ما په تاسو باندې محافظان مقرر کړل چا چې به تاسو ته وئيل، د بيګل آواز ته غوږ ونيسئ. خو تاسو ووئيل چې، نه مونږ به ورته توجو نۀ ورکوو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_017.mp3', NULL, 1761758823, 1761758823),
(39005, 'Jeremiah 6:18', 'Jeremiah', 6, 18, 'نو د دې دپاره تاسو واورئ اے قومونو، او سوچ وکړئ، اے ګواهانو چې دوئ سره به څۀ کيږى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_018.mp3', NULL, 1761758823, 1761758823),
(39006, 'Jeremiah 6:19', 'Jeremiah', 6, 19, 'اے د دُنيا قومونو غوږ شئ، زۀ په دې خلقو افت راولم، کوم چې د دوئ د خپلو منصوبو مېوه ده، ځکه چې دوئ زما کلام ته توجو ورنۀ کړه او زما شريعت يې رد کړو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_019.mp3', NULL, 1761758823, 1761758823),
(39007, 'Jeremiah 6:20', 'Jeremiah', 6, 20, 'نو بيا يې څۀ فائده ده چې دوئ د شيبا نه ما ته عطر راوړى دى، او يا د لرې مُلکونه نه قيمتى خوشبودارې مصالحې راوړى دى. زۀ به ستاسو سوزېدونکې نذرانې نۀ قبلوم. ستاسو په قربانو زۀ نۀ خوشحالېږم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_020.mp3', NULL, 1761758823, 1761758823),
(39008, 'Jeremiah 6:21', 'Jeremiah', 6, 21, 'نو ځکه مالِک خُدائ فرمائى، زۀ به د دې خلقو په لارو کښې د تيندک خوړلو کاڼے ولګوم چې دوئ پرې تيندک وخورى او راپرېوځى. ترڅو پلار او زامن او ګاونډيان او دوستان پرې په شريکه راپرېوځى او هلاک شى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_021.mp3', NULL, 1761758823, 1761758823),
(39009, 'Jeremiah 6:22', 'Jeremiah', 6, 22, 'مالِک خُدائ فرمائى، ”د شمال د مُلک د خوا نه فوج راروان دے، او ستاسو خلاف يو لوئ او تکړه قوم د لرې نه د جنګ کولو په نيت راپاڅېدلے دے.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_022.mp3', NULL, 1761758823, 1761758823),
(39010, 'Jeremiah 6:23', 'Jeremiah', 6, 23, 'هغوئ په ليندو او نېزو سره سمبال دى، هغوئ ټول ظالمان او بې‌رحمه دى. ټول جنګيالى يې په آسونو سوارۀ او په جنګى صف بندۍ کښې راروان دى او د هغوئ شور لکه د غضبناک سمندر په شان دے او په تا، صيون لورې، د حملې کولو دپاره تيار دى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_023.mp3', NULL, 1761758823, 1761758823),
(39011, 'Jeremiah 6:24', 'Jeremiah', 6, 24, '”کله چې مونږ د دوئ په حقله واورېدل، نو زمونږ لاسونو همت پرېښودلو او په لړزېدو شول. لکه څنګه چې يوې ښځې ته د لنګون درد شروع شى دغه شان درد، يرې او وحشت راواخستلو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_024.mp3', NULL, 1761758823, 1761758823),
(39012, 'Jeremiah 6:25', 'Jeremiah', 6, 25, 'بهر مېدان ته مۀ ځئ، او په کوڅو کښې مۀ ګرځئ، ځکه چې زمونږ دشمن تُوره په لاس دے، او هرې خوا ته خوف خور شوے دے.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_025.mp3', NULL, 1761758823, 1761758823),
(39013, 'Jeremiah 6:26', 'Jeremiah', 6, 26, 'مالِک خُدائ خپلو خلقو ته فرمائى، ”اے زما غوره شوى قومه، د ټاټ جامې واغوندئ او په ايرو کښې ولوغړېږئ. داسې بد بد وير وکړئ لکه څوک يې چې په يک يو زوئ باندې کوى،“ ځکه چې تباه کوونکى به په مونږ ناګهانه حمله وکړى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_026.mp3', NULL, 1761758823, 1761758823),
(39014, 'Jeremiah 6:27', 'Jeremiah', 6, 27, '”اے يرمياه، ما تۀ د اوسپنې آزمائيونکے جوړ کړې او خپل قوم نه مې اوسپنه جوړه کړه. تۀ زما غوره شوے قوم وآزمايه ترڅو د دوئ د عمل درته پته ولګى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_027.mp3', NULL, 1761758823, 1761758823),
(39015, 'Jeremiah 6:28', 'Jeremiah', 6, 28, 'هغوئ ټول سخت سرکشه شوى دى، او بدرد وائى او زړونه يې لکه د اوسپنې او پيتلو په شان سخت دى، او دوئ ټول بې‌ايمانى کوى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_028.mp3', NULL, 1761758823, 1761758823),
(39016, 'Jeremiah 6:29', 'Jeremiah', 6, 29, 'د بټۍ لاندې خو سخت اور بليږى چې سيکه د سپينو زرو نه جدا کړى خو هغې زما قوم پاک نۀ کړو او بدعمله خلق ترې جدا نۀ شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_029.mp3', NULL, 1761758823, 1761758823),
(39017, 'Jeremiah 6:30', 'Jeremiah', 6, 30, 'هغوئ ته رد شوى سپين زر وئيلے شى، ځکه ما، مالِک خُدائ هغوئ رد کړى دى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah6_verse_030.mp3', NULL, 1761758823, 1761758823),
(39018, 'Psalms 121:1', 'Psalms', 121, 1, 'سترګې مې غرونو ته نیولې دي ماته له کوم ځایه به مرسته راځي؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms121_verse_001.mp3', NULL, 1761758823, 1761758823),
(39019, 'Psalms 121:2', 'Psalms', 121, 2, 'ما سره کیږي مرسته د څښتن له خوا نه چا چې جوړ کړي اسمان او ځمکه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms121_verse_002.mp3', NULL, 1761758823, 1761758823),
(39020, 'Psalms 121:3', 'Psalms', 121, 3, 'تا به پرېنږدي چې وښویېږې د ستا ساتونکی بېداره پاتې کیږي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms121_verse_003.mp3', NULL, 1761758823, 1761758823),
(39021, 'Psalms 121:4', 'Psalms', 121, 4, 'په رښتیا څوک چې ساتونکی دی د اسراییلو بېداره پاتې کیږي او هېڅکله نه ویده کیږي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms121_verse_004.mp3', NULL, 1761758823, 1761758823),
(39022, 'Psalms 121:5', 'Psalms', 121, 5, 'څښتن ساتونکی دی ستا څښتن د سیوري په شان تا سره دی', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms121_verse_005.mp3', NULL, 1761758823, 1761758823),
(39023, 'Psalms 121:6', 'Psalms', 121, 6, 'نه به لمر د ورځې تاته کوم زیان رسوي او نه سپوږمۍ په شپه کې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms121_verse_006.mp3', NULL, 1761758823, 1761758823),
(39024, 'Psalms 121:7', 'Psalms', 121, 7, 'تا به څښتن له هر ضرره ساتي او تا به خوندي ساتي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms121_verse_007.mp3', NULL, 1761758823, 1761758823),
(39025, 'Psalms 121:8', 'Psalms', 121, 8, 'په تلو راتللو کې به دې ساتي څښتن له همدا‌اوس نه تر ابده پورې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms121_verse_008.mp3', NULL, 1761758823, 1761758823),
(39026, 'Daniel 8:1', 'Daniel', 8, 1, 'د بيلشضر بادشاه د بادشاهۍ په درېم کال، ما دانيال بله رويا وليده، د هغې رويا نه وروستو کومه چې ما مخکښې ليدلې وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_001.mp3', NULL, 1761758823, 1761758823),
(39027, 'Daniel 8:2', 'Daniel', 8, 2, 'په رويا کښې ما خپل ځان د سوسه قلعه په خوا کښې د عيلام په صوبه کښې د اولائى نِهر په غاړه ولاړ وليدلو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_002.mp3', NULL, 1761758823, 1761758823),
(39028, 'Daniel 8:3', 'Daniel', 8, 3, 'ما وکتل چې هلته زما د وړاندې يو د دوو ښکرو والا ګډ د نِهر په غاړه ولاړ وو، او ښکرونه يې اوږدۀ وُو. او يو ښکر يې د بل نه اوږد وو خو دا وروستو لوئ شوے وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_003.mp3', NULL, 1761758823, 1761758823),
(39029, 'Daniel 8:4', 'Daniel', 8, 4, 'نو ما وليدل چې هغه ګډ د مغرب او شمال او جنوب طرف ته يې ښکرونه وهل. او يو ځناور هم د هغۀ مقابله نۀ شوه کولے، او هيچا څوک هم د هغۀ د زور نه خلاصولے نۀ شُو. څۀ چې يې زړۀ غوښتل هغه يې کول، هغه ډېر طاقتور شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_004.mp3', NULL, 1761758823, 1761758823),
(39030, 'Daniel 8:5', 'Daniel', 8, 5, 'کله چې ما د دې په حقله سوچ کولو، نو ناڅاپه يو چېلے چې د سترګو په مينځ کښې يې مضبوط ښکر وو د مشرق طرف نه راغلو، هغه زمکې سره د لګېدو نه بغېر د ټولې دُنيا نه راواوړېدو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_005.mp3', NULL, 1761758823, 1761758823),
(39031, 'Daniel 8:6', 'Daniel', 8, 6, 'هغه د هغه دوو ښکرو والا ګډ له کوم چې ما د نِهر په غاړه ليدلے وو په تېزه او غصه ورغلو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_006.mp3', NULL, 1761758823, 1761758823),
(39032, 'Daniel 8:7', 'Daniel', 8, 7, 'ما هغه وليدو چې په هغه ګډ يې په ډيرې غصې سره حمله وکړه، هغه ګډ يې لاندې راوغورزولو او د هغۀ دواړه ښکرونه يې ټوټه ټوټه کړل. د هغۀ په نسبت هغه ډېر کمزورے وو چې د هغۀ مقابله يې کړے وے، چېلى هغه لاندې په زمکه راوغورزولو او د پښو لاندې يې کړو، او چا هم هغه ګډ د هغۀ د زور نه بچ کولے نۀ شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_007.mp3', NULL, 1761758823, 1761758823),
(39033, 'Daniel 8:8', 'Daniel', 8, 8, 'چېلے ډېر زورَور شو، خو د خپل طاقت آخرى حد ته په رسېدلو باندې د هغۀ لوئ ښکر مات شو، او د دې په ځائ څلور اوچت ښکرونه راوختل چې مخ يې د زمکې څلورو خواو ته وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_008.mp3', NULL, 1761758823, 1761758823),
(39034, 'Daniel 8:9', 'Daniel', 8, 9, 'په هغې کښې د يو ښکر نه بل راووتلو، چې په شروع کښې ورکوټے وو خو هغه د جنوب او مشرق طرف ته او د اِسرائيل د ښائسته مُلک طرف ته اوږد او طاقتور شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_009.mp3', NULL, 1761758823, 1761758823),
(39035, 'Daniel 8:10', 'Daniel', 8, 10, 'دا دومره غټ شو چې آسمانى لښکرو ته ورسېدو، او هغۀ څۀ آسمانى لښکر او ستورى لاندې راوغورزول او د پښو لاندې يې کړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_010.mp3', NULL, 1761758823, 1761758823),
(39036, 'Daniel 8:11', 'Daniel', 8, 11, 'هغۀ خپل ځان د آسمانى لښکرو د شهزاده په شان دومره اوچت وګڼلو، او هغۀ ته د روزانه قربانۍ پېش کول يې ختم کړل او د مالِک خُدائ کور يې پليت کړو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_011.mp3', NULL, 1761758823, 1761758823),
(39037, 'Daniel 8:12', 'Daniel', 8, 12, 'ځکه د سرکشۍ په وجه، آسمانى لښکرې او روزمره قربانى د ښکر قدرت ته ورکړے شُو. او هغه د هر کار په کولو کښې کامياب شو او حقيقت زمکې ته وغورزولے شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_012.mp3', NULL, 1761758823, 1761758823),
(39038, 'Daniel 8:13', 'Daniel', 8, 13, 'نو بيا ما واورېدل چې يوې مقدسې فرښتې خبرې کولې او بلې مقدسې فرښتې ورته وفرمائيل چې، ”دا کارونه به ترڅو پورې جارى وى کوم چې په رويا کښې وليدلے شُو؟ ترڅو پورې به دا ګناه د روزمره قربانۍ په بدله کښې کيږى؟ ترڅو پورې به آسمانى لښکرې او د مالِک خُدائ کور د پښو لاندې کيږى؟“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_013.mp3', NULL, 1761758823, 1761758823),
(39039, 'Daniel 8:14', 'Daniel', 8, 14, 'بيا فرښتې ما ته وفرمائيل، ”دا به تر دوه زره او درې سوه ماښامونو او سحرونو پورې وخت واخلى، او د هغې نه وروستو به د مالِک خُدائ کور دوباره مقدس کړے شى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_014.mp3', NULL, 1761758823, 1761758823),
(39040, 'Daniel 8:15', 'Daniel', 8, 15, 'کله چې ما دانيال دا رويا کتله او په دې د پوهېدلو کوشش مې کولو، نو زما په وړاندې څوک ودرېدو چې لکه د انسان غوندې ښکارېدو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_015.mp3', NULL, 1761758823, 1761758823),
(39041, 'Daniel 8:16', 'Daniel', 8, 16, 'او ما د اولائى نِهر د غاړې نه د يو سړى آواز واورېدو چې وې فرمائيل، ”اے جبرائيله، دې سړى ته د دې رويا مطلب ووايه.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_016.mp3', NULL, 1761758823, 1761758823),
(39042, 'Daniel 8:17', 'Daniel', 8, 17, 'کله چې هغه ما ته نزدې راغلو چرته چې زۀ ولاړ وم، نو زۀ وويرېدلم او پړمخې په زمکه پرېوتلم. هغۀ ما ته وفرمائيل، ”اے بنى آدمه، په دې پوهه شه چې د دې رويا تعلق د آخرى زمانې سره دے.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_017.mp3', NULL, 1761758823, 1761758823),
(39043, 'Daniel 8:18', 'Daniel', 8, 18, 'کله چې هغۀ ما ته خبرې کولې، زۀ بې‌هوشه وم، په زمکه پړمخې پروت وم. بيا هغۀ زۀ ونيولم او په خپلو پښو يې ودرولم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_018.mp3', NULL, 1761758823, 1761758823),
(39044, 'Daniel 8:19', 'Daniel', 8, 19, 'بيا هغۀ ما ته وفرمائيل، ”زۀ د دې دپاره راغلم چې تا ته ووايم چې وروستو د غضب په وخت کښې به څۀ وشى، ځکه چې د دې رويا تعلق د آخرى زمانې سره دے.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_019.mp3', NULL, 1761758823, 1761758823),
(39045, 'Daniel 8:20', 'Daniel', 8, 20, 'کوم د دوو ښکرو ګډ چې تا وليدو دا د مادى او فارس د بادشاهانو نمائندګى کوى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_020.mp3', NULL, 1761758823, 1761758823),
(39046, 'Daniel 8:21', 'Daniel', 8, 21, 'دا وېښتو والا چېلے د يونان بادشاه دے، او هغه د سترګو په مينځ کښې لوئ ښکر اولنے بادشاه دے.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_021.mp3', NULL, 1761758823, 1761758823),
(39047, 'Daniel 8:22', 'Daniel', 8, 22, 'هغه څلور ښکرونه کوم چې د هغۀ يو مات شوى ښکر په ځائ راوتلو د دې مطلب دا دے چې د اول بادشاهۍ نه به څلور نورې بادشاهۍ جوړې شى خو يو به هم دومره زور طاقت نۀ لرى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_022.mp3', NULL, 1761758823, 1761758823),
(39048, 'Daniel 8:23', 'Daniel', 8, 23, 'د دوئ د بادشاهۍ په آخرى ورځو کښې کله چې د دې سرکشى او بدکارى آخرى حد ته ورسيږى، نو يو ظالم او ماهر مکار بادشاه به راوچت شى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_023.mp3', NULL, 1761758823, 1761758823),
(39049, 'Daniel 8:24', 'Daniel', 8, 24, 'هغه به ډېر طاقتور شى، خو دا به د دۀ خپل طاقت نۀ وى. هغه به د حېرانونکى تباهۍ سبب شى او څۀ چې هغه کوى په هغې کښې به کامياب شى. هغه به زورَور خلق او د ايماندارانو قوم تباه کړى. ‏', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_024.mp3', NULL, 1761758823, 1761758823),
(39050, 'Daniel 8:25', 'Daniel', 8, 25, 'د دوکې په سبب به هغه کامياب شى، او هغه به خپل ځان اوچت وګڼى. کله چې هغوئ ځان محفوظ وګڼى، هغه به ناګهانه ډېر خلق تباه کړى او د شهزادګانو د شهزاده خلاف به راپاڅى. خو بيا به هغه تباه شى، خو دا نه چې د انسان په طاقت.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_025.mp3', NULL, 1761758823, 1761758823),
(39051, 'Daniel 8:26', 'Daniel', 8, 26, 'د ماښامونو او سحرونو د قربانيانو کومه رويا چې تا ته ښودلے شوې ده هغه حقيقى ده، خو دا رويا پټه وساته، ځکه چې دا د ډېر لرې مستقبل په حقله ده.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_026.mp3', NULL, 1761758823, 1761758823),
(39052, 'Daniel 8:27', 'Daniel', 8, 27, 'زۀ دانيال، ډيرې ورځې خفه او بيمار وم. بيا زۀ پاڅېدم او د بادشاه کارونو له واپس لاړم. زۀ د دې رويا په وجه خفه وم، دا د پوهې نه بهر وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel8_verse_027.mp3', NULL, 1761758823, 1761758823),
(39053, 'Psalms 116:1', 'Psalms', 116, 1, 'مینه کومه د څښتن سره زه ځکه چې سوال یې اورېدلی زما او قبولې کړې یې زارۍ دي زما', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms116_verse_001.mp3', NULL, 1761758823, 1761758823),
(39054, 'Psalms 116:2', 'Psalms', 116, 2, 'هغه نیولی دی خپل غوږ ماته ترڅو ژوندی یم دعاګانې به کومه ورته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms116_verse_002.mp3', NULL, 1761758823, 1761758823),
(39055, 'Psalms 116:3', 'Psalms', 116, 3, 'د مرګ په لومه کې راګېر شومه زه د قبر وېره راغله په ما په تکلیف او غم اخته شومه زه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms116_verse_003.mp3', NULL, 1761758823, 1761758823),
(39056, 'Psalms 116:4', 'Psalms', 116, 4, 'نو بیا مې وکړلو فریاد څښتن ته: «سوال کوم تاته ای څښتنه چې مې وژغوره ته»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms116_verse_004.mp3', NULL, 1761758823, 1761758823),
(39057, 'Psalms 116:5', 'Psalms', 116, 5, 'څښتن رحیم او نېک دی دی زړه‌سواندی زمونږ خدای', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms116_verse_005.mp3', NULL, 1761758823, 1761758823),
(39058, 'Psalms 116:6', 'Psalms', 116, 6, 'څښتن ساتي ساده زړي خلک کله چې ومه په خطر کې، هغه بچ کړمه زه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms116_verse_006.mp3', NULL, 1761758823, 1761758823),
(39059, 'Psalms 116:7', 'Psalms', 116, 7, 'ای زما ځانه ته ډاډه اوسه ځکه څښتن ما سره کړی احسان', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms116_verse_007.mp3', NULL, 1761758823, 1761758823),
(39060, 'Psalms 116:8', 'Psalms', 116, 8, 'څښتنه تا له مرګه بچ کړمه زه وچې دې کړې اوښکې زما او ودې ژغورلې زما پښې له تیندک خوړلو څخه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms116_verse_008.mp3', NULL, 1761758823, 1761758823),
(39061, 'Psalms 116:9', 'Psalms', 116, 9, 'نو زه به ګرځم د څښتن حضور کې د ژوندیو په دنیا کې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms116_verse_009.mp3', NULL, 1761758823, 1761758823),
(39062, 'Psalms 116:10', 'Psalms', 116, 10, 'ما په څښتن باندې باور درلود که څه هم ما وویل: «زه ډېر په تکلیف کې یمه»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms116_verse_010.mp3', NULL, 1761758823, 1761758823),
(39063, 'Psalms 116:11', 'Psalms', 116, 11, 'که څه هم زه وېرېدمه خو ما وویل: «ټول انسانان دروغجن دي»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms116_verse_011.mp3', NULL, 1761758823, 1761758823),
(39064, 'Psalms 116:12', 'Psalms', 116, 12, 'زه به څه ورکړم څښتن ته د هغو ټولو احسانونو په بدل کې چې یې کړي دي زما سره؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms116_verse_012.mp3', NULL, 1761758823, 1761758823),
(39065, 'Psalms 116:13', 'Psalms', 116, 13, 'زه به راوړمه څښتن ته نذرانه د څښلو چې ترې مننه وکړم د خپل نجات په خاطر', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms116_verse_013.mp3', NULL, 1761758823, 1761758823),
(39066, 'Psalms 116:14', 'Psalms', 116, 14, 'زه به ورکړمه نذرونه چې مې منلي دي څښتن ته د هغه د ټول قوم په مخکې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms116_verse_014.mp3', NULL, 1761758823, 1761758823),
(39067, 'Psalms 116:15', 'Psalms', 116, 15, 'څومره دردناکه ده څښتن دپاره چې کله مړ شي کوم یو د هغه له وفادارو څخه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms116_verse_015.mp3', NULL, 1761758823, 1761758823),
(39068, 'Psalms 116:16', 'Psalms', 116, 16, 'زه خدمتګار یمه د ستا څښتنه داسې خدمت دې زه کومه چې مې مور کړی دی زه دې خلاص کړی یم له زنځیرونو څخه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms116_verse_016.mp3', NULL, 1761758823, 1761758823),
(39069, 'Psalms 116:17', 'Psalms', 116, 17, 'د شکرګزارۍ قرباني به تاته درکړمه زه زه به تاته دعاګانې کوم', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms116_verse_017.mp3', NULL, 1761758823, 1761758823),
(39070, 'Deuteronomy 29:1', 'Deuteronomy', 29, 1, 'دا د هغه لوظ شرطونه دي چې څښتن موسی ته حکم کړی ؤ چې د اسراییلو د خلکو سره یې د موآب په خاوره کې وکړي. دا د هغه لوظ څخه بېل ؤ چې څښتن د هغوی سره د سینا د غره سره کړی ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy29_verse_001.mp3', NULL, 1761758823, 1761758823),
(39071, 'Deuteronomy 29:2', 'Deuteronomy', 29, 2, 'موسی د اسراییلو ټول خلک راوغوښتل او ورته ویې ویل: «تاسو په خپله ولیدل چې څښتن په مصر کې په فرعون، د هغه په درباریانو او د هغه په ټول هېواد باندې څه وکړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy29_verse_002.mp3', NULL, 1761758823, 1761758823),
(39072, 'Deuteronomy 29:3', 'Deuteronomy', 29, 3, 'تاسو هغه هیبتناکه بلاګانې، معجزې او هغه عجیبه کارونه ولیدل چې څښتن کړي وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy29_verse_003.mp3', NULL, 1761758823, 1761758823),
(39073, 'Deuteronomy 29:4', 'Deuteronomy', 29, 4, 'خو تر نن ورځې پورې هغه تاسو دې ته نه یئ پریښي چې په هغه څه باندې پوه شئ چې په تاسو باندې تېر شوي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy29_verse_004.mp3', NULL, 1761758823, 1761758823),
(39074, 'Deuteronomy 29:5', 'Deuteronomy', 29, 5, 'څښتن څلوېښت کاله تاسو ته په دښته کې لارښوونه وکړه او په دې موده کې ستاسو کالي او څپلۍ هېڅ زاړه نه شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy29_verse_005.mp3', NULL, 1761758823, 1761758823),
(39075, 'Deuteronomy 29:6', 'Deuteronomy', 29, 6, 'تاسو د خوراک دپاره ډوډۍ نه درلودله او نه مو د څښاک دپاره شراب درلودل، خو څښتن تاسو ته ځانګړي خواړه برابر کړل د دې دپاره چې تاسو په دې باندې پوه شئ چې هغه ستاسو خدای دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy29_verse_006.mp3', NULL, 1761758823, 1761758823),
(39076, 'Deuteronomy 29:7', 'Deuteronomy', 29, 7, 'کله چې مونږ دلته راغلو، د حشبون پاچا سیحون او د باشان پاچا عوج په مونږ باندې حمله وکړه. خو مونږ هغوی ته ماتې ورکړه،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy29_verse_007.mp3', NULL, 1761758823, 1761758823),
(39077, 'Deuteronomy 29:8', 'Deuteronomy', 29, 8, 'د هغوی خاوره مو ونیوله او هغه مو د روبین او جاد د قبیلو او منسي د نیمې قبیلې ترمنځ ووېشله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy29_verse_008.mp3', NULL, 1761758823, 1761758823),
(39078, 'Deuteronomy 29:9', 'Deuteronomy', 29, 9, 'د دې لوظ د ټولو شرطونو څخه په وفادارۍ سره اطاعت وکړئ، ترڅو تاسو په خپل هر کار کې بریالي اوسئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy29_verse_009.mp3', NULL, 1761758823, 1761758823),
(39079, 'Deuteronomy 29:12', 'Deuteronomy', 29, 12, 'تاسو نن دلته د دې دپاره ولاړ یئ چې په هغه لوظ کې شامل شئ چې خپل څښتن خدای یې ستاسو سره کوي او د هغه شرطونه قبول کړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy29_verse_012.mp3', NULL, 1761758823, 1761758823),
(39080, 'Deuteronomy 29:16', 'Deuteronomy', 29, 16, 'ستاسو په یاد دي چې په مصر کې مو څنګه ژوند کاوه او څنګه د نورو قومونو د سیمې په لاره باندې تېر شولو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy29_verse_016.mp3', NULL, 1761758823, 1761758823),
(39081, 'Deuteronomy 29:17', 'Deuteronomy', 29, 17, 'تاسو د هغوی د کرکې وړ بتان ولیدل چې د لرګیو، تیږو، سپینو او سرو زرو څخه جوړ شوي وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy29_verse_017.mp3', NULL, 1761758823, 1761758823),
(39082, 'Deuteronomy 29:18', 'Deuteronomy', 29, 18, 'پام کوئ چې هېڅ سړی، ښځه، کورنۍ یا قبیله چې نن دلته ولاړ دي، زمونږ د څښتن خدای څخه به مخ نه اړوي او نه به د نورو قومونو د خدایانو عبادت کوي. که چېرې ستاسو څخه کوم یو د بتانو عبادت کوي هغه به د داسې بوټي په شان وي چې ترخه او زهرجنه مېوه نیسي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy29_verse_018.mp3', NULL, 1761758823, 1761758823),
(39083, 'Deuteronomy 29:19', 'Deuteronomy', 29, 19, 'ګورئ چې نن باید دلته داسې څوک نه وي چې د دې لوظ خبرې واوري او بیاهم خپل ځان ته دا ډاډګېرنه ورکړي چې حتی که چېرې هغه په سرزورۍ سره هم په خپله لاره لاړ شي، د هغه هر کار به په ښه ډول په مخ ځي. داسې کار به تاسو ټول ښه او بد یوشان تباه کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy29_verse_019.mp3', NULL, 1761758823, 1761758823),
(39084, 'Deuteronomy 29:20', 'Deuteronomy', 29, 20, 'څښتن به داسې سړی ونه بخښي، بلکې د هغه په ضد به د هغه قهر او غضب راوپاریږي او هغه ټول افتونه به چې په دې کتاب کې لیکل شوي دي په هغه باندې نازلیږي، ترڅو څښتن د هغه نوم او نښان د ځمکې د مخ څخه ورک کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy29_verse_020.mp3', NULL, 1761758823, 1761758823),
(39085, 'Deuteronomy 29:21', 'Deuteronomy', 29, 21, 'څښتن به د اسراییلو ټولو قبیلو ته هغه یو عبرت وګرځوي او د هغو ټولو لعنتونو سره سم به په هغه باندې افت نازل کړي چې په هغه لوظ کې شامل دي چې د څښتن د شریعت په دې کتاب کې لیکل شوی دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy29_verse_021.mp3', NULL, 1761758823, 1761758823),
(39086, 'Deuteronomy 29:24', 'Deuteronomy', 29, 24, 'بیا به د ټولې نړۍ خلک داسې پوښتنې کوي: ‹څښتن ولې د هغوی په هېواد باندې داسې وکړل؟ د دې سخت غضب دلیل څه دی؟›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy29_verse_024.mp3', NULL, 1761758823, 1761758823),
(39087, 'Deuteronomy 29:25', 'Deuteronomy', 29, 25, 'او ځواب به داسې وي: ‹دا ځکه چې دې خلکو د خپلو نیکونو د څښتن خدای لوظ مات کړی دی، هغه لوظ چې څښتن د هغوی سره هغه وخت کړی ؤ چې کله یې هغوی د مصر څخه راوویستل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy29_verse_025.mp3', NULL, 1761758823, 1761758823),
(39088, 'Deuteronomy 29:26', 'Deuteronomy', 29, 26, 'هغوی د نورو خدایانو عبادت کاوه چې مخکې یې هېڅکله نه ؤ کړی او څښتن د هغو عبادت منع کړی ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy29_verse_026.mp3', NULL, 1761758823, 1761758823),
(39089, 'Deuteronomy 29:27', 'Deuteronomy', 29, 27, 'نو څښتن په خپل قوم باندې په قهر شو او د هغوی په خاوره باندې یې هغه ټول افتونه نازل کړل چې په دې کتاب کې لیکل شوي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy29_verse_027.mp3', NULL, 1761758823, 1761758823),
(39090, 'Deuteronomy 29:28', 'Deuteronomy', 29, 28, 'څښتن سخت په قهر شو او د خپل سخت قهر په وخت کې یې هغوی د خپلې خاورې څخه وویستل او پردۍ خاورې ته یې وشړل او هغوی اوس هم هلته دي.›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy29_verse_028.mp3', NULL, 1761758823, 1761758823),
(39091, 'Deuteronomy 29:29', 'Deuteronomy', 29, 29, 'ځینې داسې خبرې شته چې زمونږ څښتن خدای زمونږ څخه پټې ساتلې دي، خو هغه خپل شریعت راته ښکاره کړی دی او مونږ او زمونږ اولاده باید د تل دپاره د هغه شریعت اطاعت وکړو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy29_verse_029.mp3', NULL, 1761758823, 1761758823),
(39092, 'Leviticus 8:1', 'Leviticus', 8, 1, 'څښتن موسی ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_001.mp3', NULL, 1761758823, 1761758823),
(39093, 'Leviticus 8:2', 'Leviticus', 8, 2, '«هارون او د هغه زامن راوله. د هغوی د کاهنتوب کالي، د مسح کولو تېل، د ګناه د نذرانې دپاره خوسی، دوه پسونه او هغه ټوکرۍ چې فطیره ډوډۍ په کې ده، ټول راوړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_002.mp3', NULL, 1761758823, 1761758823),
(39094, 'Leviticus 8:3', 'Leviticus', 8, 3, 'بیا ټول قوم د سپېڅلې خېمې د دروازې خولې ته راټول کړه.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_003.mp3', NULL, 1761758823, 1761758823),
(39095, 'Leviticus 8:4', 'Leviticus', 8, 4, 'موسی د څښتن حکم په ځای کړ او کله چې قوم راټول شو،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_004.mp3', NULL, 1761758823, 1761758823),
(39096, 'Leviticus 8:5', 'Leviticus', 8, 5, 'نو هغه ورته وویل: «اوس چې زه کوم کار کوم هغه د څښتن حکم دی.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_005.mp3', NULL, 1761758823, 1761758823),
(39097, 'Leviticus 8:6', 'Leviticus', 8, 6, 'بیا موسی هارون او د هغه زامن راوستل او غسل یې ورته ورکړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_006.mp3', NULL, 1761758823, 1761758823),
(39098, 'Leviticus 8:7', 'Leviticus', 8, 7, 'هغه هارون ته کمیس او چپنه واغوستله، د هغه په ملا باندې یې یوه پټۍ وتړله او سپېڅلی پېشبند یې ورباندې واچاوه او هغه یې په هغه ښه اوبدل شوي کمربند باندې وتاړه چې د هغه د ملا څخه تاو شوی ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_007.mp3', NULL, 1761758823, 1761758823),
(39099, 'Leviticus 8:8', 'Leviticus', 8, 8, 'د هغه په سینه باندې یې سینه پوښ وتاړه او په هغه کې یې اوریم او تمیم کېښودل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_008.mp3', NULL, 1761758823, 1761758823),
(39100, 'Leviticus 8:9', 'Leviticus', 8, 9, 'لکه څنګه چې څښتن موسی ته امر کړی ؤ، هغه هارون ته لونګۍ ور په سر کړه او د هغې په مخه کې یې د سرو زرو ګل یعنې د وقف کولو پاکه نښه کېښودله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_009.mp3', NULL, 1761758823, 1761758823),
(39101, 'Leviticus 8:10', 'Leviticus', 8, 10, 'بیا موسی د مسح کولو تېل واخیستل او هغه یې په خېمه او ټولو شیانو باندې چې په هغې کې وو، وشیندل او په دې ډول یې هغه ټول څښتن ته وقف کړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_010.mp3', NULL, 1761758823, 1761758823),
(39102, 'Leviticus 8:11', 'Leviticus', 8, 11, 'هغه لږ تېل واخیستل او اووه ځلې یې د قربانۍ په ځای باندې وشیندل او د قربانۍ ځای یې د لوښو او تشت سره چې پایه یې درلودله، مسح کړه چې څښتن ته یې وقف کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_011.mp3', NULL, 1761758823, 1761758823),
(39103, 'Leviticus 8:12', 'Leviticus', 8, 12, 'همدارنګه هغه د مسح کولو لږ تېل د هارون په سر باندې توی کړل او هغه یې د کاهنۍ د دندې دپاره وقف کړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_012.mp3', NULL, 1761758823, 1761758823),
(39104, 'Leviticus 8:13', 'Leviticus', 8, 13, 'بیا لکه څنګه چې څښتن موسی ته امر کړی ؤ، هغه د هارون زامن مخکې راوستل او هغوی ته یې کمیسونه واغوستل، په ملاګانو باندې یې ورته پټۍ ګانې وتړلې او خولۍ ګانې یې ورته په سر کړې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_013.mp3', NULL, 1761758823, 1761758823),
(39105, 'Leviticus 8:14', 'Leviticus', 8, 14, 'بیا موسی د ګناه د نذرانې دپاره خوسی راوست او هارون او د هغه زامنو د هغه په سر باندې خپل لاسونه کېښودل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_014.mp3', NULL, 1761758823, 1761758823),
(39106, 'Leviticus 8:15', 'Leviticus', 8, 15, 'موسی خوسی حلال کړ او لږه وینه یې راواخیستله او هغه یې په خپله ګوته باندې د قربانۍ د ځای په ټولو ښکرونو باندې وسولوله، د دې دپاره چې د قربانۍ ځای سپېڅلی شي. بیا هغه پاتې وینه د قربانۍ د ځای په بېخ کې تویه کړه. په دې ډول د قربانۍ ځای سپېڅلی شو او هغه د ګناه په خاطر د قربانۍ د نذرانې دپاره یو مناسب ځای شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_015.mp3', NULL, 1761758823, 1761758823),
(39107, 'Leviticus 8:16', 'Leviticus', 8, 16, 'همدارنګه موسی ټوله وازګه چې په کولمو باندې پرته وه، د اینې ډېره ښه برخه او پښتورګي چې وازګه ورباندې پرته وي، واخیستل او ټول یې د قربانۍ په ځای باندې وسوځول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_016.mp3', NULL, 1761758823, 1761758823),
(39108, 'Leviticus 8:17', 'Leviticus', 8, 17, 'څنګه چې څښتن حکم کړی ؤ هغه پاتې خوسی د پوستکي، غوښې او خوشایو سره واخیست او هغه یې د کمپ څخه دباندې وسوځاوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_017.mp3', NULL, 1761758823, 1761758823),
(39109, 'Leviticus 8:18', 'Leviticus', 8, 18, 'بیا موسی د سوځېدونکې نذرانې دپاره پسه راوست او هارون او د هغه زامنو د پسه په سر باندې خپل لاسونه کېښودل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_018.mp3', NULL, 1761758823, 1761758823),
(39110, 'Leviticus 8:19', 'Leviticus', 8, 19, 'موسی پسه حلال کړ او وینه یې د قربانۍ د ځای په څلورو خواو باندې وشیندله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_019.mp3', NULL, 1761758823, 1761758823),
(39111, 'Leviticus 8:20', 'Leviticus', 8, 20, 'هغه پسه ټوټې ټوټې کړ او هغه یې د سر او پاتې ټوټو او وازګې سره وسوځول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_020.mp3', NULL, 1761758823, 1761758823),
(39112, 'Leviticus 8:21', 'Leviticus', 8, 21, 'څنګه چې څښتن موسی ته امر کړی ؤ، هغه د نس دنننۍ برخې او پښې ووینځلې او ټول پسه یې د قربانۍ په ځای باندې وسوځاوه. دا یوه سوځېدونکې نذرانه وه چې بوی یې په څښتن باندې ښه ولګېده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_021.mp3', NULL, 1761758823, 1761758823),
(39113, 'Leviticus 8:22', 'Leviticus', 8, 22, 'بیا موسی بل پسه راوست. دا پسه د کاهنانو د ټاکنې دپاره ؤ. هارون او د هغه زامنو خپل لاسونه د هغه په سر باندې کېښودل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_022.mp3', NULL, 1761758823, 1761758823),
(39114, 'Leviticus 8:23', 'Leviticus', 8, 23, 'موسی پسه حلال کړ او د هغه لږه وینه یې واخیستله او د هارون د ښي غوږ په نرمۍ، د ښي لاس په غټې ګوتې او د ښي پښې په غټه ګوته یې وسولوله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_023.mp3', NULL, 1761758823, 1761758823),
(39115, 'Leviticus 8:24', 'Leviticus', 8, 24, 'بیا یې د هارون زامن مخکې راوستل او د هغوی د ښي غوږونو په نرمیو، د ښي لاسونو په غټو ګوتو او د ښي پښو په غټو ګوتو یې لږه وینه وسولوله او پاتې وینه یې د قربانۍ د ځای په څلورو خواو باندې وشیندله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_024.mp3', NULL, 1761758823, 1761758823),
(39116, 'Leviticus 8:25', 'Leviticus', 8, 25, 'هغه وازګه، لم، هغه ټوله وازګه چې په کولمو باندې پرته وي، د اینې ډېره ښه برخه، پښتورګي د وازګې سره چې ورباندې پرته وي او ښي ورون واخیستل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_025.mp3', NULL, 1761758823, 1761758823),
(39117, 'Leviticus 8:26', 'Leviticus', 8, 26, 'بیا هغه د فطیرې ډوډۍ د ټوکرۍ څخه چې څښتن ته وقف شوې وه یوه ساده ډوډۍ، یوه غوړه ډوډۍ او یوه نرۍ ډوډۍ راواخیستله او د وازګې او ښي ورون دپاسه یې کېښودله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_026.mp3', NULL, 1761758823, 1761758823),
(39118, 'Leviticus 8:27', 'Leviticus', 8, 27, 'موسی هغه ټول د هارون او د هغه د زامنو په لاسونو کې کېښودل او دوی هغه پورته ونیول، ترڅو دا وښایي چې هغه څښتن ته وقف شوي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_027.mp3', NULL, 1761758823, 1761758823),
(39119, 'Leviticus 8:28', 'Leviticus', 8, 28, 'بیا موسی دا شیان د هغوی څخه بېرته واخیستل او هغه یې د ټاکنې د نذرانې په توګه د سوځېدونکې نذرانې سره د قربانۍ په ځای باندې وسوځول. د داسې نذرانې بوی په څښتن باندې ښه لګېده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_028.mp3', NULL, 1761758823, 1761758823),
(39120, 'Leviticus 8:29', 'Leviticus', 8, 29, 'بیا موسی د پسه سینه راواخیستله او د څښتن په حضور کې یې پورته ونیوله، ترڅو دا وښایي چې هغه څښتن ته وقف شوې ده. دا د ټاکنې په پسه کې د موسی برخه وه. موسی دا ټول کارونه د څښتن د حکم سره سم سرته ورسول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_029.mp3', NULL, 1761758823, 1761758823),
(39121, 'Leviticus 8:30', 'Leviticus', 8, 30, 'موسی لږ د مسح کولو تېل او لږه وینه چې د قربانۍ په ځای باندې پرته وه واخیستل او په هارون، د هغه په زامنو او د هغو په کالیو باندې یې وشیندل. په دې ډول یې هغوی او د هغوی کالي څښتن ته وقف کړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_030.mp3', NULL, 1761758823, 1761758823),
(39122, 'Leviticus 8:31', 'Leviticus', 8, 31, 'موسی هارون او د هغه زامنو ته وویل: «لکه څنګه چې څښتن حکم کړی دی دا غوښه د سپېڅلې خېمې د دروازې په خوله کې پخه کړئ او هلته یې د هغې ډوډۍ سره چې د ټاکنې د نذرانې په ټوکرۍ کې ده، وخورئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_031.mp3', NULL, 1761758823, 1761758823),
(39123, 'Leviticus 8:32', 'Leviticus', 8, 32, 'کومه غوښه یا ډوډۍ چې پاتې شي، نو هغه وسوځوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_032.mp3', NULL, 1761758823, 1761758823),
(39124, 'Leviticus 8:33', 'Leviticus', 8, 33, 'تاسو به اووه ورځې د خېمې د دروازې د خولې څخه نه ځئ، ترڅو پورې چې ستاسو د ټاکنې مراسم پوره شوي نه وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_033.mp3', NULL, 1761758823, 1761758823),
(39125, 'Leviticus 8:34', 'Leviticus', 8, 34, 'مونږ چې نن کوم کار وکړ، څښتن د هغه د کولو حکم مونږ ته کړی ؤ، د دې په خاطر چې ستاسو د ګناه دپاره کفاره ادا کړو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_034.mp3', NULL, 1761758823, 1761758823),
(39126, 'Leviticus 8:35', 'Leviticus', 8, 35, 'تاسو باید د سپېڅلې خېمې د دروازې په خوله کې اووه شپې او اووه ورځې پاتې شئ او هغه کار به کوئ چې څښتن یې امر کړی دی. که چېرې داسې ونه کړئ نو مړه به شئ، ځکه چې څښتن په ما باندې داسې امر کړی دی.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_035.mp3', NULL, 1761758823, 1761758823),
(39127, 'Leviticus 8:36', 'Leviticus', 8, 36, 'نو هارون او د هغه زامنو ټول کارونه د څښتن د هغه حکم له مخې وکړل چې د موسی په وسیله یې کړی ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus8_verse_036.mp3', NULL, 1761758823, 1761758823),
(39128, 'Proverbs 3:1', 'Proverbs', 3, 1, 'ای زما زویه! زما تعلیم مه هېروه او زما حکمونه په خپل زړه کې ټینګ وساته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_001.mp3', NULL, 1761758823, 1761758823),
(39129, 'Proverbs 3:2', 'Proverbs', 3, 2, 'ځکه دا به ستا د عمر ورځې او کلونه ډېر کړي او سوله او سلامتي به در په برخه کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_002.mp3', NULL, 1761758823, 1761758823),
(39130, 'Proverbs 3:3', 'Proverbs', 3, 3, 'مینه او وفا د خپل ځانه مه لېرې کوه هغه د تل دپاره د خپلې غاړې هار کړه او د خپل زړه په تخته یې ولیکه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_003.mp3', NULL, 1761758823, 1761758823),
(39131, 'Proverbs 3:4', 'Proverbs', 3, 4, 'نو بیا به ته د خدای او انسان په نظر کې نېک وګڼل شې او د یو هوښیار انسان په توګه وپېژندل شې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_004.mp3', NULL, 1761758823, 1761758823),
(39132, 'Proverbs 3:5', 'Proverbs', 3, 5, 'په خپل ټول زړه په څښتن توکل کوه او په خپل عقل او پوهه تکیه مه کوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_005.mp3', NULL, 1761758823, 1761758823),
(39133, 'Proverbs 3:6', 'Proverbs', 3, 6, 'په هر کار کې د هغه د حضور غوښتنه کوه نو هغه به ستا لارې هوارې کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_006.mp3', NULL, 1761758823, 1761758823),
(39134, 'Proverbs 3:7', 'Proverbs', 3, 7, 'په خپل فکر ځان د حکمت خاوند مه ګڼه له څښتن څخه وېره کوه او له بدۍ نه مخ واړوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_007.mp3', NULL, 1761758823, 1761758823),
(39135, 'Proverbs 3:8', 'Proverbs', 3, 8, 'نو په دې به ستا بدن تل روغ وي او ټول وجود به دې تازه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_008.mp3', NULL, 1761758823, 1761758823),
(39136, 'Proverbs 3:9', 'Proverbs', 3, 9, 'په خپلې شتمنۍ سره د څښتن عزت کوه او د خپل ټول فصل لومړنۍ مېوه ورکوه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_009.mp3', NULL, 1761758823, 1761758823),
(39137, 'Proverbs 3:10', 'Proverbs', 3, 10, 'نو بیا به ستا ګودامونه له غلي دانې نه ډک شي او چاټۍ‌ګانې به دې د انګورو له شیرې څخه له خولې نه واوړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_010.mp3', NULL, 1761758823, 1761758823),
(39138, 'Proverbs 3:11', 'Proverbs', 3, 11, 'نو ای زما زویه! د څښتن اصلاح ته په سپکه سترګه مه ګوره او کله چې تا رټي نو هېڅکله مه خفه کېږه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_011.mp3', NULL, 1761758823, 1761758823),
(39139, 'Proverbs 3:12', 'Proverbs', 3, 12, 'ځکه څښتن چې له چا سره مینه کوي نو هغه ته سزا ورکوي لکه یو پلار ته چې کوم زوی منلی وي نو رټنه یې د محبت نښه ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_012.mp3', NULL, 1761758823, 1761758823),
(39140, 'Proverbs 3:13', 'Proverbs', 3, 13, 'بختور دی هغه څوک چې حکمت حاصل کړي او هغه څوک چې پوهه پیدا کړي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_013.mp3', NULL, 1761758823, 1761758823),
(39141, 'Proverbs 3:14', 'Proverbs', 3, 14, 'ځکه چې د هغې ثمره له سپینو زرو نه غوره ده او حاصل یې له سرو زرو نه ډېر زیات دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_014.mp3', NULL, 1761758823, 1761758823),
(39142, 'Proverbs 3:15', 'Proverbs', 3, 15, 'هغه د لعلونو نه ډېر قیمتي دی چې له ارزښت سره یې ستا له خوښې هېڅ ګټه برابره نه ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_015.mp3', NULL, 1761758823, 1761758823),
(39143, 'Proverbs 3:16', 'Proverbs', 3, 16, 'د هغې په یو لاس کې اوږد ژوند دی او په بل لاس کې یې دولت او عزت دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_016.mp3', NULL, 1761758823, 1761758823),
(39144, 'Proverbs 3:17', 'Proverbs', 3, 17, 'لارې یې خوشحالوونکې دي او ټولې لارې یې د سولې او سلامتۍ دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_017.mp3', NULL, 1761758823, 1761758823),
(39145, 'Proverbs 3:18', 'Proverbs', 3, 18, 'څوک چې هغې ته غېږ ورکوي نو د هغوی دپاره د ژوندانه ونه ده او بختور دي هغه څوک چې هغې ته ټینګه غاړه ورکوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_018.mp3', NULL, 1761758823, 1761758823),
(39146, 'Proverbs 3:19', 'Proverbs', 3, 19, 'څښتن په خپل حکمت سره د ځمکې بنیاد کېښود او اسمانونه یې د خپلې پوهې په وسیله پیدا کړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_019.mp3', NULL, 1761758823, 1761758823),
(39147, 'Proverbs 3:20', 'Proverbs', 3, 20, 'د هغه د علم په وسیله د ځمکې په تل کې د اوبو چینې روانیږي او له ورېځو نه یې باران او پرخه په ځمکه راوریږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_020.mp3', NULL, 1761758823, 1761758823),
(39148, 'Proverbs 3:21', 'Proverbs', 3, 21, 'نو ای زما زویه! پوهه له خپله نظره مه لېرې کوه او په خپل ځان کې د حکمت او لیاقت ټینګه ساتنه کوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_021.mp3', NULL, 1761758823, 1761758823),
(39149, 'Proverbs 3:22', 'Proverbs', 3, 22, 'دوی به ستا روح تازه ساتي او دا به ستا د غاړې د فضل هار وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_022.mp3', NULL, 1761758823, 1761758823),
(39150, 'Proverbs 3:23', 'Proverbs', 3, 23, 'نو بیا به په ډاډه زړه په خپله لار روان شې او ستا پښه به په تیږه نه لګیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_023.mp3', NULL, 1761758823, 1761758823),
(39151, 'Proverbs 3:24', 'Proverbs', 3, 24, 'کله چې ته ویده کېږې نو نه به وېرېږې او د څملاستو په وخت کې به په خواږه خوب ویده کېږې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_024.mp3', NULL, 1761758823, 1761758823),
(39152, 'Proverbs 3:25', 'Proverbs', 3, 25, 'نو له ناڅاپي بلا نه مه وېرېږه کله چې په تا راشي او نه د هغه توفان له تباهۍ نه چې په بدکارانو راځي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_025.mp3', NULL, 1761758823, 1761758823),
(39153, 'Proverbs 3:26', 'Proverbs', 3, 26, 'ځکه څښتن به تل ستا ساتونکی وي چې پښه دې په دام کې ونه نښلي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_026.mp3', NULL, 1761758823, 1761758823),
(39154, 'Proverbs 3:27', 'Proverbs', 3, 27, 'ترڅو چې د نېکۍ کولو توان لرې نو د مسکینانو سره له مرستې نه ډډه مه کوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_027.mp3', NULL, 1761758823, 1761758823),
(39155, 'Proverbs 3:28', 'Proverbs', 3, 28, 'کله چې څوک ستا نه څه وغواړي او ته یې ولرې نو ورته مه وایه چې نن لاړ شه او سبا راشه، بیا به یې درکړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_028.mp3', NULL, 1761758823, 1761758823),
(39156, 'Proverbs 3:29', 'Proverbs', 3, 29, 'د خپل ګاونډي په خلاف د زیان رسولو اراده مه لره څوک چې ستا په خوا کې اوسیږي او په تا باور کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_029.mp3', NULL, 1761758823, 1761758823),
(39157, 'Proverbs 3:30', 'Proverbs', 3, 30, 'ترڅو چې چا تاته زیان نه وي رسولی نو په هغه باندې بېځایه تور مه لګوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_030.mp3', NULL, 1761758823, 1761758823),
(39158, 'Proverbs 3:31', 'Proverbs', 3, 31, 'د ظالم انسان سره بخیلي مه کوه او د هغه د لارې پیروي مه کوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_031.mp3', NULL, 1761758823, 1761758823),
(39159, 'Proverbs 3:32', 'Proverbs', 3, 32, 'ځکه څښتن له هغه چا نه کرکه کوي چې په غلطه لار روان وي خو هغه د رښتینو خلکو سره د دوستۍ اړیکې لري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_032.mp3', NULL, 1761758823, 1761758823),
(39160, 'Proverbs 3:33', 'Proverbs', 3, 33, 'د څښتن لعنت د بدکاره انسان په کور باندې وریږي خو هغه د نېکو خلکو په کورنیو باندې برکت وروي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_033.mp3', NULL, 1761758823, 1761758823),
(39161, 'Proverbs 3:34', 'Proverbs', 3, 34, 'هغه په ملنډو وهونکو خندا کوي خو په عاجزانو خپل فضل کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_034.mp3', NULL, 1761758823, 1761758823),
(39162, 'Proverbs 3:35', 'Proverbs', 3, 35, 'د حکمت خاوندانو ته عزت په میراث کې رسیږي خو کم‌عقلان به د شرم سره مخامخ کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs3_verse_035.mp3', NULL, 1761758823, 1761758823),
(39163, 'Psalms 69:1', 'Psalms', 69, 1, 'وژغوره ما وژغوره ای خدایه اوبه نژدې دي چې نفس مې وباسي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_001.mp3', NULL, 1761758823, 1761758823),
