(39165, 'Psalms 69:3', 'Psalms', 69, 3, 'ستومانه شوی یمه زه چې نارې ووهم کومک دپاره زما ستونی دی وچ شوی ستا په انتظار مې سترګې ستړې شوې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_003.mp3', NULL, 1761758823, 1761758823),
(39166, 'Psalms 69:4', 'Psalms', 69, 4, 'چې بې‌سببه رانه کرکه کوي هغوی دي زیات زما د سر له ویښتو دښمنان زما په هکله دروغ وایي دوی دي قوي او غواړي ما ووژني مجبوروي مې دوی ته ورکړمه زه هغه شیان چې ما پټ کړي نه دي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_004.mp3', NULL, 1761758823, 1761758823),
(39167, 'Psalms 69:5', 'Psalms', 69, 5, 'ای خدایه ته ما پېژنې چې زه څومره کم‌عقل یمه ګناهونه زما نه دي پټ له تا نه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_005.mp3', NULL, 1761758823, 1761758823),
(39168, 'Psalms 69:6', 'Psalms', 69, 6, 'ای څښتنه ای مطلق قادره خدایه شرمنده نه دې شي زما په سبب څوک چې په تا باندې توکل کوي ای د اسراییلو خدایه رسوا دې نه شي هغوی زما په خاطر څوک چې تاته کړي رجوع', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_006.mp3', NULL, 1761758823, 1761758823),
(39169, 'Psalms 69:7', 'Psalms', 69, 7, 'ستا په خاطر مې سپکاوی وزغامه او په شرمونو پټ شوم', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_007.mp3', NULL, 1761758823, 1761758823),
(39170, 'Psalms 69:8', 'Psalms', 69, 8, 'خپلو خپلوانو ته پردی ښکارم خپل خاندان ته بېګانه ښکارم', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_008.mp3', NULL, 1761758823, 1761758823),
(39171, 'Psalms 69:9', 'Psalms', 69, 9, 'هغه غیرت چې زه یې لرم ستا د کور په خاطر زما بدن باندې یې اور بل کړی کومو خلکو چې وکړ ستا سپکاوي هغوی زما سپکاوی هم وکړلو', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_009.mp3', NULL, 1761758823, 1761758823),
(39172, 'Psalms 69:10', 'Psalms', 69, 10, 'کله چې زه شوم په ژړا ځان مې خاکسار کړ په روژه نیولو نو خلکو زه سپک کړمه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_010.mp3', NULL, 1761758823, 1761758823),
(39173, 'Psalms 69:11', 'Psalms', 69, 11, 'کله چې ما د ویر جامې واغوستې هغوی په ما پورې خندا وکړه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_011.mp3', NULL, 1761758823, 1761758823),
(39174, 'Psalms 69:12', 'Psalms', 69, 12, 'بازار کې ما پسې خبرې کوي او شرابیان زما په هکله جوړوي سندرې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_012.mp3', NULL, 1761758823, 1761758823),
(39175, 'Psalms 69:13', 'Psalms', 69, 13, 'خو زه به تاته کړم دعا څښتنه خدایه قبوله مې دعا کړه چې کله خوښه وي ستا په خاطر د خپلې زیاتې او تلپاتې مینې کړه زما دعا قبوله ځکه په وعده د نجات باندې وفا کوې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_013.mp3', NULL, 1761758823, 1761758823),
(39176, 'Psalms 69:14', 'Psalms', 69, 14, 'ما پرېنږدې چې شم ډوب خټو کې خوندي مې وساته له هغو چې نفرت کړي له ما ژورو اوبو څخه ما وساته ته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_014.mp3', NULL, 1761758823, 1761758823),
(39177, 'Psalms 69:15', 'Psalms', 69, 15, 'پرېنږدې چې سېلاب راباندی راشي پرې مې نه ږدې چې شم ډوب اوبو کې یا مې کړي تېر قبر ژوندی ځان ته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_015.mp3', NULL, 1761758823, 1761758823),
(39178, 'Psalms 69:16', 'Psalms', 69, 16, 'ای څښتنه ته قبوله مې دعا کړه ځکه تلپاتې مینه ستا غوره ده د خپلې زیاتې همدردۍ نه دې خپل مخ ماته راواړوه!', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_016.mp3', NULL, 1761758823, 1761758823),
(39179, 'Psalms 69:17', 'Psalms', 69, 17, 'د خپل بنده نه دې مخ مه پټوه د ډېر تکلیف سره زه مخ یمه قبوله مې دعا کړه زر', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_017.mp3', NULL, 1761758823, 1761758823),
(39180, 'Psalms 69:18', 'Psalms', 69, 18, 'ماته ته راشه او نجات راکړه خلاص مې کړه خپلو دښمنانو ځینې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_018.mp3', NULL, 1761758823, 1761758823),
(39181, 'Psalms 69:19', 'Psalms', 69, 19, 'ته ښه پوهېږې زما څومره سپکاوی شوی دی څومره رسوا او بې‌حرمته شومه ټول دښمنان زما ته وینې خپله', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_019.mp3', NULL, 1761758823, 1761758823),
(39182, 'Psalms 69:20', 'Psalms', 69, 20, 'په سپکاوي دی زما زړګی مات شوی او مایوس شوی یمه ما امید د خواخوږۍ لرلو خو هلته هېڅوک نه ؤ وم منتظر چې تسلي راکړي څوک خو څوک مې نه کړ پیدا', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_020.mp3', NULL, 1761758823, 1761758823),
(39183, 'Psalms 69:21', 'Psalms', 69, 21, 'چې کله وږی وم دوی زهر راکړل کله چې تږی وم سرکه یې راکړه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_021.mp3', NULL, 1761758823, 1761758823),
(39184, 'Psalms 69:22', 'Psalms', 69, 22, 'دسترخوانونه د دوی خپل دې دوی ته دام وګرځي ودې ګرځي د دوی مذهبي مېلې تیلک دوی ته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_022.mp3', NULL, 1761758823, 1761758823),
