(39187, 'Psalms 69:25', 'Psalms', 69, 25, 'وران او ویجاړ دې شي د دوی د اوسېدو ځایونه د دوی خېمو کې دې هېڅوک نه اوسي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_025.mp3', NULL, 1761758823, 1761758823),
(39188, 'Psalms 69:26', 'Psalms', 69, 26, 'ځکه هغه دوی ځوروي چې تا ورکړې سزا د هغو خلکو د کړاو په هکله کړي خبرې چې ژوبل کړي دي تا', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_026.mp3', NULL, 1761758823, 1761758823),
