(39190, 'Psalms 69:28', 'Psalms', 69, 28, 'د دوی نومونه دې شي ورک د ژوندانه له کتاب حساب دې نه شي په نېکانو کې دوی', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_028.mp3', NULL, 1761758823, 1761758823),
(39191, 'Psalms 69:29', 'Psalms', 69, 29, 'خو زه مظلوم یم او په غم کې ګېر یم ای خدایه ما کړه پورته نجات راکړه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_029.mp3', NULL, 1761758823, 1761758823),
