(39194, 'Psalms 69:32', 'Psalms', 69, 32, 'کله چې ویني مظلومان دغه کار نو خوشحالیږي به دوی کوم خلک چې کړي خدای ته رجوع شي به یې زړونه ژوندي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_032.mp3', NULL, 1761758823, 1761758823),
(39195, 'Psalms 69:33', 'Psalms', 69, 33, 'ځکه څښتن د محتاجانو قبلوي دعا خپل خلک به هېر نه کړي زندان کې هغه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_033.mp3', NULL, 1761758823, 1761758823),
(39196, 'Psalms 69:34', 'Psalms', 69, 34, 'ثنا او صفت وکړئ د خدای ای اسمانونو او ځمکې او هم بحرونو او هغې کې ګرځېدونکو ځناورو', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_034.mp3', NULL, 1761758823, 1761758823),
(39197, 'Psalms 69:35', 'Psalms', 69, 35, 'ځکه خدای به وژغوري صهیون بېرته اباد به کړي د یهودا ښارونه د هغه قوم به هلته اوسي او دوی به خپله کړي هغه ځمکه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_035.mp3', NULL, 1761758823, 1761758823),
(39198, 'Psalms 69:36', 'Psalms', 69, 36, 'اولاده به د هغوی یې وارثان شي اوسي به هلته څوک چې مینه کړي د هغه سره', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms69_verse_036.mp3', NULL, 1761758823, 1761758823),
(39199, 'Leviticus 23:1', 'Leviticus', 23, 1, 'څښتن موسی ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_001.mp3', NULL, 1761758823, 1761758823),
(39200, 'Leviticus 23:2', 'Leviticus', 23, 2, '«د اسراییلو خلکو ته ووایه چې ما ستاسو دپاره څو مذهبي اخترونه ټاکلي دي چې سره راټول شئ او زما عبادت وکړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_002.mp3', NULL, 1761758823, 1761758823),
(39201, 'Leviticus 23:3', 'Leviticus', 23, 3, 'تاسو د خپل کار دپاره شپږ ورځې لرئ، خو اوومه ورځ چې د سبت ورځ ده، د ارام کولو دپاره ده. په هغه ورځ کار مه کوئ، خو د عبادت دپاره راټول شئ. دا مهمه نه ده چې چېرته اوسېږئ، سبت د څښتن ورځ ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_003.mp3', NULL, 1761758823, 1761758823),
(39202, 'Leviticus 23:4', 'Leviticus', 23, 4, 'دغه اخترونه باید په ټاکل شویو وختونو کې اعلان کړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_004.mp3', NULL, 1761758823, 1761758823),
(39203, 'Leviticus 23:5', 'Leviticus', 23, 5, 'څښتن ته د درناوي کولو دپاره د فسحې د اختر لمانځل هر کال د لومړۍ میاشتې په څوارلسمه ورځ د لمرپرېواته په وخت کې پیل کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_005.mp3', NULL, 1761758823, 1761758823),
(39204, 'Leviticus 23:6', 'Leviticus', 23, 6, 'په پنځلسمه ورځ د فطیرې ډوډۍ اختر پیل کیږي او اووه ورځې دوام کوي. تاسو باید په دې موده کې فطیره ډوډۍ وخورئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_006.mp3', NULL, 1761758823, 1761758823),
(39205, 'Leviticus 23:7', 'Leviticus', 23, 7, 'د دغو ورځو څخه په لومړۍ ورځ د عبادت دپاره سره راټول شئ او هېڅ خپل ورځنی کار مه کوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_007.mp3', NULL, 1761758823, 1761758823),
(39206, 'Leviticus 23:8', 'Leviticus', 23, 8, 'اووه ورځې هغه نذرانې وړاندې کړئ چې څښتن ته په اور باندې تیاریږي او په اوومه ورځ به بیا د عبادت دپاره سره راټول شئ، خو هېڅ خپل ورځنی کار مه کوئ.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_008.mp3', NULL, 1761758823, 1761758823),
(39207, 'Leviticus 23:9', 'Leviticus', 23, 9, 'څښتن موسی ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_009.mp3', NULL, 1761758823, 1761758823),
(39208, 'Leviticus 23:10', 'Leviticus', 23, 10, '«د اسراییلیانو سره خبرې وکړه او ورته ووایه: کله چې تاسو هغې خاورې ته چې زه یې تاسو ته درکوم ورننوځئ او فصل یې ورېبئ، نو کاهن ته لومړنۍ ګېډۍ ورکړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_010.mp3', NULL, 1761758823, 1761758823),
(39209, 'Leviticus 23:11', 'Leviticus', 23, 11, 'هغه دې دا ګېډۍ د څښتن په حضور کې پورته کړي، ترڅو هغه ستاسو په خاطر قبوله شي. کاهن دې هغه د سبت د ورځې څخه وروسته په بله ورځ پورته کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_011.mp3', NULL, 1761758823, 1761758823),
(39210, 'Leviticus 23:12', 'Leviticus', 23, 12, 'په هماغه ورځ یوه سوځېدونکې نذرانه هم څښتن ته قرباني کړئ، یعنې یو وری چې یو کلن وي او هېڅ عیب په کې نه وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_012.mp3', NULL, 1761758823, 1761758823),
(39211, 'Leviticus 23:13', 'Leviticus', 23, 13, 'د هغې سره به تاسو د دوو کیلو ګرامو ښو اوړو د غلې دانې یوه نذرانه چې د زیتونو تېل ورسره ګډ وي وړاندې کړئ. دا یوه داسې نذرانه ده چې په اور باندې څښتن ته تیاریږي او بوی یې په هغه باندې ښه لګیږي. همدارنګه د هغې سره به تاسو د څښلو د نذرانې په توګه یو لیتر د شرابو نذرانه هم وړاندې کړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_013.mp3', NULL, 1761758823, 1761758823),
(39212, 'Leviticus 23:14', 'Leviticus', 23, 14, 'ترڅو پورې چې تاسو خدای ته دا نذرانه راوړې نه وي، نو نوې غلې دانې هېڅ مه خورئ. که هغه خامې وي، نینې شوې وي، یا ډوډۍ ورڅخه پخه شوې وي هغه دې ونه خوړل شي. په دې قانون باندې دې د تل دپاره ستاسو د ټولو نسلونو له خوا عمل وشي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_014.mp3', NULL, 1761758823, 1761758823),
(39213, 'Leviticus 23:15', 'Leviticus', 23, 15, 'د سبت د ورځې په سبا چې تاسو په کې څښتن ته د وړاندې کولو دپاره خپلې ګېډۍ راوړئ، پوره اووه هفتې وشمېرئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_015.mp3', NULL, 1761758823, 1761758823),
(39214, 'Leviticus 23:16', 'Leviticus', 23, 16, 'په پنځوسمه ورځ، یعنې هغه ورځ چې د اووم سبت څخه وروسته وي، د نوي حاصل څخه څښتن ته د غلې دانې بله نذرانه وړاندې کړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_016.mp3', NULL, 1761758823, 1761758823),
(39215, 'Leviticus 23:17', 'Leviticus', 23, 17, 'هره کورنۍ دې دوه ډوډۍ راوړي چې ماته د وقف کولو دپاره پورته ونیول شي. هره یوه دې د دوو کیلو ګرامو ښو اوړو څخه پخه شوې وي او خمیره هم په کې وي. دا به څښتن ته د لومړنیو رېبل شویو غلو دانو د نذرانې په توګه وړاندې شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_017.mp3', NULL, 1761758823, 1761758823),
(39216, 'Leviticus 23:18', 'Leviticus', 23, 18, 'قوم دې د ډوډۍ سره اووه یو کلن وري، یو غویی او دوه پسونه وړاندې کړي، د دغو څخه دې په یو کې هم کوم عیب نه وي. دا به د غلې دانې او د څښلو د نذرانې سره څښتن ته یوه سوځېدونکې نذرانه وي، یوه داسې نذرانه چې بوی یې په څښتن باندې ښه لګیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_018.mp3', NULL, 1761758823, 1761758823),
(39217, 'Leviticus 23:19', 'Leviticus', 23, 19, 'بیا د ګناه د نذرانې دپاره یو سېرلی او د سلامتۍ د نذرانې دپاره دوه یو کلن وري قرباني کړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_019.mp3', NULL, 1761758823, 1761758823),
(39218, 'Leviticus 23:20', 'Leviticus', 23, 20, 'کاهن دې هغه ډوډۍ چې د لومړنیو رېبل شویو غلو دانو نښه ده، د دوه وریو سره څښتن ته د وقف کېدلو په خاطر پورته ونیسي. دا څښتن ته یوه سپېڅلې نذرانه ده چې باید کاهنانو ته ورکړل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_020.mp3', NULL, 1761758823, 1761758823),
(39219, 'Leviticus 23:21', 'Leviticus', 23, 21, 'تاسو باید په هماغه ورځ د عبادت دپاره سره راټول شئ او هېڅ ورځنی کار ونه کړئ. هر چېرته چې ستاسو اولاده اوسیږي، دا مقررات دې تل ترتله مراعت کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_021.mp3', NULL, 1761758823, 1761758823),
(39220, 'Leviticus 23:22', 'Leviticus', 23, 22, 'کله چې تاسو د خپلو ځمکو حاصلات لو کوئ، نو هغه د پټیو تر غاړو پورې مه لو کوئ او هغه وږي چې د لو څخه پاتې شوي وي، هغه مه راټولوئ. هغه غریبانو او پردیو خلکو ته پرېږدئ. زه ستاسو څښتن خدای یم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_022.mp3', NULL, 1761758823, 1761758823),
(39221, 'Leviticus 23:23', 'Leviticus', 23, 23, 'څښتن موسی ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_023.mp3', NULL, 1761758823, 1761758823),
(39222, 'Leviticus 23:24', 'Leviticus', 23, 24, '«د اسراییلو قوم ته ووایه چې د هر کال د اوومې میاشتې لومړۍ ورځ د ارام کولو ځانګړې ورځ ده او د اسراییلو ټول خلک دې د سرني د اواز په اورېدلو سره د عبادت دپاره سره راټول شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_024.mp3', NULL, 1761758823, 1761758823),
(39223, 'Leviticus 23:25', 'Leviticus', 23, 25, 'په هماغه ورځ خپل عادي کار مه کوئ، خو څښتن ته یوه داسې نذرانه وړاندې کړئ چې په اور باندې تیاریږي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_025.mp3', NULL, 1761758823, 1761758823),
(39224, 'Leviticus 23:26', 'Leviticus', 23, 26, 'څښتن موسی ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_026.mp3', NULL, 1761758823, 1761758823),
(39225, 'Leviticus 23:27', 'Leviticus', 23, 27, '«هر کال د اوومې میاشتې لسمه ورځ د کفارې ورځ ده. په هغه ورځ د عبادت دپاره سره راټول شئ او روژه ونیسئ. یوه داسې نذرانه وړاندې کړئ چې څښتن ته په اور باندې تیاریږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_027.mp3', NULL, 1761758823, 1761758823),
(39226, 'Leviticus 23:28', 'Leviticus', 23, 28, 'په هغه ورځ هېڅ کار مه کوئ، ځکه چې دا د کفارې ورځ ده چې ستاسو دپاره ستاسو د څښتن خدای په حضور کې کفاره ادا کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_028.mp3', NULL, 1761758823, 1761758823),
(39227, 'Leviticus 23:29', 'Leviticus', 23, 29, 'هرڅوک چې په هغه ورځ روژه ونه نیسي باید د خدای د قوم څخه وشړل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_029.mp3', NULL, 1761758823, 1761758823),
(39228, 'Leviticus 23:30', 'Leviticus', 23, 30, 'که چېرې څوک په هغه ورځ کوم کار وکړي، زه به په خپله هغه ووژنم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_030.mp3', NULL, 1761758823, 1761758823),
(39229, 'Leviticus 23:31', 'Leviticus', 23, 31, 'دا قانون ستاسو په ټوله اولاده باندې هر چېرته چې اوسیږي، عملي کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_031.mp3', NULL, 1761758823, 1761758823),
(39230, 'Leviticus 23:32', 'Leviticus', 23, 32, 'د هغې میاشتې په نهمه ورځ د لمرپرېواته څخه نیولې د میاشتې د لسمې ورځې تر لمرپرېواته پورې دا ورځ د ارام کولو د یوې ځانګړې ورځې په توګه ولمانځئ او په دې دوران کې باید تاسو روژه ونیسئ.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_032.mp3', NULL, 1761758823, 1761758823),
(39231, 'Leviticus 23:33', 'Leviticus', 23, 33, 'څښتن موسی ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_033.mp3', NULL, 1761758823, 1761758823),
(39232, 'Leviticus 23:34', 'Leviticus', 23, 34, '«اسراییلیانو ته ووایه چې د اوومې میاشتې په پنځلسمه ورځ څښتن ته د درناوۍ دپاره د جونګړو اختر پیل کیږي. هغه اووه ورځې دوام کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_034.mp3', NULL, 1761758823, 1761758823),
(39233, 'Leviticus 23:35', 'Leviticus', 23, 35, 'په دغو ورځو کې لومړۍ ورځ د عبادت دپاره سره راټول شئ او خپل ورځنی کار مه کوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_035.mp3', NULL, 1761758823, 1761758823),
(39234, 'Leviticus 23:36', 'Leviticus', 23, 36, 'اووه ورځې څښتن ته داسې نذرانې وړاندې کړئ چې په اور باندې تیاریږي او په اتمه ورځ بیا د عبادت دپاره سره راټول شئ او د پخوا په شان نذرانه وړاندې کړئ. دا د عبادت ورځ ده او تاسو به خپل عادي کار نه کوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_036.mp3', NULL, 1761758823, 1761758823),
(39235, 'Leviticus 23:37', 'Leviticus', 23, 37, 'دا هغه اخترونه دي چې د څښتن له خوا ټاکل شوي دي. هغه داسې ولمانځئ چې سره راټول شئ او هغه ډول ډول نذرانې چې په اور باندې څښتن ته تیاریږي یعنې سوځېدونکې نذرانې، د غلو دانو نذرانې، قربانۍ او د څښلو نذرانې، دا هره یوه دې په خپله مناسبه ورځ هغه ته وړاندې شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_037.mp3', NULL, 1761758823, 1761758823),
(39236, 'Leviticus 23:38', 'Leviticus', 23, 38, 'دا اخترونه د سبت د ورځو څخه بېل دي او دا نذرانې د عادي سوغاتونو څخه بېلې دي، یعنې ستاسو د هغو نذرانو څخه چې د نذرونو دپاره دي او د هغو د خپلې خوښې نذرانو څخه چې څښتن ته یې ورکوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_038.mp3', NULL, 1761758823, 1761758823),
(39237, 'Leviticus 23:39', 'Leviticus', 23, 39, 'نو کله چې تاسو خپل پټي ورېبل، اووه ورځې دا اختر چې د اوومې میاشتې په پنځلسمه ورځ پیل کیږي، ولمانځئ. لومړۍ ورځ به د ارام کولو ورځ وي او اتمه ورځ به هم د ارام کولو ورځ وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_039.mp3', NULL, 1761758823, 1761758823),
(39238, 'Leviticus 23:40', 'Leviticus', 23, 40, 'په لومړۍ ورځ تاسو د خپلو ونو څخه ډېره ښه مېوه، د خرما د ونې څانګې، پاڼې لرونکې څانګې او د سیند د غاړو څخه ولې واخلئ او اووه ورځې د خپل څښتن خدای په حضور کې خوشحالي وکړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_040.mp3', NULL, 1761758823, 1761758823),
(39239, 'Leviticus 23:41', 'Leviticus', 23, 41, 'دا هر کال اووه ورځې څښتن ته د درناوي دپاره د یو اختر په توګه ولمانځئ. ستاسو راتلونکې اولاده دې تل ترتله د دې قانون څخه پیروي وکړي. هغه په اوومه میاشت ولمانځئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_041.mp3', NULL, 1761758823, 1761758823),
(39240, 'Leviticus 23:42', 'Leviticus', 23, 42, 'د اسراییلو ټول خلک باید اووه ورځې په جونګړو کې واوسیږي،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_042.mp3', NULL, 1761758823, 1761758823),
(39241, 'Leviticus 23:43', 'Leviticus', 23, 43, 'ترڅو ستاسو اولاده په دې پوه شي کله چې ما د اسراییلو قوم د مصر څخه راوویست، هغوی مې دې ته مجبور کړل چې په ساده جونګړو کې واوسیږي. زه ستاسو څښتن خدای یم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_043.mp3', NULL, 1761758823, 1761758823),
(39242, 'Leviticus 23:44', 'Leviticus', 23, 44, 'نو په دې ډول موسی د اسراییلو خلکو ته لارښوونه وکړه چې د څښتن اخترونه ولمانځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus23_verse_044.mp3', NULL, 1761758823, 1761758823),
(39243, 'Psalms 143:1', 'Psalms', 143, 1, 'ای څښتنه، زما دعا واوره زما زاریو ته ته غوږ ونیسه خپلې وفادارۍ او عدالت سره قبوله کړه دعا زما', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms143_verse_001.mp3', NULL, 1761758823, 1761758823),
(39244, 'Psalms 143:2', 'Psalms', 143, 2, 'خپل خدمتګار دې محاکمه نه کړې ته څوک بې‌ګناه نشته دی ستا نظر کې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms143_verse_002.mp3', NULL, 1761758823, 1761758823),
(39245, 'Psalms 143:3', 'Psalms', 143, 3, 'دښمنان په ما پسې دي او زه یې ځپلی یمه زه یې اچولی یم تیاره ځای کې د هغو خلکو په شان چې دي مړه شوي ډېر پخوا', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms143_verse_003.mp3', NULL, 1761758823, 1761758823),
(39246, 'Psalms 143:4', 'Psalms', 143, 4, 'نو کمزوری شوی زما روح دی ډېر وېرېدلی او نا‌امیده یمه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms143_verse_004.mp3', NULL, 1761758823, 1761758823),
(39247, 'Psalms 143:5', 'Psalms', 143, 5, 'رایادومه تېر وختونه زه کوم کارونه چې تا کړي دي د هغو ټولو په هکله کومه فکر زه ستا ټول کارونه راولم ذهن ته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms143_verse_005.mp3', NULL, 1761758823, 1761758823),
(39248, 'Psalms 143:6', 'Psalms', 143, 6, 'پورته کومه خپل لاسونه په دعا کې تاته د وچې ځمکې په شان تږی زما ځان دی تاته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms143_verse_006.mp3', NULL, 1761758823, 1761758823),
(39249, 'Psalms 143:7', 'Psalms', 143, 7, 'زر مې قبوله کړه دعا څښتنه ټول امیدونه مې ورکړي دي له لاسه ته دې خپل مخ له ما نه مه اړوه که نه نو زه به د هغو په شان شم چې وي روان قبر ته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms143_verse_007.mp3', NULL, 1761758823, 1761758823),
(39250, 'Psalms 143:8', 'Psalms', 143, 8, 'هر سهار راته رایاده کړه ته خپله تلپاتې مینه ځکه چې تا باندې باور لرمه ستا درګاه ته زه دعا کومه راته وښایه ته لاره چې پرې لاړ شمه زه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms143_verse_008.mp3', NULL, 1761758823, 1761758823),
(39251, 'Psalms 143:9', 'Psalms', 143, 9, 'د دښمنانو نه مې خلاص کړه ته ځکه چې تاته مې راوړې ده پناه څښتنه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms143_verse_009.mp3', NULL, 1761758823, 1761758823),
(39252, 'Psalms 143:10', 'Psalms', 143, 10, 'ته زما خدای یې، ماته وښایه ته خپله رضا چې یې پوره کړمه زه ستا نېک روح دې ماته وښایي سمه لاره', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms143_verse_010.mp3', NULL, 1761758823, 1761758823),
(39253, 'Psalms 143:11', 'Psalms', 143, 11, 'د خپل نوم په خاطر دې ای څښتنه زما ژوند وساته خپل عدالت په خاطر خلاص کړه تکلیفونو نه ما', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms143_verse_011.mp3', NULL, 1761758823, 1761758823),
(39254, 'Psalms 143:12', 'Psalms', 143, 12, 'د خپلې تلپاتې مینې په خاطر مړه دښمنان کړه زما تباه کړه هغه خلک چې کوي ظلم په ما ځکه چې زه ستا خدمتګار یمه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms143_verse_012.mp3', NULL, 1761758823, 1761758823),
(39255, 'Numbers 17:1', 'Numbers', 17, 1, 'څښتن موسی ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers17_verse_001.mp3', NULL, 1761758823, 1761758823),
(39256, 'Numbers 17:2', 'Numbers', 17, 2, '«د اسراییلو خلکو ته ووایه چې دولس امساګانې درکړي یعنې د هرې قبیلې د مشر څخه یوه یوه دانه. د هر سړي نوم د هغه په امسا باندې ولیکه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers17_verse_002.mp3', NULL, 1761758823, 1761758823),
(39257, 'Numbers 17:3', 'Numbers', 17, 3, 'او بیا د هارون نوم د لاویانو په امسا باندې ولیکه. د هر قبیلوي مشر دپاره دې یوه یوه امسا وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers17_verse_003.mp3', NULL, 1761758823, 1761758823),
(39258, 'Numbers 17:4', 'Numbers', 17, 4, 'دا امساګانې په سپېڅلې خېمه کې د لوظ د صندوق په مخکې چېرته چې زه تاسو سره ملاقات کوم، کېږده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers17_verse_004.mp3', NULL, 1761758823, 1761758823),
(39259, 'Numbers 17:5', 'Numbers', 17, 5, 'بیا به د هغه کس امسا غوټۍ ونیسي چې زه یې غوره کوم. په دې ډول به ستاسو په خلاف د دغو اسراییلیانو دوامداره شکایتونو ته د پای ټکی کېږدم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers17_verse_005.mp3', NULL, 1761758823, 1761758823),
(39260, 'Numbers 17:6', 'Numbers', 17, 6, 'موسی د اسراییلیانو سره خبرې وکړې او د هغوی هر یو مشر موسی ته امسا ورکړه، یعنې د هرې قبیلې څخه یوه یوه دانه چې ټولې دولس وې او د هارون امسا هم په کې شامله وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers17_verse_006.mp3', NULL, 1761758823, 1761758823),
(39261, 'Numbers 17:7', 'Numbers', 17, 7, 'بیا موسی ټولې امساګانې په خېمه کې د څښتن د لوظ د صندوق مخې ته کېښودلې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers17_verse_007.mp3', NULL, 1761758823, 1761758823),
(39262, 'Numbers 17:8', 'Numbers', 17, 8, 'په سبا ورځ کله چې موسی خېمې ته ورننوت، هغه ولیدل چې د هارون امسا چې د لاوي د قبیلې استازیتوب یې کوله تېغ وهلی. هغې غوټۍ کړې وې، ګلان یې نیولي وو او بادام یې کړي وو!', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers17_verse_008.mp3', NULL, 1761758823, 1761758823),
(39263, 'Numbers 17:9', 'Numbers', 17, 9, 'موسی هغه دولس امساګانې له خېمې څخه راوویستلې او خلکو ته یې ورښکاره کړې. هر مشر خپله امسا راپیدا کړه او هغه یې واخیستله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers17_verse_009.mp3', NULL, 1761758823, 1761758823),
(39264, 'Numbers 17:10', 'Numbers', 17, 10, 'خو څښتن موسی ته وویل: «د هارون امسا بېرته د لوظ صندوق ته مخامخ کېږده! پرېږده چې هغه هلته پاتې وي او د هغه چا دپاره چې د سرکښۍ کولو په اړه فکر کوي د خبرداري په توګه وي. که چېرې دا خلک زما په هکله شکایت بس نه کړي، نو زه به یې له منځه یوسم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers17_verse_010.mp3', NULL, 1761758823, 1761758823),
(39265, 'Numbers 17:11', 'Numbers', 17, 11, 'لکه څنګه چې څښتن حکم کړی ؤ، موسی هماغسې وکړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers17_verse_011.mp3', NULL, 1761758823, 1761758823),
(39266, 'Numbers 17:12', 'Numbers', 17, 12, 'اسراییلیانو موسی ته فریاد وکړ او ویې ویل: «مونږ مړه کېږو! زمونږ دپاره کومه هیله نشته، مونږ ټول له منځه ځو!', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers17_verse_012.mp3', NULL, 1761758823, 1761758823),
(39267, 'Numbers 17:13', 'Numbers', 17, 13, 'حتی هرڅوک چې سپېڅلې خېمې ته ورنژدې شي، هغه به مړ شي. نو مونږ ټول به مړه شو!»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers17_verse_013.mp3', NULL, 1761758823, 1761758823),
(39268, 'Numbers 20:1', 'Numbers', 20, 1, 'د اسراییلو ټول قوم د کال د اولې میاشتې په دوران کې د صین دښتې ته راورسېد او په قادش کې یې خېمې ودرولې. دا هغه ځای ؤ چې مریم په کې مړه شوه او ښخه کړای شوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_001.mp3', NULL, 1761758823, 1761758823),
(39269, 'Numbers 20:2', 'Numbers', 20, 2, 'په کوم ځای کې چې هغوی خېمې ودرولې وې هلته اوبه نه وې، نو خلک د موسی او هارون په ضد راټول شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_002.mp3', NULL, 1761758823, 1761758823),
(39270, 'Numbers 20:3', 'Numbers', 20, 3, 'هغوی موسی ته شکایت وکړ او ویې ویل: «دا به ښه وای چې مونږ د نورو اسراییلیانو سره د څښتن په حضور کې مړه شوي وای.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_003.mp3', NULL, 1761758823, 1761758823),
(39271, 'Numbers 20:4', 'Numbers', 20, 4, 'تا ولې مونږ دې دښتې ته راوستلو؟ یوازې د دې دپاره چې د خپلو حیواناتو سره دلته مړه شو؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_004.mp3', NULL, 1761758823, 1761758823),
(39272, 'Numbers 20:5', 'Numbers', 20, 5, 'ولې دې مونږ د مصر څخه دې خوار ځای ته چې هېڅ شی په کې نه شنه کیږي راوستلو؟ دلته نه غله شته، نه انځران، نه انګور او نه انار. حتی د څښلو اوبه هم دلته نشته!»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_005.mp3', NULL, 1761758823, 1761758823),
(39273, 'Numbers 20:6', 'Numbers', 20, 6, 'موسی او هارون د خلکو څخه لېرې لاړل او د سپېڅلې خېمې په دروازه کې ودرېدل. هغوی په سجده شول او د څښتن جلال ورته ښکاره شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_006.mp3', NULL, 1761758823, 1761758823),
(39274, 'Numbers 20:7', 'Numbers', 20, 7, 'څښتن موسی ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_007.mp3', NULL, 1761758823, 1761758823),
(39275, 'Numbers 20:8', 'Numbers', 20, 8, '«هغه امسا چې د لوظ د صندوق په مخکې پرته ده راواخله او بیا ته او هارون ټول قوم راټول کړئ. د هغو ټولو په مخکې هغه ګټ ته ووایئ چې اوبه ورڅخه جاري شي. په دې ډول به ته د ګټ څخه خلکو او د هغو حیواناتو ته د څښلو دپاره اوبه راوباسې.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_008.mp3', NULL, 1761758823, 1761758823),
(39276, 'Numbers 20:9', 'Numbers', 20, 9, 'نو موسی لاړ او څنګه چې څښتن ورته حکم کړی ؤ، امسا یې راواخیستله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_009.mp3', NULL, 1761758823, 1761758823),
(39277, 'Numbers 20:10', 'Numbers', 20, 10, 'هغه او هارون ټول قوم د ګټ مخې ته راټول کړ او موسی ورته وویل: «ای سرکښو خلکو، واورئ! ایا مونږ باید تاسو ته د دې ګټ څخه اوبه راوباسو؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_010.mp3', NULL, 1761758823, 1761758823),
(39278, 'Numbers 20:11', 'Numbers', 20, 11, 'بیا موسی امسا پورته کړه او ګټ یې دوه ځلې ورباندې وواهه او د هغه څخه د اوبو یوه لویه ویاله جاري شوه او ټولو خلکو او حیواناتو هغه وڅښلې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_011.mp3', NULL, 1761758823, 1761758823),
(39279, 'Numbers 20:12', 'Numbers', 20, 12, 'خو څښتن موسی او هارون ورټل او ورته ویې ویل: «څرنګه چې تاسو په ما باندې اعتماد ونه کړ چې د اسراییلو د خلکو په مخکې زما د پاک قدرت درناوی وکړئ، نو تاسو به ونه شئ کولای چې هغوی هغې خاورې ته بوځئ چې د هغې د ورکولو وعده مې د هغوی سره کړې ده.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_012.mp3', NULL, 1761758823, 1761758823),
(39280, 'Numbers 20:13', 'Numbers', 20, 13, 'دا پېښه په مریبه کې وشوه، یعنې هغه ځای چې اسراییلیانو په کې د څښتن په خلاف شکایت وکړ او څښتن هغوی ته خپل سپېڅلتوب وروښود.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_013.mp3', NULL, 1761758823, 1761758823),
(39281, 'Numbers 20:14', 'Numbers', 20, 14, 'موسی د قادش څخه د ادوم پاچا ته استازي ولېږل چې دا پیغام ورته ورسوي: «مونږ اسراییلیان ستاسو خپل خپلوان یو او تاسو خبر یئ چې په مونږ باندې څومره سختۍ تېرې شوې،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_014.mp3', NULL, 1761758823, 1761758823),
(39282, 'Numbers 20:15', 'Numbers', 20, 15, 'څنګه زمونږ نیکونه مصر ته لاړل او مونږ د ډېرو کلونو دپاره هلته اوسېدلو. مصریانو زمونږ د نیکونو او زمونږ سره بد چلند وکړ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_015.mp3', NULL, 1761758823, 1761758823),
(39283, 'Numbers 20:16', 'Numbers', 20, 16, 'او مونږ څښتن ته د مرستې دپاره فریاد وکړ. هغه زمونږ فریاد واورېد او فرښته یې راولېږله او مونږ یې د مصر څخه راوویستلو. اوس مونږ په قادش کې یو چې دا یو ښار دی چې ستاسو د سیمې سره سرحد لري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_016.mp3', NULL, 1761758823, 1761758823),
(39284, 'Numbers 20:17', 'Numbers', 20, 17, 'مهرباني وکړئ مونږ ته اجازه راکړئ چې ستاسو د هېواد څخه تېر شو. مونږ به خپله لاره نه پرېنږدو او ستاسو پټیو او د انګورو باغونو ته به نه ورننوځو او ستاسو د څاه ګانو څخه به هېڅ اوبه ونه څښو. مونږ به په لویه لاره باندې ځو، ترڅو ستاسو د سیمې څخه ووځو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_017.mp3', NULL, 1761758823, 1761758823),
(39285, 'Numbers 20:18', 'Numbers', 20, 18, 'خو ادومیانو په ځواب کې وویل: «نه، مونږ به تاسو پرېنږدو چې زمونږ د هېواد په لاره باندې لاړ شئ! او که چېرې تاسو د دې کار هڅه وکړئ، مونږ به ووځو او حمله به درباندې وکړو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_018.mp3', NULL, 1761758823, 1761758823),
(39286, 'Numbers 20:19', 'Numbers', 20, 19, 'د اسراییلو خلکو وویل: «مونږ به په لویه لاره باندې ځو او که مونږ یا زمونږ حیواناتو ستاسو اوبه وڅښلې، مونږ به یې بیه درکړو. مونږ یوازې غواړو چې تېر شو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_019.mp3', NULL, 1761758823, 1761758823),
(39287, 'Numbers 20:20', 'Numbers', 20, 20, 'خو ادومیانو بیا وویل: «مونږ یې نه منو!» او هغوی د یو قوي لښکر سره ووتل چې د اسراییلو په خلکو باندې حمله وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_020.mp3', NULL, 1761758823, 1761758823),
(39288, 'Numbers 20:21', 'Numbers', 20, 21, 'څرنګه چې ادومیانو اسراییلیانو ته اجازه ورنه کړه چې د هغوی د سیمې له لارې تېر شي، نو اسراییلیان بېرته ستانه شول او په بله لاره باندې لاړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_021.mp3', NULL, 1761758823, 1761758823),
(39289, 'Numbers 20:22', 'Numbers', 20, 22, 'د اسراییلو ټول قوم د قادش څخه لاړ او د هور غره ته ورسېدل،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_022.mp3', NULL, 1761758823, 1761758823),
(39290, 'Numbers 20:23', 'Numbers', 20, 23, 'یعنې د ادوم سرحد ته. په هغه ځای کې څښتن موسی او هارون ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_023.mp3', NULL, 1761758823, 1761758823),
(39291, 'Numbers 20:24', 'Numbers', 20, 24, '«هارون به هغې خاورې ته داخل نه شي چې د هغې د ورکولو وعده مې د اسراییلیانو سره کړې ده. هغه به مړ شي او د خپلو نیکونو سره به یوځای شي، ځکه چې تاسو دواړو په مریبه کې زما د حکم څخه سرغړونه وکړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_024.mp3', NULL, 1761758823, 1761758823),
(39292, 'Numbers 20:25', 'Numbers', 20, 25, 'هارون او د هغه زوی العازار درسره واخله او د هور د غره سرته یې وخېژوه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_025.mp3', NULL, 1761758823, 1761758823),
(39293, 'Numbers 20:26', 'Numbers', 20, 26, 'او په هغه ځای کې د هارون څخه د کاهنتوب کالي وباسه او العازار ته یې ورواغونده. هارون به هلته مړ شي او د خپلو نیکونو سره به یوځای شي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_026.mp3', NULL, 1761758823, 1761758823),
(39294, 'Numbers 20:27', 'Numbers', 20, 27, 'څه چې څښتن حکم کړی ؤ موسی هماغسې وکړل. ټول قوم ورته کتل چې هغوی د هور د غره سرته وختل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_027.mp3', NULL, 1761758823, 1761758823),
(39295, 'Numbers 20:28', 'Numbers', 20, 28, 'موسی د هارون څخه د کاهنتوب کالي لېرې کړل او د هغه زوی العازار ته یې ورواغوستل. هارون هلته د هور د غره په سر باندې مړ شو او موسی او العازار بېرته راښکته شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_028.mp3', NULL, 1761758823, 1761758823),
(39296, 'Numbers 20:29', 'Numbers', 20, 29, 'کله چې د اسراییلو ټول قوم خبر شو چې هارون مړ شوی دی، نو هغوی دېرش ورځې د هغه په مرګ باندې غم او ژړا وکړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers20_verse_029.mp3', NULL, 1761758823, 1761758823),
(39297, 'Hosea 4:1', 'Hosea', 4, 1, 'ای د اسراییلو خلکو، د څښتن خبرو ته غوږ ونیسئ. څښتن د دې وطن په اوسېدونکو باندې تور لګوي، ځکه چې په دې وطن کې نه وفاداري شته، نه مینه او دا خلک خدای نه پېژني.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea4_verse_001.mp3', NULL, 1761758823, 1761758823),
(39298, 'Hosea 4:2', 'Hosea', 4, 2, 'هغوی په نورو باندې لعنت وایي، دروغ وایي، قتل کوي، غلا کوي او زنا کوي. جرمونه زیاتیږي او د یو قتل پسې بل قتل کیږي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea4_verse_002.mp3', NULL, 1761758823, 1761758823),
(39299, 'Hosea 4:3', 'Hosea', 4, 3, 'نو له همدې امله به دا ځمکه وچه شي او هر ژوندی موجود، ټول ځنګلي حیوانات، مرغان او حتی ماهیان به هم مړه شي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea4_verse_003.mp3', NULL, 1761758823, 1761758823),
(39300, 'Hosea 4:4', 'Hosea', 4, 4, 'څښتن وایي: «هېڅوک دې په خلکو باندې تور نه لګوي او نه دې هغوی ملامتوي. زما ګیله ستاسو کاهنانو څخه ده.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea4_verse_004.mp3', NULL, 1761758823, 1761758823),
(39301, 'Hosea 4:5', 'Hosea', 4, 5, 'تاسو او پیغمبران شپه او ورځ خطاګانې کوئ. زه به ستاسو مور یعنې اسراییل تباه کړم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea4_verse_005.mp3', NULL, 1761758823, 1761758823),
(39302, 'Hosea 4:6', 'Hosea', 4, 6, 'زما قوم تباه دی، ځکه چې هغوی ما نه پېژني. تاسو کاهنانو زما د پېژندلو نه انکار کړی دی، نو زه به تاسو د خپلو کاهنانو په توګه ونه پېژنم. څرنګه چې تاسو زما قوانین هېر کړي دي، نو زه به هم ستاسو اولادونه هېر کړم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea4_verse_006.mp3', NULL, 1761758823, 1761758823),
(39303, 'Hosea 4:7', 'Hosea', 4, 7, 'هرڅومره چې تاسو کاهنان زیاتیږئ په هماغه اندازه زما په وړاندې ستاسو ګناهونه زیاتیږي، نو زه به ستاسو عزت په بې‌عزتۍ باندې بدل کړم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea4_verse_007.mp3', NULL, 1761758823, 1761758823),
(39304, 'Hosea 4:8', 'Hosea', 4, 8, 'کله چې خلک خپلې سوځېدونکې نذرانې راوړي، نو تاسو کاهنان ورباندې ځانونه مړوئ. کله چې خلک ګناه کوي، نو تاسو کاهنان خوشحالېږئ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea4_verse_008.mp3', NULL, 1761758823, 1761758823),
(39305, 'Hosea 4:9', 'Hosea', 4, 9, 'کوم کارونه چې تاسو کاهنان یې کوئ، نو خلک یې هم کوي او تاسو دواړو ته به د هغوی د بدو عملونو سزا درکړم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea4_verse_009.mp3', NULL, 1761758823, 1761758823),
(39306, 'Hosea 4:10', 'Hosea', 4, 10, 'تاسو به د قربانیو نه خپله برخه خورئ، خو بیا به هم وږي یئ. تاسو به زناکاري کوئ خو اولادونه به مو نه پیدا کیږي، ځکه چې زه مو پریښی یم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea4_verse_010.mp3', NULL, 1761758823, 1761758823),
(39307, 'Hosea 4:11', 'Hosea', 4, 11, 'د نورو خدایانو پیروي کول او شراب څښل که نوي یا زاړه وي، زما د خلکو عقل له منځه وړي!', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea4_verse_011.mp3', NULL, 1761758823, 1761758823),
(39308, 'Hosea 4:12', 'Hosea', 4, 12, 'زما خلک د لرګي د بتانو سره مشوره کوي! هغوی فکر کوي چې هغه د لرګي امسا کولای شي هغوی ته د راتلونکې په هکله یو څه ووایي! لکه د یوې فاحشې ښځې په شان چې بې لارې کیږي، دوی خپل ځانونه نورو خدایانو ته سپارلي دي او زه یې پریښی یم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea4_verse_012.mp3', NULL, 1761758823, 1761758823),
(39309, 'Hosea 4:13', 'Hosea', 4, 13, 'هغوی د غرونو په سرونو کې قربانۍ وړاندې کوي او په غونډیو، د څېړۍ ، سپېدار او چنار د ونو لاندې خوشبویئ سوځوي، ځکه چې ښایسته سیوری لري! نو له دې امله ستاسو لورګانې فاحشې شوې او ستاسو انږورګانې زنا کوي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea4_verse_013.mp3', NULL, 1761758823, 1761758823),
(39310, 'Hosea 4:14', 'Hosea', 4, 14, 'خو زه ستاسو لورګانو او انږورګانو ته د بدلمنتوب په خاطر سزا نه ورکوم. ځکه چې سړي د بتخانې فاحشو ته ورځي او د هغوی سره په زیارتونو کې قربانۍ وړاندې کوي. لکه چې یو متل دی: ‹کوم خلک چې عقل نه لري هغوی به تباه کیږي.›', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea4_verse_014.mp3', NULL, 1761758823, 1761758823),
(39311, 'Hosea 4:15', 'Hosea', 4, 15, 'که څه هم تاسو اسراییلیان زنا کوئ، خو د یهودا د ګناه سبب مه کېږئ. جلجال یا بیت‌آون ته د عبادت دپاره مه ځئ او هلته د ژوندي څښتن په نوم قسم مه خورئ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea4_verse_015.mp3', NULL, 1761758823, 1761758823),
(39312, 'Hosea 4:16', 'Hosea', 4, 16, 'د اسراییلو خلک د غویي په شان سرتمبه خلک دي. ایا څښتن کولای شي چې هغوی لکه د وریو په شان په څړځایونو کې ماړه کړي؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea4_verse_016.mp3', NULL, 1761758823, 1761758823),
(39313, 'Hosea 4:17', 'Hosea', 4, 17, 'د اسراییلو خلک د بتانو سره یوځای شوي دي. پرېږده چې هغوی په خپله لاره روان وي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea4_verse_017.mp3', NULL, 1761758823, 1761758823),
(39314, 'Hosea 4:18', 'Hosea', 4, 18, 'کله چې هغوی زیات شراب وڅښي، نو فاحشو پسې ورځي او د عزت څخه بې‌عزتي غوره ګڼي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea4_verse_018.mp3', NULL, 1761758823, 1761758823),
(39315, 'Hosea 4:19', 'Hosea', 4, 19, 'هغوی به داسې ورک شي لکه باد یې چې یوسي او بتانو ته د قربانیو په وړاندې کولو باندې به وشرمیږي.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea4_verse_019.mp3', NULL, 1761758823, 1761758823),
(39316, 'Leviticus 14:1', 'Leviticus', 14, 1, 'څښتن موسی ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_001.mp3', NULL, 1761758823, 1761758823),
(39317, 'Leviticus 14:2', 'Leviticus', 14, 2, '«دا قوانین د هغه کس د پاکېدلو په اړه دي چې د پوستکي د ساري ناروغۍ څخه روغ شوی وي. په هغه ورځ چې د هغه پاکوالی اعلانیږي، باید هغه کاهن ته راوستل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_002.mp3', NULL, 1761758823, 1761758823),
(39318, 'Leviticus 14:3', 'Leviticus', 14, 3, 'کاهن دې د کمپ څخه دباندې لاړ شي او هغه دې معاینه کړي. که چېرې هغه کس د پوستکي د ساري ناروغۍ څخه روغ شوی وي،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_003.mp3', NULL, 1761758823, 1761758823),
(39319, 'Leviticus 14:4', 'Leviticus', 14, 4, 'کاهن به داسې حکم وکړي چې دوه ژوندۍ پاکې مرغۍ، د سبر لږ لرګي، سور تار او د وېلني بوټی دې د پاکوالي د مراسمو دپاره راوړل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_004.mp3', NULL, 1761758823, 1761758823),
(39320, 'Leviticus 14:5', 'Leviticus', 14, 5, 'بیا به کاهن داسې حکم وکړي چې د دې مرغیو څخه دې یوه د خټو د لوښي دپاسه چې د چینې تازه اوبه په کې وي، حلاله شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_005.mp3', NULL, 1761758823, 1761758823),
(39321, 'Leviticus 14:6', 'Leviticus', 14, 6, 'هغه دې بله ژوندۍ مرغۍ د سبر د لرګي، سور تار او د وېلني د بوټي سره واخلي او د هغې مرغۍ په وینه کې دې غوټه کړي چې د تازه اوبو دپاسه حلاله شوې وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_006.mp3', NULL, 1761758823, 1761758823),
(39322, 'Leviticus 14:7', 'Leviticus', 14, 7, 'کاهن به اووه ځلې په هغه کس باندې چې د ساري ناروغۍ څخه پاکیږي، هغه وینه وشیندي او هغه به پاک اعلان کړي. بیا دې هغه ژوندۍ مرغۍ په صحرا کې خوشې کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_007.mp3', NULL, 1761758823, 1761758823),
(39323, 'Leviticus 14:8', 'Leviticus', 14, 8, 'کوم کس چې پاکیږي، هغه باید خپل کالي ووینځي، خپل ټول ویښتان دې وخرایي او غسل دې وکړي، بیا به هغه پاک شي. له دې وروسته هغه کولای شي چې کمپ ته ورننوځي، خو اووه ورځې باید د خپلې خېمې څخه دباندې واوسیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_008.mp3', NULL, 1761758823, 1761758823),
(39324, 'Leviticus 14:9', 'Leviticus', 14, 9, 'هغه باید په اوومه ورځ بیا خپل سر، ږیره، وروځې او د بدن پاتې ویښتان وخرایي. خپل کالي دې ووینځي او غسل دې وکړي، نو هغه به پاک شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_009.mp3', NULL, 1761758823, 1761758823),
(39325, 'Leviticus 14:10', 'Leviticus', 14, 10, 'هغه باید په اتمه ورځ دغه شیان راوړي: دوه وري او یوه یو کلنه مېږه چې هېڅ عیب په کې نه وي، د غلې دانې د نذرانې دپاره درې کیلو ګرامه ښه اوړه چې د زیتونو تېل ورسره ګډ وي او یوه پیاله د زیتونو تېل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_010.mp3', NULL, 1761758823, 1761758823),
(39326, 'Leviticus 14:11', 'Leviticus', 14, 11, 'کاهن باید هغه کس چې پاکیږي، د دې نذرانو سره د سپېڅلې خېمې د دروازې په خوله کې د څښتن حضور ته ورولي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_011.mp3', NULL, 1761758823, 1761758823),
(39327, 'Leviticus 14:12', 'Leviticus', 14, 12, 'بیا به کاهن یو وری د یوې پیالې تېلو سره واخلي او هغه به د تاوان د نذرانې په توګه وړاندې کړي. کاهن به هغه پورته ونیسي، ترڅو دا وښایي چې هغه څښتن ته وقف شوي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_012.mp3', NULL, 1761758823, 1761758823),
(39328, 'Leviticus 14:13', 'Leviticus', 14, 13, 'هغه دې وری په هغه سپېڅلي ځای کې حلال کړي چې د ګناه د نذرانو او سوځېدونکو نذرانو دپاره حیوانات حلالیږي. هغه باید داسې وکړي، ځکه چې د تاوان نذرانه د ګناه د نذرانې په شان د کاهن ده او هغه ډېره سپېڅلې ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_013.mp3', NULL, 1761758823, 1761758823),
(39329, 'Leviticus 14:14', 'Leviticus', 14, 14, 'کاهن دې د وري د وینې څخه لږه وینه واخلي او د هغه کس چې پاکیږي، د هغه د ښي غوږ په نرمۍ، د ښي لاس په غټې ګوتې او د ښي پښې په غټې ګوتې دې وسولوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_014.mp3', NULL, 1761758823, 1761758823),
(39330, 'Leviticus 14:15', 'Leviticus', 14, 15, 'بیا به کاهن لږ تېل راواخلي او د خپل چپ لاس په ورغوي کې به یې توی کړي،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_015.mp3', NULL, 1761758823, 1761758823),
(39331, 'Leviticus 14:16', 'Leviticus', 14, 16, 'خپله ښي ګوته به په خپل ورغوي کې غوټه کړي او لږ تېل به په خپلې ګوتې سره د څښتن په حضور کې اووه ځلې وشیندي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_016.mp3', NULL, 1761758823, 1761758823),
(39332, 'Leviticus 14:17', 'Leviticus', 14, 17, 'کاهن دې لږ تېل چې د هغه د لاس په ورغوي کې پاتې دي، راواخلي او د هغه کس چې پاکیږي د هغه د ښي غوږ په نرمۍ، د ښي لاس په غټې ګوتې او د ښي پښې په غټې ګوتې وسولوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_017.mp3', NULL, 1761758823, 1761758823),
(39333, 'Leviticus 14:18', 'Leviticus', 14, 18, 'کاهن به پاتې تېل چې د هغه په ورغوي کې دي، د هغه چا په سر باندې توی کړي چې پاکیږي او د هغه دپاره به د څښتن په حضور کې کفاره ادا کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_018.mp3', NULL, 1761758823, 1761758823),
(39334, 'Leviticus 14:19', 'Leviticus', 14, 19, 'بیا دې کاهن د ګناه نذرانه قرباني کړي او د هغه چا دپاره دې کفاره ادا کړي چې د خپلې ناپاکۍ څخه پاکیږي. له هغې وروسته به د سوځېدونکې نذرانې دپاره حیوان حلال کړي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_019.mp3', NULL, 1761758823, 1761758823),
(39335, 'Leviticus 14:20', 'Leviticus', 14, 20, 'او د غلې دانې د نذرانې سره به یې د قربانۍ په ځای باندې وړاندې کړي. په دې ډول به د هغه کس دپاره کفاره ادا کړي او هغه به پاک شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_020.mp3', NULL, 1761758823, 1761758823),
(39336, 'Leviticus 14:21', 'Leviticus', 14, 21, 'که چېرې هغه کس غریب وي او نور څه نه شي اخیستلی، باید یو وری د تاوان د نذرانې په توګه راوړي. کاهن به هغه څښتن ته د وقف کولو دپاره پورته ونیسي او د هغه کس دپاره به کفاره ادا کړي. هغه به یو کیلو ګرام ښه اوړه چې د زیتونو تېل ورسره ګډ وي، د غلې دانې د نذرانې دپاره راوړي او یوه پیاله تېل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_021.mp3', NULL, 1761758823, 1761758823),
(39337, 'Leviticus 14:22', 'Leviticus', 14, 22, 'همدارنګه هغه کس به دوه کوترې یا دوه قمري ګانې راوړي، یوه د ګناه د نذرانې دپاره او بله د سوځېدونکې نذرانې دپاره.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_022.mp3', NULL, 1761758823, 1761758823),
(39338, 'Leviticus 14:23', 'Leviticus', 14, 23, 'هغه باید په اتمه ورځ دا شیان د خپل ځان د پاکېدلو دپاره د سپېڅلې خېمې د دروازې په خوله کې کاهن ته راوړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_023.mp3', NULL, 1761758823, 1761758823),
(39339, 'Leviticus 14:24', 'Leviticus', 14, 24, 'کاهن به وری او د زیتونو تېل د تاوان د نذرانې دپاره واخلي او څښتن ته به یې د وقف کولو دپاره پورته ونیسي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_024.mp3', NULL, 1761758823, 1761758823),
(39340, 'Leviticus 14:25', 'Leviticus', 14, 25, 'هغه به وری د تاوان د نذرانې په توګه حلال کړي او د هغه لږه وینه به واخلي او د هغه کس چې پاکیږي، د ښي غوږ په نرمۍ، د ښي لاس په غټې ګوتې او د ښي پښې په غټې ګوتې به یې وسولوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_025.mp3', NULL, 1761758823, 1761758823),
(39341, 'Leviticus 14:26', 'Leviticus', 14, 26, 'بیا دې کاهن لږ تېل راواخلي او د خپل چپ لاس په ورغوي کې دې توی کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_026.mp3', NULL, 1761758823, 1761758823),
(39342, 'Leviticus 14:27', 'Leviticus', 14, 27, 'هغه دې په خپله ښي ګوته د خپل ورغوي څخه لږ تېل اووه ځلې د څښتن په حضور کې وشیندي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_027.mp3', NULL, 1761758823, 1761758823),
(39343, 'Leviticus 14:28', 'Leviticus', 14, 28, 'د خپل ورغوي څخه دې لږ تېل په هماغو ځایونو باندې وسولوي چې د تاوان د نذرانې وینه یې ورباندې سولولې وه، یعنې د هغه کس چې پاکیږي د هغه د ښي غوږ په نرمۍ، د ښي لاس په غټې ګوتې او د ښي پښې په غټې ګوتې دې هغه وسولوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_028.mp3', NULL, 1761758823, 1761758823),
(39344, 'Leviticus 14:29', 'Leviticus', 14, 29, 'کاهن به هغه تېل چې د هغه په ورغوي کې پاتې دي، د هغه کس په سر باندې چې پاکیږي، توی کړي او په دې ډول به د هغه دپاره د څښتن په حضور کې کفاره ادا کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_029.mp3', NULL, 1761758823, 1761758823),
(39345, 'Leviticus 14:32', 'Leviticus', 14, 32, 'دا مقررات د هغه چا دپاره دي چې د پوستکي په ساري ناروغۍ باندې اخته وي او د خپل ځان د پاکوالي دپاره هغه نذرانې چې رواج وې، نه شي اخیستلی.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_032.mp3', NULL, 1761758823, 1761758823),
(39346, 'Leviticus 14:33', 'Leviticus', 14, 33, 'څښتن موسی او هارون ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_033.mp3', NULL, 1761758823, 1761758823),
(39347, 'Leviticus 14:34', 'Leviticus', 14, 34, '«کله چې تاسو د کنعان خاورې ته چې تاسو ته یې ستاسو د ملکیت په توګه درکوم، ورننوځئ او که چېرې په تاسو کې څوک په یو کور کې یوه چڼاسکه چې ما درلېږلې ده پیدا کړي،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_034.mp3', NULL, 1761758823, 1761758823),
(39348, 'Leviticus 14:35', 'Leviticus', 14, 35, 'نو د هغه کور خاوند باید لاړ شي او کاهن ته دې داسې ووایي چې ما په خپل کور کې یو شی لیدلی دی چې د چڼاسکې په شان ښکاري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_035.mp3', NULL, 1761758823, 1761758823),
(39349, 'Leviticus 14:36', 'Leviticus', 14, 36, 'کاهن به داسې حکم وکړي چې مخکې له دې چې هغه د چڼاسکې د معاینه کولو دپاره لاړ شي، هرڅه دې د هغه کور څخه راوویستل شي. که نه، نو هرڅه چې په هغه کور کې دي، هغه به ناپاکه اعلان شي. له هغې وروسته دې کاهن دننه لاړ شي او کور دې معاینه کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_036.mp3', NULL, 1761758823, 1761758823),
(39350, 'Leviticus 14:37', 'Leviticus', 14, 37, 'هغه دې په دېوالونو باندې چڼاسکې معاینه کړي. که چېرې په هغه کې شین بخن یا سوربخن داغونه وي چې دېوال خرابوي،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_037.mp3', NULL, 1761758823, 1761758823),
(39351, 'Leviticus 14:38', 'Leviticus', 14, 38, 'نو کاهن به د هغه کور څخه لاړ شي او کور به د اوو ورځو دپاره بند کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_038.mp3', NULL, 1761758823, 1761758823),
(39352, 'Leviticus 14:39', 'Leviticus', 14, 39, 'په اوومه ورځ به کاهن بېرته راشي او هغه کور به بیا معاینه کړي. که چېرې چڼاسکه په دېوالونو باندې خپره شوې وي،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_039.mp3', NULL, 1761758823, 1761758823),
(39353, 'Leviticus 14:40', 'Leviticus', 14, 40, 'هغه دې حکم وکړي چې هغه تیږې چې چڼاسکې ورباندې پیدا شوې دي، هغه دې لېرې شي او د ښار څخه دې دباندې په یو ناپاک ځای کې وغورځول شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_040.mp3', NULL, 1761758823, 1761758823),
(39354, 'Leviticus 14:41', 'Leviticus', 14, 41, 'له هغې وروسته باید کاهن ټول دننني دېوالونه په یو چا باندې وتوږي او خاوره دې د ښار څخه دباندې په یو ناپاکه ځای کې وغورځوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_041.mp3', NULL, 1761758823, 1761758823),
(39355, 'Leviticus 14:42', 'Leviticus', 14, 42, 'بیا دې د هغو تیږو په ځای چې لېرې کړای شوې دي د نورو تیږو څخه کار واخیستل شي او دېوالونو ته دې نوی اخېړ ورکړای شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_042.mp3', NULL, 1761758823, 1761758823),
(39356, 'Leviticus 14:43', 'Leviticus', 14, 43, 'که چېرې د دېوالونو د تیږو د لېرې کولو، توږلو او اخېړولو نه وروسته بیا په هغه کور کې چڼاسکه راښکاره شي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_043.mp3', NULL, 1761758823, 1761758823),
(39357, 'Leviticus 14:44', 'Leviticus', 14, 44, 'نو کاهن دې لاړ شي او هغه دې بیا معاینه کړي. که چېرې په کور کې چڼاسکه خپره شوې وي، نو دا یوه خرابوونکې چڼاسکه ده او دا کور ناپاک دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_044.mp3', NULL, 1761758823, 1761758823),
(39358, 'Leviticus 14:45', 'Leviticus', 14, 45, 'هغه کور باید وران شي او د هغه تیږې، تیرونه او ټوله خاوره باید د ښار څخه دباندې یو ناپاکه ځای ته یووړل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_045.mp3', NULL, 1761758823, 1761758823),
(39359, 'Leviticus 14:46', 'Leviticus', 14, 46, 'په هغه دوران کې چې کاهن هغه کور بند اعلان کړی وي، نو هرڅوک چې هغه ته ننوځي، هغه به تر ماښامه پورې ناپاک وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_046.mp3', NULL, 1761758823, 1761758823),
(39360, 'Leviticus 14:47', 'Leviticus', 14, 47, 'همدارنګه هرڅوک چې په هغه کور کې خوب کوي یا خوراک کوي، باید خپل کالي ووینځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_047.mp3', NULL, 1761758823, 1761758823),
(39361, 'Leviticus 14:48', 'Leviticus', 14, 48, 'خو که چېرې کاهن راشي او هغه معاینه کړي، نو که د کور د اخېړولو څخه وروسته چڼاسکه خپره شوې نه وي، نو هغه به کور پاک اعلان کړي، ځکه چې چڼاسکه ورکه شوې ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_048.mp3', NULL, 1761758823, 1761758823),
(39362, 'Leviticus 14:49', 'Leviticus', 14, 49, 'هغه دې د کور د پاکولو دپاره دوه مرغۍ، د سبر لرګی، سور تار او د وېلني بوټی راواخلي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_049.mp3', NULL, 1761758823, 1761758823),
(39363, 'Leviticus 14:50', 'Leviticus', 14, 50, 'هغه به د دغو مرغیو څخه یوه د خټو د لوښي دپاسه چې د چینې تازه اوبه په کې وي، حلاله کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_050.mp3', NULL, 1761758823, 1761758823),
(39364, 'Leviticus 14:51', 'Leviticus', 14, 51, 'بیا دې د سبر لرګی، د وېلني بوټی، سور تار او ژوندۍ مرغۍ راواخلي او هغه دې د مړې مرغۍ په وینه او تازه اوبو کې غوټه کړي او په کور باندې دې اووه ځلې وشیندي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_051.mp3', NULL, 1761758823, 1761758823),
(39365, 'Leviticus 14:52', 'Leviticus', 14, 52, 'په دې ډول به کاهن هغه کور د مرغۍ په وینه، تازه اوبو، ژوندۍ مرغۍ، د سبر په لرګي، د وېلني په بوټي او سور تار باندې پاک کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_052.mp3', NULL, 1761758823, 1761758823),
(39366, 'Leviticus 14:53', 'Leviticus', 14, 53, 'بیا دې هغه ژوندۍ مرغۍ د ښار څخه دباندې په صحرا کې خوشې کړي. په دې ډول به هغه د کور دپاره د پاکوالي مراسم سرته ورسوي او هغه به پاک شي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_053.mp3', NULL, 1761758823, 1761758823),
(39367, 'Leviticus 14:54', 'Leviticus', 14, 54, 'دا مقررات د پوستکي د هرې ساري ناروغۍ دپاره دي لکه خارښت،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_054.mp3', NULL, 1761758823, 1761758823),
(39368, 'Leviticus 14:57', 'Leviticus', 14, 57, 'د دې مقرراتو له مخې دا پرېکړه کېدای شي چې یو شی په کوم وخت کې پاک دی او په کوم وخت کې ناپاک.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus14_verse_057.mp3', NULL, 1761758823, 1761758823),
(39369, 'Exodus 35:1', 'Exodus', 35, 1, 'موسی د اسراییلو ټول قوم سره راټول کړ او ورته ویې ویل: «دا د څښتن حکمونه دي چې تاسو به ورباندې عمل کوئ:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_001.mp3', NULL, 1761758823, 1761758823),
(39370, 'Exodus 35:2', 'Exodus', 35, 2, 'تاسو باید په هفته کې شپږ ورځې کار وکړئ، خو په اوومه ورځ چې د څښتن سپېڅلې ورځ ده، ارام وکړئ. هرڅوک چې په هغې ورځ کار وکړي، هغه دې ووژل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_002.mp3', NULL, 1761758823, 1761758823),
(39371, 'Exodus 35:3', 'Exodus', 35, 3, 'حتی د سبت په ورځ په خپلو کورونو کې اور هم مه بلوئ.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_003.mp3', NULL, 1761758823, 1761758823),
(39372, 'Exodus 35:4', 'Exodus', 35, 4, 'موسی د اسراییلو ټول قوم ته وویل: «څښتن داسې حکم کړی دی:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_004.mp3', NULL, 1761758823, 1761758823),
(39373, 'Exodus 35:5', 'Exodus', 35, 5, 'څه چې تاسو لرئ د هغو څخه د څښتن دپاره یوه نذرانه یوسئ. هرڅوک چې په خپله خوښه څښتن ته نذرانې راوړي، نو دا شیان دې راوړي: سره زر، سپین زر او برنج،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_005.mp3', NULL, 1761758823, 1761758823),
(39374, 'Exodus 35:6', 'Exodus', 35, 6, 'ښه کتان او ابي، بانجاني او سرې وړۍ، هغه ټوکر چې د وزو د وړیو څخه جوړ شوی وي،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_006.mp3', NULL, 1761758823, 1761758823),
(39375, 'Exodus 35:7', 'Exodus', 35, 7, 'سره رنګ شوي د پسه پوستکي، ښه څرمن، د اکاسۍ لرګی،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_007.mp3', NULL, 1761758823, 1761758823),
(39376, 'Exodus 35:8', 'Exodus', 35, 8, 'د څراغونو دپاره تېل، د مسح کولو د تېلو او د خوشبویۍ دپاره مسالې،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_008.mp3', NULL, 1761758823, 1761758823),
(39377, 'Exodus 35:9', 'Exodus', 35, 9, 'د عقیقو تیږې او نورې قیمتي تیږې چې د لوی کاهن په سپېڅلي پېشبند او د هغه په سینه پوښ باندې ولګول شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_009.mp3', NULL, 1761758823, 1761758823),
(39378, 'Exodus 35:10', 'Exodus', 35, 10, 'په تاسو کې چې څومره ماهر خلک دي، هغوی دې راشي او هغه ټول شیان دې جوړ کړي چې څښتن یې حکم کړی دی:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_010.mp3', NULL, 1761758823, 1761758823),
(39379, 'Exodus 35:11', 'Exodus', 35, 11, 'لکه سپېڅلې خېمه او د هغې پوښونه، چنګکونه، چوکاټونه، اړمونه، ستنې او پایې،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_011.mp3', NULL, 1761758823, 1761758823),
(39380, 'Exodus 35:12', 'Exodus', 35, 12, 'د لوظ صندوق او د هغه میلې او سرپوښ چې کفاره ورباندې ادا کیږي او پرده چې هغه ورباندې پټیږي،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_012.mp3', NULL, 1761758823, 1761758823),
(39381, 'Exodus 35:13', 'Exodus', 35, 13, 'مېز د پایو او ټول سامان سره او سپېڅلې ډوډۍ،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_013.mp3', NULL, 1761758823, 1761758823),
(39382, 'Exodus 35:14', 'Exodus', 35, 14, 'د رڼا دپاره څراغدان د هغه د سامان سره، د رڼا دپاره څراغونه او تېل،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_014.mp3', NULL, 1761758823, 1761758823),
(39383, 'Exodus 35:15', 'Exodus', 35, 15, 'د خوشبویۍ د سوځولو د قربانۍ ځای د هغې د میلو سره، د مسح کولو تېل او خوشبویي، د سپېڅلې خېمې د دروازې دپاره پرده،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_015.mp3', NULL, 1761758823, 1761758823),
(39384, 'Exodus 35:16', 'Exodus', 35, 16, 'د سوځېدونکې نذرانې د قربانۍ ځای او د هغه برنجي جالۍ، میلې او ټول لوښي، برنجي تشت د پایې سره،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_016.mp3', NULL, 1761758823, 1761758823),
(39385, 'Exodus 35:17', 'Exodus', 35, 17, 'د حوېلۍ پردې د هغو د ستنو او پایو سره او د حوېلۍ د دروازې دپاره پرده،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_017.mp3', NULL, 1761758823, 1761758823),
(39386, 'Exodus 35:18', 'Exodus', 35, 18, 'د خېمې او حوېلۍ دپاره موږي او رسۍ،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_018.mp3', NULL, 1761758823, 1761758823),
(39387, 'Exodus 35:19', 'Exodus', 35, 19, 'ښکلي کالي چې په سپېڅلي ځای کې د خدمت دپاره اغوستل کیږي، د هارون کاهن دپاره ځانګړي کالي او د هغه د زامنو دپاره کالي چې د کاهنۍ د خدمت په وخت کې یې اغوندي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_019.mp3', NULL, 1761758823, 1761758823),
(39388, 'Exodus 35:20', 'Exodus', 35, 20, 'بیا د اسراییلو ټول خلک د موسی د حضور څخه لاړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_020.mp3', NULL, 1761758823, 1761758823),
(39389, 'Exodus 35:21', 'Exodus', 35, 21, 'بیا هغو خلکو چې زړونو یې غوښتل چې څښتن ته نذرانې راوړي، نو هغه یې راوړلې چې په سپېڅلې خېمه، د عبادت په خدمتونو او د کاهنانو د کالیو په جوړولو کې ورڅخه کار واخیستل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_021.mp3', NULL, 1761758823, 1761758823),
(39390, 'Exodus 35:22', 'Exodus', 35, 22, 'نو ټول خلک یعنې نارینه او ښځې په خپله خوښه راغلل او هغوی د سینې ګلان، غوږوالۍ، ګوتې او غاړه کۍ او هر ډول د سرو زرو ګاڼې راوړلې او څښتن ته یې وقف کړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_022.mp3', NULL, 1761758823, 1761758823),
(39391, 'Exodus 35:23', 'Exodus', 35, 23, 'د هرچا سره چې ابي، بانجاني یا سرې وړۍ، ښه کتان، د وزو د وړیو څخه جوړ شوی ټوکر، سره رنګ شوي د پسه پوستکي یا ښې څرمنې وې، هغه یې راوړلې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_023.mp3', NULL, 1761758823, 1761758823),
(39392, 'Exodus 35:24', 'Exodus', 35, 24, 'د چا سره چې سپین زر یا برنج او یا د اکاسۍ لرګي وو، هغه یې راوړل او څښتن ته یې د سوغات په توګه وړاندې کړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_024.mp3', NULL, 1761758823, 1761758823),
(39393, 'Exodus 35:25', 'Exodus', 35, 25, 'هغو ټولو ښځو چې د ګنډلو او اوبدلو په کار کې یې مهارت درلود ابي، بانجاني یا سرې وړۍ یا ښه کتان چې هغوی په خپله جوړ کړي وو، راوړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_025.mp3', NULL, 1761758823, 1761758823),
(39394, 'Exodus 35:26', 'Exodus', 35, 26, 'ټولو ښځو چې زړونو یې غوښتل او مهارت یې درلود، هغوی به د وزو د وړیو څخه تارونه جوړول او اوبدل به یې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_026.mp3', NULL, 1761758823, 1761758823),
(39395, 'Exodus 35:27', 'Exodus', 35, 27, 'مشرانو د عقیقو تیږې او نور غمي راوړل چې په سپېڅلي پېشبند او سینه پوښ باندې ولګول شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_027.mp3', NULL, 1761758823, 1761758823),
(39396, 'Exodus 35:28', 'Exodus', 35, 28, 'همدارنګه هغوی د څراغونو دپاره تېل راوړل او خوشبویه مسالې یې راوړلې چې د خوشبویۍ او مسح کولو د تېلو سره ګډ شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_028.mp3', NULL, 1761758823, 1761758823),
(39397, 'Exodus 35:29', 'Exodus', 35, 29, 'د اسراییلو ټولو نارینه او ښځو چې غوښتل یې د هغه کار دپاره د خپلې خوښې نذرانې راوړلې چې څښتن د موسی په وسیله هغوی ته حکم کړی ؤ، چې هغه وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_029.mp3', NULL, 1761758823, 1761758823),
(39398, 'Exodus 35:30', 'Exodus', 35, 30, 'بیا موسی اسراییلیانو ته وویل: «ګورئ، څښتن بزل ییل د اوري زوی او د حور لمسی د یهودا له قبیلې څخه غوره کړی دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_030.mp3', NULL, 1761758823, 1761758823),
(39399, 'Exodus 35:31', 'Exodus', 35, 31, 'څښتن هغه د خپل روح څخه ډک کړی دی او په هر ډول هنري کار کې یې ورته مهارت، توان او پوهه ورکړې ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_031.mp3', NULL, 1761758823, 1761758823),
(39400, 'Exodus 35:32', 'Exodus', 35, 32, 'هغه کولای شي چې د سرو زرو، سپینو زرو او برنجو څخه ښکلي شیان جوړ کړي،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_032.mp3', NULL, 1761758823, 1761758823),
(39401, 'Exodus 35:33', 'Exodus', 35, 33, 'تیږې پرې کړي او تیارې یې کړي، د لرګیو کار او هر ډول هنري کار وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_033.mp3', NULL, 1761758823, 1761758823),
(39402, 'Exodus 35:34', 'Exodus', 35, 34, 'څښتن هغه او د دان د قبیلې د اخیسامک زوی اهولیاب دواړو ته دا توان ورکړی دی چې نورو ته خپل هنر ورزده کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_034.mp3', NULL, 1761758823, 1761758823),
(39403, 'Exodus 35:35', 'Exodus', 35, 35, 'هغه ورته په هر ډول کار کې مهارت ورکړی دی چې د زرګرانو، نقشه جوړوونکو، د ابي، بانجاني او سرو وړیو او د ښه کتان د ګلدوزانو او اوبدونکو په توګه کار وکړي. هغوی کولای شي چې هر ډول کارونه وکړي او هغوی تکړه نقشه جوړوونکي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus35_verse_035.mp3', NULL, 1761758823, 1761758823),
(39404, 'Malachi 1:1', 'Malachi', 1, 1, 'دا هغه پېغام دے کوم چې مالِک خُدائ د ملاکى په وسيله بنى اِسرائيلو له ورکړو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/malachi1_verse_001.mp3', NULL, 1761758823, 1761758823),
(39405, 'Malachi 1:2', 'Malachi', 1, 2, '”ما تاسو سره مينه کړې ده،“ مالِک خُدائ فرمائى. ”خو تاسو تپوس کوئ چې، تا مونږ سره څنګه مينه کړې ده؟“ مالِک خُدائ په جواب کښې وفرمائيل، ”آيا عِيسو د يعقوب ورور نۀ وو څۀ؟ بيا هم ما يعقوب سره مينه وکړه،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/malachi1_verse_002.mp3', NULL, 1761758823, 1761758823),
(39406, 'Malachi 1:3', 'Malachi', 1, 3, 'خو عِيسو يعنې د ادوميانو پلار نيکۀ ما رد کړو، او ما د هغوئ غرونه شاړ کړل او د هغوئ ميراث مې د بيابان ګيدړانو ته پرېښودلو.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/malachi1_verse_003.mp3', NULL, 1761758823, 1761758823),
(39407, 'Malachi 1:4', 'Malachi', 1, 4, 'ادوميان وائى چې، ”اګر کۀ مونږ تباه کړے شوى يُو، خو مونږ به دا کنډرې بيا جوړې کړُو.“ خو مالِک خُدائ ربُ الافواج دا فرمائى چې، ”هغوئ دا جوړولے شى، خو زۀ به يې تباه کړم. دې ته به د بدعملۍ مُلک وئيلے کيږى، او خلق به يې همېشه د خُدائ پاک د لعنت لاندې وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/malachi1_verse_004.mp3', NULL, 1761758823, 1761758823),
(39408, 'Malachi 1:5', 'Malachi', 1, 5, 'کله چې تاسو دا تباهى په خپلو سترګو وګورئ نو وبه وايئ چې، مالِک خُدائ د اِسرائيل د سرحدونو نه بهر هم خپله لوئى ښکاره کوى.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/malachi1_verse_005.mp3', NULL, 1761758823, 1761758823),
(39409, 'Malachi 1:6', 'Malachi', 1, 6, 'مالِک خُدائ ربُ الافواج اِمامانو ته فرمائى چې، ”يو زوئ د خپل پلار عزت کوى، او نوکر د خپل مالِک. کۀ چرې زۀ پلار يم، نو زما هغه عزت چرته دے؟ کۀ چرې زۀ مالِک يم، نو زما هغه احترام چرته دے؟ اے اِمامانو، خو دا تاسو يئ چې زما د نوم سپکاوے کوئ. خو تاسو تپوس کوئ چې، مونږ څنګه ستا د نوم سپکاوے کړے دے؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/malachi1_verse_006.mp3', NULL, 1761758823, 1761758823),
(39410, 'Malachi 1:7', 'Malachi', 1, 7, 'تاسو زما په قربان‌ګاه ناپاکه خوراک کېښودو. او بيا هم تاسو تپوس کوئ چې تۀ مونږ په څۀ ناپاک کړے يې؟ په دې چې تاسو ووئيل چې د مالِک خُدائ قربان‌ګاه ناپاکه ده زما د قربان ګاه سپکاوے مو وکړو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/malachi1_verse_007.mp3', NULL, 1761758823, 1761758823);